function recipientPolicyDisplay(policy: RecipientPolicy): string {
  switch (policy) {
    case 'allow':
      return 'Allowed';
    case 'block':
      return 'Blocked';
    case 'known':
      return 'Known';
  }
}

function savedRecipientById(id: string): SavedRecipient | undefined {
  return state.recipientRules.recipients.find((recipient) => recipient.id === id);
}

function savedRecipientForAddress(address: string): SavedRecipient | undefined {
  const normalized = address.trim();
  if (!normalized) return undefined;
  return state.recipientRules.recipients.find((recipient) => recipient.address === normalized);
}

function recipientDisplayLabel(address: string): string {
  const normalized = address.trim();
  if (!normalized) return 'n/a';
  const recipient = savedRecipientForAddress(normalized);
  return recipient ? `${recipient.name} (${short(normalized)})` : short(normalized);
}

function recipientPolicyStatus(address: string): RecipientPolicyStatus {
  const normalized = address.trim();
  const recipient = savedRecipientForAddress(normalized);
  const blocked = Boolean(recipient && recipient.policy === 'block' && state.recipientRules.blockListEnabled);
  const allowed = Boolean(recipient && recipient.policy === 'allow');
  const allowRequired = Boolean(
    state.recipientRules.allowListEnabled &&
      normalized &&
      (!recipient || recipient.policy !== 'allow'),
  );
  const name = recipient?.name ?? short(normalized);
  if (!normalized) {
    return {
      address: '',
      known: false,
      allowed: false,
      blocked: false,
      allowRequired: false,
      label: 'Recipient not set',
      title: 'Recipient not set',
    };
  }
  if (blocked) {
    return {
      address: normalized,
      ...(recipient && { recipient }),
      known: Boolean(recipient),
      allowed,
      blocked,
      allowRequired: false,
      label: `${name} is blocked`,
      title: recipientPolicyBlockReason(normalized) ?? `${name} is blocked.`,
    };
  }
  if (allowRequired) {
    return {
      address: normalized,
      ...(recipient && { recipient }),
      known: Boolean(recipient),
      allowed,
      blocked: false,
      allowRequired,
      label: `${name} not on allow list`,
      title: recipientPolicyBlockReason(normalized) ?? `${name} is not on allow list.`,
    };
  }
  if (recipient && allowed) {
    return {
      address: normalized,
      recipient,
      known: true,
      allowed,
      blocked: false,
      allowRequired: false,
      label: `${recipient.name} allowed`,
      title: `${recipient.name} is on the allow list.`,
    };
  }
  if (recipient) {
    return {
      address: normalized,
      recipient,
      known: true,
      allowed: false,
      blocked: false,
      allowRequired: false,
      label: `${recipient.name} saved`,
      title: `${recipient.name} is saved as a known recipient.`,
    };
  }
  return {
    address: normalized,
    known: false,
    allowed: false,
    blocked: false,
    allowRequired: false,
    label: 'Unsaved recipient',
    title: 'This recipient is not saved.',
  };
}

function recipientPolicyBlockReason(address: string): string | null {
  const normalized = address.trim();
  if (!normalized || !state.recipientRules.enabled) return null;
  const recipient = savedRecipientForAddress(normalized);
  if (state.recipientRules.blockListEnabled && recipient?.policy === 'block') {
    return `${recipient.name} is on your block list. Remove or allow this recipient before approving.`;
  }
  if (state.recipientRules.allowListEnabled && recipient?.policy !== 'allow') {
    return recipient
      ? `${recipient.name} is saved but not on your allow list. Move it to allow list or turn off allow-list checks.`
      : `${short(normalized)} is not on your allow list. Save it as allowed or turn off allow-list checks.`;
  }
  return null;
}

function actionRecipientPolicyBlockReason(action: PreparedAction): string | null {
  return recipientPolicyBlockReason(recipientParam(action));
}

function isRecipientFieldId(fieldId: string): boolean {
  return fieldId === 'recipient' || fieldId === 'recipientAddress' || fieldId === 'settlementWallet';
}

function updateRecipientDraftField(field: HTMLInputElement | HTMLSelectElement): void {
  const key = field.dataset.recipientField;
  if (key === 'name' || key === 'address' || key === 'note' || key === 'tags') {
    state.recipientDraft[key] = field.value;
    delete state.recipientErrors[key];
    return;
  }
  if (key === 'isMine' && field instanceof HTMLInputElement) {
    state.recipientDraft.isMine = field.checked;
    return;
  }
  if (key === 'policy' && isRecipientPolicy(field.value)) {
    state.recipientDraft.policy = field.value;
  }
}

function applyRecipientSelection(select: HTMLSelectElement): void {
  const recipientId = select.value;
  if (recipientId === '__manual__') return;
  const recipient = savedRecipientById(recipientId);
  if (!recipient) return;
  const target = select.dataset.recipientSelect;
  const fieldId = select.dataset.recipientTargetField || 'recipient';
  if (target === 'template') {
    state.templateFields[fieldId] = recipient.address;
    delete state.templateFieldErrors[fieldId];
    state.agentPlan = null;
    state.agentSignature = '';
    state.agentPreparedActionId = '';
    render();
    return;
  }
  if (target === 'recurring') {
    state.recurringDraft = readRecurringDraft();
    state.recurringDraft.recipient = recipient.address;
    delete state.recurringErrors.recurringRecipient;
    render();
  }
}

function updateAgentPolicyDraftField(field: HTMLInputElement | HTMLSelectElement): void {
  const key = field.dataset.agentPolicyField;
  if (key === 'label' || key === 'detail' || key === 'paramValue') {
    state.agentPolicyDraft[key] = field.value;
    delete state.agentPolicyErrors[key];
    delete state.agentPolicyErrors._form;
    return;
  }
  if (key === 'kind' && isAgentPolicyKind(field.value)) {
    state.agentPolicyDraft.kind = field.value;
    state.agentPolicyDraft.paramValue = '';
    delete state.agentPolicyErrors.paramValue;
    delete state.agentPolicyErrors._form;
    render();
  }
}

function handleAgentPolicyAction(button: HTMLButtonElement): void {
  const action = button.dataset.agentPolicyAction;
  if (action === 'save') {
    saveAgentPolicyDraft();
    return;
  }
  if (action === 'reset') {
    state.agentPolicyDraft = defaultAgentPolicyDraft();
    state.agentPolicyErrors = {};
    render();
    return;
  }
  const policyId = button.dataset.agentPolicyId;
  if (!policyId) return;
  if (action === 'toggle') {
    toggleAgentPolicy(policyId);
    return;
  }
  if (action === 'delete') {
    deleteAgentPolicy(policyId);
  }
}

function saveAgentPolicyDraft(): void {
  const draft = {
    ...state.agentPolicyDraft,
    label: state.agentPolicyDraft.label.trim(),
    detail: state.agentPolicyDraft.detail.trim(),
    paramValue: state.agentPolicyDraft.paramValue.trim(),
  };
  const errors: Record<string, string> = {};
  if (!draft.label) errors.label = 'A short label is required.';
  if ((draft.kind === 'slippage_max' || draft.kind === 'amount_max') && draft.paramValue && Number.isNaN(Number(draft.paramValue))) {
    errors.paramValue = 'Use a number for this rule.';
  }
  if ((draft.kind === 'token_allow' || draft.kind === 'token_block' || draft.kind === 'slippage_max' || draft.kind === 'amount_max' || draft.kind === 'custom') && !draft.paramValue) {
    errors.paramValue = 'Add a value the agent should reason about.';
  }
  state.agentPolicyErrors = errors;
  if (Object.keys(errors).length > 0) {
    render();
    return;
  }
  const now = new Date().toISOString();
  const policy: UserAgentPolicy = {
    id: newId('agent-policy'),
    label: draft.label,
    kind: draft.kind,
    enabled: true,
    detail: draft.detail,
    ...(draft.paramValue ? { params: { value: draft.paramValue } } : {}),
    createdAt: now,
    updatedAt: now,
  };
  state.agentPolicies = [policy, ...state.agentPolicies];
  state.agentPolicyDraft = defaultAgentPolicyDraft();
  state.agentPolicyErrors = {};
  saveAgentPolicies();
  pushToast('success', 'Agent policy saved', `Saved "${policy.label}".`);
  render();
}

function toggleAgentPolicy(policyId: string): void {
  const now = new Date().toISOString();
  let toggled = false;
  state.agentPolicies = state.agentPolicies.map((policy) => {
    if (policy.id !== policyId) return policy;
    toggled = true;
    return { ...policy, enabled: !policy.enabled, updatedAt: now };
  });
  if (toggled) {
    saveAgentPolicies();
    render();
  }
}

function deleteAgentPolicy(policyId: string): void {
  const before = state.agentPolicies.length;
  state.agentPolicies = state.agentPolicies.filter((policy) => policy.id !== policyId);
  if (state.agentPolicies.length === before) return;
  saveAgentPolicies();
  pushToast('success', 'Agent policy deleted', 'The policy will no longer be sent to the agent.');
  render();
}

function updateCustomTokenDraftField(field: HTMLInputElement): void {
  const key = field.dataset.customTokenField;
  if (key === 'mint' || key === 'symbol' || key === 'decimals' || key === 'label') {
    state.customTokenDraft[key] = field.value;
    delete state.customTokenErrors[key];
  }
}

function handleCustomTokenAction(button: HTMLButtonElement): void {
  const action = button.dataset.customTokenAction;
  if (action === 'save') {
    saveCustomTokenDraft();
    return;
  }
  if (action === 'reset') {
    state.customTokenDraft = defaultCustomTokenDraft();
    state.customTokenErrors = {};
    render();
    return;
  }
  const tokenId = button.dataset.customTokenId;
  if (!tokenId) return;
  if (action === 'delete') {
    deleteCustomToken(tokenId);
    return;
  }
  if (action === 'edit') {
    editCustomToken(tokenId);
  }
}

function saveCustomTokenDraft(): void {
  const draft = {
    mint: state.customTokenDraft.mint.trim(),
    symbol: state.customTokenDraft.symbol.trim(),
    decimals: state.customTokenDraft.decimals.trim(),
    label: state.customTokenDraft.label.trim(),
  };
  const errors: Record<string, string> = {};
  if (!draft.mint) {
    errors.mint = 'Mint address is required.';
  } else if (!isSolanaPublicKeyText(draft.mint)) {
    errors.mint = 'Use a valid Solana mint address.';
  }
  if (!draft.symbol) errors.symbol = 'Symbol is required.';
  const decimalsNum = Number(draft.decimals);
  if (!draft.decimals || !Number.isFinite(decimalsNum) || decimalsNum < 0 || decimalsNum > 18 || !Number.isInteger(decimalsNum)) {
    errors.decimals = 'Use an integer between 0 and 18.';
  }
  state.customTokenErrors = errors;
  if (Object.keys(errors).length > 0) {
    render();
    return;
  }
  const now = new Date().toISOString();
  const existing = customTokenByMint(draft.mint);
  const token: CustomToken = {
    id: existing?.id ?? newId('custom-token'),
    mint: draft.mint,
    symbol: draft.symbol.slice(0, 12),
    decimals: decimalsNum,
    ...(draft.label ? { label: draft.label.slice(0, 64) } : {}),
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
  };
  state.customTokens = [token, ...state.customTokens.filter((entry) => entry.id !== token.id)];
  state.customTokenDraft = defaultCustomTokenDraft();
  state.customTokenErrors = {};
  saveCustomTokens();
  pushToast('success', 'Token saved', `${token.symbol} (${shortHexMint(token.mint)})`);
  render();
}

function deleteCustomToken(tokenId: string): void {
  const token = state.customTokens.find((entry) => entry.id === tokenId);
  state.customTokens = state.customTokens.filter((entry) => entry.id !== tokenId);
  saveCustomTokens();
  pushToast('success', 'Token removed', token?.symbol ?? tokenId);
  render();
}

function editCustomToken(tokenId: string): void {
  const token = state.customTokens.find((entry) => entry.id === tokenId);
  if (!token) return;
  state.customTokenDraft = {
    mint: token.mint,
    symbol: token.symbol,
    decimals: String(token.decimals),
    label: token.label ?? '',
  };
  state.customTokenErrors = {};
  render();
}

function updateAgentDraftField(field: HTMLInputElement | HTMLSelectElement): void {
  const key = field.dataset.agentField;
  if (key === 'label' || key === 'notes') {
    state.agentDraft[key] = field.value;
    delete state.agentErrors[key];
    delete state.agentErrors._form;
    return;
  }
  if (key === 'tier' && (field.value === 'read_only' || field.value === 'capped' || field.value === 'full')) {
    state.agentDraft.tier = field.value;
  }
}

function handleAgentAction(button: HTMLButtonElement): void {
  const action = button.dataset.agentAction;
  if (action === 'reset') {
    state.agentDraft = defaultAgentDraft();
    state.agentErrors = {};
    render();
    return;
  }
  if (action === 'issue') {
    void issueAgentDraft();
    return;
  }
  if (action === 'dismiss-reveal') {
    state.agentReveal = null;
    render();
    return;
  }
  const agentId = button.dataset.agentId;
  if (!agentId) return;
  if (action === 'toggle') {
    toggleAgent(agentId);
    return;
  }
  if (action === 'tier') {
    const tier = button.dataset.agentTier;
    if (tier === 'read_only' || tier === 'capped' || tier === 'full') {
      setAgentTier(agentId, tier);
    }
    return;
  }
  if (action === 'delete') {
    deleteAgent(agentId);
  }
}

async function issueAgentDraft(): Promise<void> {
  const draft = {
    label: state.agentDraft.label.trim(),
    tier: state.agentDraft.tier,
    notes: state.agentDraft.notes.trim(),
  };
  const errors: Record<string, string> = {};
  if (!draft.label) errors.label = 'Label is required.';
  state.agentErrors = errors;
  if (Object.keys(errors).length > 0) {
    render();
    return;
  }
  const issued = await issueAgentViaBridge(draft);
  if (!issued) {
    render();
    return;
  }
  state.agents = [issued, ...state.agents.filter((entry) => entry.id !== issued.id)];
  state.agentDraft = defaultAgentDraft();
  state.agentErrors = {};
  state.agentReveal = {
    agentId: issued.id,
    label: issued.label,
    token: issued.token,
    tier: issued.tier,
  };
  saveAgents();
  pushToast('success', 'Agent token issued', `${issued.label} (${agentTierLabel(issued.tier)})`);
  render();
}

function toggleAgent(agentId: string): void {
  const agent = agentById(agentId);
  if (!agent) return;
  state.agents = state.agents.map((entry) =>
    entry.id === agentId ? { ...entry, enabled: !entry.enabled } : entry,
  );
  saveAgents();
  void syncAgentsToBridge();
  pushToast('success', agent.enabled ? 'Agent paused' : 'Agent resumed', agent.label);
  render();
}

function setAgentTier(agentId: string, tier: AgentTier): void {
  const agent = agentById(agentId);
  if (!agent || agent.tier === tier) return;
  state.agents = state.agents.map((entry) =>
    entry.id === agentId ? { ...entry, tier } : entry,
  );
  saveAgents();
  void syncAgentsToBridge();
  pushToast('success', 'Agent tier updated', `${agent.label} → ${agentTierLabel(tier)}`);
  render();
}

function deleteAgent(agentId: string): void {
  const agent = agentById(agentId);
  if (!agent) return;
  state.agents = state.agents.filter((entry) => entry.id !== agentId);
  saveAgents();
  void syncAgentsToBridgeAfterDelete(agentId);
  pushToast('success', 'Agent revoked', agent.label);
  render();
}

async function syncAgentsToBridgeAfterDelete(agentId: string): Promise<void> {
  if (!state.bridgeActive || !state.bridgeUrl || !state.bridgeToken) return;
  try {
    await bridgeRequest('/bridge/agents/delete', {
      method: 'POST',
      body: JSON.stringify({ agentId }),
    });
  } catch {
    // Best-effort.
  }
  await syncAgentsToBridge();
}

function handleRecipientAction(button: HTMLButtonElement): void {
  const action = button.dataset.recipientAction;
  if (action === 'save') {
    saveRecipientDraft();
    return;
  }
  if (action === 'reset') {
    state.recipientDraft = defaultRecipientDraft();
    state.recipientErrors = {};
    render();
    return;
  }
  const recipientId = button.dataset.recipientId;
  if (!recipientId) return;
  if (action === 'delete') {
    deleteSavedRecipient(recipientId);
    return;
  }
  if (action === 'policy') {
    const policy = button.dataset.recipientPolicy;
    if (isRecipientPolicy(policy)) {
      updateSavedRecipientPolicy(recipientId, policy);
    }
    return;
  }
  if (action === 'use') {
    useSavedRecipient(recipientId);
    return;
  }
  if (action === 'toggle-mine') {
    toggleRecipientIsMine(recipientId);
  }
}

function handleConnectedDappAction(button: HTMLButtonElement): void {
  const action = button.dataset.connectedDappAction;
  if (!action) return;
  const id = action === 'add-selected'
    ? (document.querySelector<HTMLSelectElement>('[data-connected-dapp-catalog]')?.value as ConnectedDappId | undefined)
    : button.dataset.connectedDappId as ConnectedDappId | undefined;
  if (!id) return;
  const adapter = getAdapterMeta(id);
  if (!adapter) return;
  if (action === 'toggle' || action === 'add-selected') {
    if (!isClusterSupported(adapter, state.cluster)) {
      pushToast(
        'error',
        `${adapter.name} unavailable here`,
        `${adapter.name} is only available on ${adapter.supportedClusters.join(', ')}.`,
      );
      return;
    }
    const next = action === 'add-selected' ? true : button.dataset.connectedDappNext === 'on';
    const updated = setConnectedDappEnabled(state.connectedDapps, id, next);
    state.connectedDapps = updated;
    saveConnectedDapps(updated);
    void syncCloudPreference('protocol-connectors');
    pushToast(
      'success',
      next ? `${adapter.name} enabled` : `${adapter.name} disabled`,
      next
        ? `Agent can now use ${adapter.capabilities.map((capability) => capability.replace(/_/g, ' ')).join(' / ')} when available.`
        : `Agent will refuse ${adapter.name} connector actions until re-enabled.`,
    );
    render();
  }
}

function updateProtocolConnectorPref(field: HTMLInputElement): void {
  const key = field.dataset.protocolConnectorPref;
  if (key === 'dialectClientKey') {
    state.protocolConnectorPrefs.dialectClientKey = field.value.slice(0, 160);
    saveProtocolConnectorPrefs();
  }
}

function saveRecipientDraft(): void {
  const draft = {
    ...state.recipientDraft,
    name: state.recipientDraft.name.trim(),
    address: state.recipientDraft.address.trim(),
    note: state.recipientDraft.note.trim(),
    tags: state.recipientDraft.tags.trim(),
  };
  const errors: Record<string, string> = {};
  if (!draft.name) errors.name = 'Name is required.';
  if (!draft.address) {
    errors.address = 'Address is required.';
  } else if (!isSolanaPublicKeyText(draft.address)) {
    errors.address = 'Use a valid Solana address.';
  }
  state.recipientErrors = errors;
  if (Object.keys(errors).length > 0) {
    render();
    return;
  }
  const now = new Date().toISOString();
  const existing = savedRecipientForAddress(draft.address);
  const tags = draft.tags
    ? draft.tags
        .split(',')
        .map((tag) => tag.trim())
        .filter((tag) => tag.length > 0)
        .slice(0, 8)
    : [];
  const recipient: SavedRecipient = {
    id: existing?.id ?? newId('recipient'),
    name: draft.name.slice(0, 48),
    address: draft.address,
    policy: draft.policy,
    ...(draft.note ? { note: draft.note.slice(0, 140) } : {}),
    ...(tags.length ? { tags } : {}),
    ...(draft.isMine ? { isMine: true } : {}),
    ...(existing?.lastUsedAt ? { lastUsedAt: existing.lastUsedAt } : {}),
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
  };
  state.recipientRules = {
    ...state.recipientRules,
    enabled: true,
    allowListEnabled: state.recipientRules.allowListEnabled || recipient.policy === 'allow',
    blockListEnabled: state.recipientRules.blockListEnabled || recipient.policy === 'block',
    recipients: mergeSavedRecipients([recipient, ...state.recipientRules.recipients.filter((entry) => entry.id !== recipient.id)]),
  };
  state.recipientDraft = defaultRecipientDraft();
  state.recipientErrors = {};
  saveRecipientRules();
  pushToast('success', 'Recipient saved', `${recipient.name} - ${recipientPolicyDisplay(recipient.policy)}`);
  render();
}

function deleteSavedRecipient(recipientId: string): void {
  const recipient = savedRecipientById(recipientId);
  state.recipientRules.recipients = state.recipientRules.recipients.filter((entry) => entry.id !== recipientId);
  saveRecipientRules();
  pushToast('success', 'Recipient removed', recipient?.name ?? recipientId);
  render();
}

function updateSavedRecipientPolicy(recipientId: string, policy: RecipientPolicy): void {
  const now = new Date().toISOString();
  const recipient = savedRecipientById(recipientId);
  if (!recipient) return;
  state.recipientRules = {
    ...state.recipientRules,
    enabled: true,
    allowListEnabled: state.recipientRules.allowListEnabled || policy === 'allow',
    blockListEnabled: state.recipientRules.blockListEnabled || policy === 'block',
    recipients: mergeSavedRecipients(state.recipientRules.recipients.map((entry) =>
      entry.id === recipientId ? { ...entry, policy, updatedAt: now } : entry,
    )),
  };
  saveRecipientRules();
  pushToast('success', 'Recipient updated', `${recipient.name} - ${recipientPolicyDisplay(policy)}`);
  render();
}

function useSavedRecipient(recipientId: string): void {
  const recipient = savedRecipientById(recipientId);
  if (!recipient) return;
  if (state.activeTab === 'schedule') {
    state.recurringDraft.recipient = recipient.address;
    state.recurringView = 'create';
    delete state.recurringErrors.recurringRecipient;
  } else {
    const template = selectedTemplate();
    const field = template.fields.find((candidate) => isRecipientFieldId(candidate.id));
    if (field) {
      state.templateFields[field.id] = recipient.address;
      delete state.templateFieldErrors[field.id];
      state.activeTab = 'agent';
      state.oneTimePlanView = 'create';
      state.agentPlan = null;
      state.agentSignature = '';
      state.agentPreparedActionId = '';
    }
  }
  bumpRecipientLastUsed(recipient.address);
  pushToast('success', 'Recipient selected', recipient.name);
  render();
}

function toggleRecipientIsMine(recipientId: string): void {
  const now = new Date().toISOString();
  const recipient = savedRecipientById(recipientId);
  if (!recipient) return;
  const willBeMine = !recipient.isMine;
  state.recipientRules = {
    ...state.recipientRules,
    recipients: mergeSavedRecipients(state.recipientRules.recipients.map((entry) =>
      entry.id === recipientId
        ? { ...entry, isMine: willBeMine ? true : undefined, updatedAt: now }
        : entry,
    )),
  };
  saveRecipientRules();
  pushToast(
    'success',
    willBeMine ? 'Marked as your wallet' : 'Unmarked',
    `${recipient.name}${willBeMine ? ' → your wallet' : ''}`,
  );
  render();
}

function recipientFieldError(field: keyof RecipientDraft): string {
  const message = state.recipientErrors[field];
  return message ? `<em class="field-error-text">${escapeHtml(message)}</em>` : '';
}

function publicBridgeStatusCard(): string {
  const connected = state.bridgeActive;
  const localMode = activeWorkflowMode() === 'local-bridge';
  const tone = localMode ? 'online' : connected ? 'connected' : state.busy ? 'checking' : 'offline';
  const status = localMode ? 'Active' : connected ? 'Connected' : state.busy ? 'Checking' : 'Offline';
  const detail = connected
    ? localMode
      ? 'Private local mode owns new workflow actions on this device.'
      : 'Local connector is available. Use it only when you want local-only workflow storage.'
    : 'Optional. Start the local connector only when you want private local workflow storage.';
  return `
    <section class="rail-bridge-card ${tone}" aria-label="Private local mode status">
      <div class="rail-bridge-head">
        <span>Local connector</span>
        <strong>${escapeHtml(status)}</strong>
      </div>
      <p>${escapeHtml(detail)}</p>
      ${connected ? `
        <div class="rail-bridge-facts">
          <span>Endpoint <strong>${escapeHtml(compactEndpoint(state.bridgeUrl))}</strong></span>
          <span>Wallet <strong>${escapeHtml(state.address ? short(state.address) : 'Not connected')}</strong></span>
        </div>
        <div class="rail-bridge-actions">
          ${localMode
            ? `<button type="button" data-workflow-mode="auto" ${state.busy ? 'disabled' : ''}>Use cloud or browser</button>`
            : `<button type="button" class="utility" data-workflow-mode="local-bridge" ${!state.address || state.busy ? 'disabled' : ''}>Use private local mode</button>`}
        </div>
      ` : `
        <div class="rail-bridge-actions">
          <button type="button" class="utility" data-bridge-action="connect" ${!state.address || state.busy ? 'disabled' : ''}>Check local bridge</button>
          ${optionalPrivateLocalModeDetails()}
        </div>
      `}
    </section>
  `;
}

function optionalPrivateLocalModeDetails(): string {
  return `
    <details class="bridge-setup-details optional-local-runtime">
      <summary>Use private local mode</summary>
      <div class="local-runtime-guide rail-runtime-guide optional-runtime-guide">
        <div class="local-runtime-guide-head">
          <span>Optional on this computer</span>
          <strong>${escapeHtml(compactEndpoint(state.bridgeUrl))}</strong>
        </div>
        <p>Use the local runtime only when you want workflow storage to stay on this machine. The normal web app can use Agentic Cloud or saved-on-device workflow without localhost.</p>
        <ol class="local-runtime-steps">
          <li>Run the one-shot command in Terminal.</li>
          <li>Connect the same wallet in the local browser tab.</li>
          <li>Return here and check the local bridge.</li>
        </ol>
        <div class="bridge-command-row primary-runtime-command">
          <code>${escapeHtml(NPM_EXEC_COMMAND)}</code>
          <button type="button" data-copy="${escapeHtml(NPM_EXEC_COMMAND)}" data-copy-name="local runtime command">Copy</button>
        </div>
      </div>
    </details>
  `;
}

function walletRailIcon(wallet: WalletIdentity): string {
  const iconSrc = wallet.logoId ? BRAND_LOGOS[wallet.logoId] : wallet.discoveredWallet?.icon;
  if (iconSrc) {
    return `
      <span class="rail-icon wallet-provider-icon" aria-hidden="true">
        <img src="${escapeHtml(iconSrc)}" alt="" />
      </span>
    `;
  }
  return `<span class="rail-icon" aria-hidden="true">${escapeHtml(wallet.icon)}</span>`;
}

function publicWalletActions(): string {
  const selectedProvider = discoveredSelectedWalletName();
  const androidNative = state.androidNativeEnvironment.isAndroidNative;
  const iosNative = state.iosNativeEnvironment.isIosNative;
  const nativeWallet = androidNative || iosNative;
  if (state.address) {
    return `
      <div class="wallet-actions public-wallet-actions connected">
        <button id="disconnect" ${state.busy ? 'disabled' : ''}>Disconnect wallet</button>
      </div>
    `;
  }
  if (androidNative) {
    return `
      <div class="wallet-actions public-wallet-actions native-wallet-actions android-wallet-actions">
        ${androidNativeWalletChoiceButtons('public')}
      </div>
    `;
  }
  if (nativeWallet) {
    return `
      <div class="wallet-actions public-wallet-actions native-wallet-actions">
        <button data-start-action="connect" class="primary wallet-connect-cta" ${state.busy ? 'disabled' : ''}>
          ${walletButtonIcon()}
          <span>Connect wallet</span>
        </button>
      </div>
    `;
  }
  return `
    <div class="wallet-actions public-wallet-actions">
      <button data-start-action="discover" class="primary" ${state.busy ? 'disabled' : ''}>
        Discover
      </button>
      <button data-start-action="connect" class="${state.wallets.length ? 'primary' : ''}" ${(state.wallets.length === 0 || !selectedProvider) || state.busy ? 'disabled' : ''} title="${!selectedProvider ? 'Discover and select a wallet provider first.' : ''}">
        Connect wallet
      </button>
    </div>
  `;
}

function walletButtonIcon(): string {
  return `
    <svg class="wallet-button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <path d="M19 7h-1V6.5A2.5 2.5 0 0 0 15.5 4H5.75A3.75 3.75 0 0 0 2 7.75v8.5A3.75 3.75 0 0 0 5.75 20H19a3 3 0 0 0 3-3v-7a3 3 0 0 0-3-3Zm-3-1a.5.5 0 0 1 .5.5V7H5.75a1.25 1.25 0 0 1 0-2.5h9.75ZM20 17a1 1 0 0 1-1 1H5.75A1.75 1.75 0 0 1 4 16.25V8.76c.52.16 1.08.24 1.75.24H19a1 1 0 0 1 1 1v7Zm-4.5-4.5a1.25 1.25 0 1 0 0 2.5 1.25 1.25 0 0 0 0-2.5Z"></path>
    </svg>
  `;
}

function androidNativeWalletChoiceButtons(surface: 'public' | 'panel' | 'guided'): string {
  const choices = androidNativeWalletChoices();
  const choiceButtons = choices
    .map((wallet, index) => androidNativeWalletButton(wallet, surface, index === 0))
    .join('');
  return `
    <div class="android-wallet-choice-grid" data-android-wallet-surface="${escapeHtml(surface)}">
      ${choiceButtons}
      <button
        type="button"
        data-start-action="connect"
        class="${surface === 'public' && choiceButtons.length === 0 ? 'primary ' : ''}wallet-connect-cta android-wallet-choice other-wallet"
        ${state.busy ? 'disabled' : ''}
      >
        ${walletButtonIcon()}
        <span>Other wallet</span>
      </button>
    </div>
  `;
}

function androidNativeWalletButton(
  wallet: AndroidNativeDetectedWallet,
  surface: 'public' | 'panel' | 'guided',
  primary: boolean,
): string {
  const logoId = wallet.logoId ?? walletLogoIdForName(wallet.name);
  const className = [
    'wallet-connect-cta',
    'android-wallet-choice',
    primary || surface === 'public' ? 'primary' : '',
    wallet.installed ? 'installed' : 'not-detected',
  ].filter(Boolean).join(' ');
  return `
    <button
      type="button"
      data-android-wallet-package="${escapeHtml(wallet.walletPackage)}"
      data-android-wallet-name="${escapeHtml(wallet.name)}"
      data-android-wallet-type="${wallet.walletType ?? ''}"
      data-android-wallet-logo-id="${escapeHtml(logoId ?? '')}"
      class="${escapeHtml(className)}"
      ${state.busy ? 'disabled' : ''}
    >
      ${logoId ? brandLogo(logoId, 'android-wallet-choice-logo') : walletButtonIcon()}
      <span>${escapeHtml(wallet.name)}</span>
    </button>
  `;
}

function androidNativeWalletChoices(): AndroidNativeDetectedWallet[] {
  const byPackage = new Map<string, AndroidNativeDetectedWallet>();
  for (const wallet of [...ANDROID_NATIVE_WALLET_FALLBACKS, ...state.androidNativeWallets]) {
    const key = wallet.walletPackage.toLowerCase();
    const existing = byPackage.get(key);
    byPackage.set(key, {
      ...wallet,
      logoId: wallet.logoId ?? existing?.logoId ?? walletProviderLogoIdForName(wallet.name),
      installed: wallet.installed || existing?.installed === true,
      versionName: wallet.versionName ?? existing?.versionName,
    });
  }
  const priority = ['com.solanamobile.seedvaultimpl', 'com.solflare.mobile'];
  return [...byPackage.values()]
    .filter((wallet) => wallet.logoId === 'seedVault' || wallet.logoId === 'solflare' || wallet.installed)
    .sort((a, b) => {
      const aPriority = priority.indexOf(a.walletPackage);
      const bPriority = priority.indexOf(b.walletPackage);
      const aRank = aPriority === -1 ? priority.length : aPriority;
      const bRank = bPriority === -1 ? priority.length : bPriority;
      if (aRank !== bRank) return aRank - bRank;
      if (a.installed !== b.installed) return a.installed ? -1 : 1;
      return a.name.localeCompare(b.name);
    });
}

