function commandConnectedAiPathVisual(): string {
  return `
    <svg class="command-ai-path-visual" viewBox="0 0 132 76" aria-hidden="true" focusable="false">
      <path class="command-ai-path-visual-halo" d="M17 49c18-35 38-35 49-12s35 27 49-10" />
      <path class="command-ai-path-visual-line" d="M17 49c18-35 38-35 49-12s35 27 49-10" />
      <g class="command-ai-path-visual-node">
        <circle cx="17" cy="49" r="9" />
        <path d="M17 44.8v8.4M12.8 49h8.4" />
      </g>
      <g class="command-ai-path-visual-node main">
        <circle cx="66" cy="37" r="12" />
        <path d="M66 29.8v3.4M66 40.8v3.4M58.8 37h3.4M69.8 37h3.4M61 32l2.4 2.4M68.6 39.6 71 42M71 32l-2.4 2.4M63.4 39.6 61 42" />
      </g>
      <g class="command-ai-path-visual-node">
        <circle cx="115" cy="27" r="9" />
        <path d="m111.2 27.2 2.4 2.4 5.1-5.6" />
      </g>
    </svg>
  `;
}

function walletFlowPanel(): string {
  if (!state.address) {
    return `
      ${guidedStartPanel('Wallet signing', 'Connect a browser wallet to open signing requests, approvals, and receipts.')}
      ${SHOW_DEV_CONTROLS ? terminalCommandPanel() : ''}
    `;
  }
  const signButtonClass = state.signature ? 'primary resolved' : 'primary';
  const signButtonLabel = state.signature ? 'Signed' : 'Sign message';
  const signButtonDisabled = state.signature || !state.address || state.busy ? 'disabled' : '';
  const walletStatus = state.signature
    ? 'Wallet signature captured. Receipt is ready for audit.'
    : state.transactionStatus || 'Ready for wallet approval.';
  return `
    <section class="approval-object signature-stage stage-wallet ${state.signature ? 'stage-complete' : 'stage-active'}">
      <div class="signature-object-head">
        <div>
          <h2>Message approval</h2>
          <p>Wallet-held key approval for a bounded agent message on ${escapeHtml(titleCaseCluster(state.cluster))}.</p>
        </div>
        <span class="signature-state ${state.signature ? 'complete' : 'active'}">${state.signature ? 'signed' : 'ready'}</span>
      </div>

      <div class="signature-capsule">
        <div class="capsule-main">
          <span>Request</span>
          <strong>${escapeHtml(DEMO_MESSAGE)}</strong>
          <p>Signer: ${escapeHtml(state.selectedWalletName || 'Connected wallet')} • ${escapeHtml(short(state.address))}</p>
        </div>
        <button id="signMessage" class="${signButtonClass}" ${signButtonDisabled}>${signButtonLabel}</button>
      </div>

      ${signatureLifecycle([
        ['Provider', state.wallets.length ? `${state.wallets.length} discovered` : 'Ready', true],
        ['Signer', short(state.address), true],
        ['Approval', state.signature ? 'Wallet signed' : 'Waiting for action', Boolean(state.signature)],
        ['Receipt', state.txid || state.txSignature ? 'Available' : 'Pending', Boolean(state.txid || state.txSignature)],
      ])}

      ${SHOW_DEV_CONTROLS ? `<details class="advanced-section" ${state.customTransactionBase64 || state.txSignature || state.txid ? 'open' : ''}>
        <summary>
          <span>Advanced transaction tools</span>
          <strong>${state.cluster === 'devnet' ? 'Devnet memo test' : 'Paste transaction bytes'}</strong>
        </summary>
        <div class="transaction-actions">
          <div class="transaction-action-row">
            <button id="createTx" ${!state.address || state.busy || state.cluster !== 'devnet' ? 'disabled' : ''}>Create demo transaction</button>
            <button id="signTx" ${!state.address || !state.customTransactionBase64 || state.busy ? 'disabled' : ''}>Sign transaction</button>
            <button id="sendTx" ${!canSignAndSend() ? 'disabled' : ''}>Sign and send</button>
          </div>
          <label class="field compact transaction-field">
            <span>Transaction base64</span>
            <textarea id="txInput" placeholder="Create a demo transaction or paste a transaction, base64 encoded" ${state.busy ? 'disabled' : ''}>${escapeHtml(state.customTransactionBase64)}</textarea>
          </label>
        </div>
      </details>` : ''}

      <div class="signature-floor">
        <div>
          <span>Status</span>
          <strong>${escapeHtml(walletStatus)}</strong>
        </div>
        ${SHOW_DEV_CONTROLS ? `<button id="airdrop" class="utility" ${!state.address || state.busy || state.cluster !== 'devnet' ? 'disabled' : ''}>
          Request devnet SOL
        </button>` : ''}
      </div>

      ${resultBlock()}
      ${SHOW_DEV_CONTROLS ? terminalCommandPanel() : ''}
      ${state.error ? `<div class="error">${escapeHtml(state.error)}</div>` : ''}
    </section>
  `;
}

function agentPlanPanel(): string {
  const reviewCount = generatedPlansForPanel(true).filter(isGeneratedPlanActiveInReview).length;
  const headerTitle = state.oneTimePlanView === 'review' ? 'Check request' : 'New Request';
  const headerDetail = state.oneTimePlanView === 'review'
    ? 'Saved one-time drafts. Send executable work to Needs Approval for a wallet decision.'
    : 'Create a one-time payment or swap. Nothing is sent until you approve it.';
  const statusMarker = state.oneTimePlanView === 'review'
    ? `<span class="signature-state accent-note ${state.agentSignature ? 'complete' : state.agentPlan ? 'active' : ''}">${reviewCount} plan${reviewCount === 1 ? '' : 's'}</span>`
    : '';
  return `
    <section class="approval-object signature-stage stage-agent ${state.agentSignature ? 'stage-complete' : state.agentPlan ? 'stage-active' : 'stage-draft'}">
      <div class="signature-object-head">
        ${sectionTitleLine(headerTitle, headerDetail)}
        ${statusMarker}
      </div>

      ${oneTimePlanTabs()}
      ${state.oneTimePlanView === 'review' ? generatedPlansPanel(true) : oneTimeCreatePlanPanel()}
      ${state.oneTimePlanView === 'create' && state.error ? `<div class="error">${escapeHtml(state.error)}</div>` : ''}
    </section>
  `;
}

function oneTimePlanTabs(): string {
  const creating = state.oneTimePlanView === 'create';
  const reviewing = state.oneTimePlanView === 'review';
  const selectedConnector = creating ? selectedConnectorForCreate(selectedTemplate()) : undefined;
  return `
    <div class="one-time-plan-control-row ${creating ? 'has-connector' : reviewing ? 'review-filter-row' : ''}">
      <div class="tabs compact-tabs one-time-plan-tabs" role="tablist" aria-label="One-time plan steps">
        ${oneTimePlanViewButton('create', 'Start')}
        ${oneTimePlanViewButton('review', 'Check')}
      </div>
      ${reviewing ? agentReviewFilterControl('generated') : ''}
      ${reviewing ? `<button id="deleteAllCheck" class="utility danger" ${state.busy || filterGeneratedPlansByAgentReview(visibleGeneratedPlans(true)).length === 0 ? 'disabled' : ''}>Delete All</button>` : ''}
      ${creating ? connectorCreatePickerControl(selectedTemplate()) : ''}
      ${creating && !selectedConnector ? templateOutcomeControls('header') : ''}
    </div>
  `;
}

function oneTimePlanViewButton(view: OneTimePlanView, label: string): string {
  const active = state.oneTimePlanView === view;
  return `
    <button
      data-one-time-view="${view}"
      class="${active ? 'active' : ''}"
      role="tab"
      aria-selected="${active ? 'true' : 'false'}"
      type="button"
      ${state.busy ? 'disabled' : ''}
    >
      ${escapeHtml(label)}
    </button>
  `;
}

function oneTimeCreatePlanPanel(): string {
  const walletReady = Boolean(state.address);
  const hasOneTimePlans = generatedPlansForPanel(true).length > 0;
  return `
    <div class="one-time-create-panel">
      ${agentPlannerWorkbench()}

      ${draftFlowHint(hasOneTimePlans, walletReady)}
    </div>
  `;
}

function draftFlowHint(hasOneTimePlans: boolean, walletReady: boolean): string {
  const reviewCopy = hasOneTimePlans ? 'Check already has saved drafts.' : 'New drafts move to Check.';
  const walletCopy = walletReady ? 'Wallet is ready when you send work for approval.' : 'Wallet is optional until approval or proof signing.';
  return `
    <div class="draft-flow-hint">
      <span class="accent-note">Draft flow</span>
      <p class="accent-note">${escapeHtml(reviewCopy)} Drafts save to Check; send for approval only when ready. ${escapeHtml(walletCopy)}</p>
    </div>
  `;
}

function draftReadyPanel(plan: AgentPlan): string {
  const outcome = planOutcome(plan);
  const approvalCapable = canQueueAgentPlan(plan);
  const activeRecord = generatedPlanById(state.selectedGeneratedPlanId);
  const queueable = canQueueGuardedPlan(plan);
  return `
    <section class="draft-ready-panel ${escapeHtml(outcomeClass(outcome))}">
      <div>
        <span class="workbench-kicker">Plan ready</span>
        <h3>${escapeHtml(outcomeLabel(outcome))}</h3>
        <p>${escapeHtml(outcomeDetailForPlan(plan))}</p>
      </div>
      ${planGuardrailStrip(plan)}
      <div class="draft-ready-actions">
        ${approvalCapable ? `
          <button
            id="queueAgentPlan"
            class="${queueable ? 'primary' : 'utility'}"
            ${!state.address || !queueable ? 'disabled' : ''}
            title="${escapeHtml(queuePlanTitle())}"
          >
            ${escapeHtml(queueActionLabelForPlan(plan))}
          </button>
        ` : `
          <button
            id="signAgentPlan"
            class="review-action-proof"
            ${!state.address || state.busy ? 'disabled' : ''}
            title="${!state.address ? 'Connect a wallet before signing review evidence.' : 'Creates audit evidence only. It does not queue, approve, or submit a transaction.'}"
          >
            Sign proof
          </button>
        `}
        <button
          data-one-time-view="review"
          class="utility"
          ${state.busy ? 'disabled' : ''}
        >
          Check
        </button>
      </div>
    </section>
  `;
}

function generatedPlansPanel(embedded = false): string {
  const allPlans = generatedPlansForPanel(embedded);
  const baseVisiblePlans = visibleGeneratedPlans(embedded);
  const visiblePlans = filterGeneratedPlansByAgentReview(baseVisiblePlans);
  const paginatedPlans = paginateList(visiblePlans, 'review');
  const aiDraftPending = embedded && state.activeOperation === 'generate-ai-plan';
  const archivedCount = allPlans.filter((record) => record.status === 'archived').length;
  const activeCount = allPlans.filter(isGeneratedPlanActiveInReview).length;
  const movedCount = allPlans.filter(hasGeneratedPlanMovedPastReview).length;
  const selectedAuditRecord = generatedPlanById(state.generatedPlanAuditId);
  const auditRecord = selectedAuditRecord && (!embedded || isOneTimeGeneratedPlan(selectedAuditRecord))
    ? selectedAuditRecord
    : undefined;
  const toolbar = `
        <div class="generated-plans-toolbar signature-toolbar">
          <span class="signature-state micro-emphasis">${escapeHtml(`${activeCount} active`)}</span>
          <button
            data-one-time-view="create"
            class="utility check-toolbar-create-another"
            ${state.busy ? 'disabled' : ''}
          >
            Create another draft
          </button>
          <button
            id="toggleArchivedGeneratedPlans"
            class="utility"
            ${archivedCount === 0 ? 'disabled' : ''}
          >
            ${state.showArchivedGeneratedPlans ? 'Hide archived' : `Show archived (${archivedCount})`}
          </button>
        </div>
  `;
  const content = `
      ${embedded
        ? `<div class="generated-plans-toolbar-row">${toolbar}</div>`
        : `<div class="signature-object-head">
        ${sectionTitleLine('Check request', 'Saved one-time drafts. Send executable work to Needs Approval for a wallet decision.')}
        ${toolbar}
      </div>
      `}

      ${planTemplatesStrip(embedded)}
      ${generatedPlanStatusLine(allPlans.length, baseVisiblePlans.length, visiblePlans.length, archivedCount, movedCount)}
      ${aiDraftPending ? aiDraftPendingCard() : ''}
      ${
        visiblePlans.length
          ? `
            <div class="${embedded ? 'review-plan-list' : 'generated-plan-grid'}" aria-label="Check request drafts" data-layout="${embedded ? 'review-plan-list' : 'generated-plan-grid'}">
              ${paginatedPlans.items.map((record) => generatedPlanCard(record)).join('')}
            </div>
            ${listPagination('review', paginatedPlans, 'Check drafts')}
          `
          : aiDraftPending ? '' : generatedPlansEmptyState(embedded, baseVisiblePlans.length > 0)
      }
      ${state.error ? `<div class="error">${escapeHtml(state.error)}</div>` : ''}
  `;
  if (embedded) {
    return `
      <div class="one-time-review-panel stage-generated stage-anchor ${allPlans.length ? 'stage-active' : 'stage-draft'}">
        ${content}
      </div>
      ${auditRecord ? generatedPlanAuditModal(auditRecord) : ''}
    `;
  }
  return `
    <section class="approval-object signature-stage stage-generated stage-anchor ${allPlans.length ? 'stage-active' : 'stage-draft'}">
      ${content}
    </section>
    ${auditRecord ? generatedPlanAuditModal(auditRecord) : ''}
  `;
}

function generatedPlanStatusLine(
  totalCount: number,
  inCheckCount: number,
  shownCount: number,
  archivedCount: number,
  movedCount: number,
): string {
  const filtered = state.generatedPlanAgentReviewFilter !== 'all';
  return `
    <div class="queue-status generated-plan-status">
      <span class="status-detail-desktop-only">${escapeHtml(`${totalCount} plan${totalCount === 1 ? '' : 's'} saved`)}</span>
      ${filtered
        ? `<strong class="accent-note">${shownCount} shown</strong><span>${inCheckCount} in check</span><span>${escapeHtml(agentReviewFilterLabel(state.generatedPlanAgentReviewFilter))}</span>`
        : `<strong class="accent-note">${inCheckCount} in check</strong>`}
      <span class="status-detail-desktop-only">${movedCount} moved forward</span>
      <span>${archivedCount} archived</span>
      <span>Newest first</span>
    </div>
  `;
}

function agentReviewFilterControl(scope: AgentReviewFilterScope): string {
  const value = scope === 'generated'
    ? state.generatedPlanAgentReviewFilter
    : state.recurringAgentReviewFilter;
  return selectPicker({
    id: scope === 'generated' ? 'generatedPlanAgentReviewFilter' : 'recurringAgentReviewFilter',
    value,
    options: agentReviewFilterOptions(),
    attrs: { 'data-agent-review-filter': scope },
    disabled: state.busy,
    className: 'agent-review-filter-control',
    title: 'Filter by AI review status',
  });
}

function agentReviewFilterOptions(): SelectPickerOption[] {
  return [
    { value: 'all', label: 'AI: All', meta: 'AI filter', detail: 'Every review status' },
    { value: 'approved', label: 'Passed', meta: 'AI filter', detail: 'Agent approved' },
    { value: 'denied', label: 'Denied', meta: 'AI filter', detail: 'Agent denied' },
    { value: 'needs_input', label: 'Needs context', meta: 'AI filter', detail: 'Agent asked questions' },
    { value: 'checking', label: 'Checking', meta: 'AI filter', detail: 'Review in progress' },
    { value: 'error', label: 'Failed', meta: 'AI filter', detail: 'Review failed' },
    { value: 'not_asked', label: 'Not asked', meta: 'AI filter', detail: 'No agent review yet' },
  ];
}

function isAgentReviewFilter(value: string | undefined): value is AgentReviewFilter {
  return value === 'all' ||
    value === 'approved' ||
    value === 'denied' ||
    value === 'needs_input' ||
    value === 'checking' ||
    value === 'error' ||
    value === 'not_asked';
}

function agentReviewFilterLabel(filter: AgentReviewFilter): string {
  switch (filter) {
    case 'approved':
      return 'Passed';
    case 'denied':
      return 'Denied';
    case 'needs_input':
      return 'Needs context';
    case 'checking':
      return 'Checking';
    case 'error':
      return 'Failed';
    case 'not_asked':
      return 'Not asked';
    case 'all':
    default:
      return 'AI: All';
  }
}

function matchesAgentReviewFilter(review: AgentPlanReviewState | undefined, filter: AgentReviewFilter): boolean {
  if (filter === 'all') return true;
  if (filter === 'not_asked') return !review?.required;
  return review?.required === true && review.status === filter;
}

function aiDraftPendingCard(): string {
  const operation = activeAiDraftOperation;
  const templateTitle = operation?.templateTitle ?? selectedTemplate().title;
  const prompt = operation?.prompt ?? state.agentPrompt.trim();
  return `
    <section class="ai-draft-pending-card" aria-label="AI draft in progress">
      <div class="ai-draft-pending-copy">
        <span>AI draft</span>
        <h3>${escapeHtml(templateTitle)} is being drafted</h3>
        <p>${escapeHtml(prompt || 'Building the request for Check. Optional agent review stays off unless you enable it.')}</p>
      </div>
      <div class="ai-draft-pending-actions">
        <strong>${buttonSpinner()}Working</strong>
        ${operation ? `
          <button type="button" class="utility danger" data-ai-draft-action="cancel">
            Cancel
          </button>
        ` : ''}
      </div>
    </section>
  `;
}

function generatedPlanCard(record: GeneratedPlanRecord): string {
  const displayRecord = generatedPlanRecordWithRuntimeTokenLabels(record);
  const plan = displayRecord.plan;
  const approvalCapable = canQueueAgentPlan(plan);
  const queueable = canQueueGeneratedPlan(displayRecord);
  const archived = record.status === 'archived';
  const proofDisabled = !state.address || state.busy || archived ? 'disabled' : '';
  const queueDisabled = !state.address || !queueable || archived ? 'disabled' : '';
  const selected = state.selectedGeneratedPlanId === record.id;
  const actionHint = generatedPlanActionHint(displayRecord);
  const guardrailBlocked = planGuardrailVerdict(plan) === 'block';
  const reviewSummary = generatedPlanReviewSummary(displayRecord);
  const metaHint = generatedPlanMetaHint(displayRecord, guardrailBlocked);
  const agentReviewAction = agentReviewButton(record);
  const reviewActionLayoutClass = agentReviewAction ? 'has-agent-review-action' : 'solo-primary-action';
  return `
    <article class="generated-plan-card review-plan-card ${selected ? 'selected' : ''} ${archived ? 'archived' : ''}" data-layout="review-plan-card">
      <div class="review-plan-card-head">
        <div class="review-plan-title-block">
          <div class="review-plan-meta">
            <span class="status-pill ${generatedPlanStatusTone(record)}">${escapeHtml(generatedPlanStatusLabel(record))}</span>
            ${storageBadgeHtml(generatedPlanStorageBadge(record))}
            ${generatedPlanConnectorChip(displayRecord)}
            <span>${escapeHtml(record.source === 'ai' ? 'AI draft' : 'Template draft')}</span>
            ${generatedPlanFailurePill(record)}
            <span>${escapeHtml(formatDateTime(record.createdAt))}</span>
            ${metaHint ? `<span class="review-plan-meta-pill">${escapeHtml(metaHint)}</span>` : ''}
          </div>
          <h3>${escapeHtml(generatedPlanReviewTitle(record))}</h3>
          ${reviewSummary ? `<p>${escapeHtml(reviewSummary)}</p>` : ''}
        </div>
        ${generatedPlanHeroValue(displayRecord)}
        <div class="review-plan-actions ${reviewActionLayoutClass}">
          ${agentReviewAction}
          ${approvalCapable ? `
            <button
              class="review-action-inbox"
              data-generated-plan-action="queue"
              data-generated-plan-id="${escapeHtml(record.id)}"
              ${queueDisabled}
              title="${escapeHtml(generatedQueuePlanTitle(displayRecord))}"
            >
              ${escapeHtml(queueActionLabelForPlan(plan))}
            </button>
          ` : `
            <button
              class="review-action-proof"
              data-generated-plan-action="sign-proof"
              data-generated-plan-id="${escapeHtml(record.id)}"
              ${proofDisabled}
              title="${escapeHtml(signProofTitle(displayRecord))}"
            >
              Sign proof
            </button>
          `}
        </div>
      </div>

      ${generatedPlanReviewSummaryGrid(displayRecord)}
      ${generatedPlanUserNote(plan)}
      ${generatedPlanConsistencyWarning(displayRecord)}
      ${generatedPlanAgentReviewStrip(displayRecord)}
      ${agentOverrideStrip(record.agentOverride)}
      ${record.error ? generatedPlanErrorNotice(record.error) : ''}
      ${guardrailBlocked ? actionHint : ''}

      <div class="review-plan-footer-row">
        <details class="generated-plan-inline-details review-plan-details">
          <summary><span>Details</span></summary>
          <div class="review-plan-details-body">
            <section class="review-plan-detail-section">
              <div class="review-plan-detail-section-head">
                <span>Review details</span>
                <strong>${escapeHtml(generatedPlanStatusLabel(record))}</strong>
              </div>
              <dl class="review-detail-list">
                ${reviewPlanDetailRows(displayRecord).map(([label, value]) => reviewPlanDetailRow(label, value)).join('')}
              </dl>
            </section>
            ${planGuardrailStrip(plan)}
            ${generatedPlanCompactExtras(plan)}
            ${generatedPlanOutcomeStrip(displayRecord)}
          </div>
        </details>
        ${generatedPlanCardFooterActions(displayRecord)}
      </div>
    </article>
  `;
}

function generatedPlanErrorNotice(message: string): string {
  return `
    <section class="review-plan-error" aria-label="AI draft issue">
      <span>AI draft issue</span>
      <p>${escapeHtml(message)}</p>
    </section>
  `;
}

function generatedPlanReviewTitle(record: GeneratedPlanRecord): string {
  const connectorDisplay = CONNECTOR_APPROVAL_ACTION_TYPES.has(record.plan.actionType)
    ? connectorActionDisplayParts(record.plan.actionType, record.plan.parameters)
    : undefined;
  if (connectorDisplay?.title) return connectorDisplay.title;
  return record.plan.templateTitle || record.plan.intent;
}

function connectorChip(connectorId: string | undefined, connectorName: string | undefined): string {
  if (!connectorId) return '';
  const logoId = protocolConnectorLogoId(connectorId as ConnectedDappId);
  if (!logoId) return '';
  return `
    <span class="review-plan-meta-pill connector-meta-chip">
      ${brandLogo(logoId, 'connector-meta-logo')}
      ${escapeHtml(connectorName ?? connectorId)}
    </span>
  `;
}

function generatedPlanConnectorChip(record: GeneratedPlanRecord): string {
  // Honor user-selected connector only (via form-supplied parameters.protocol /
  // .connectorId / .dapp / .provider / .route). Do NOT fuzzy-match record.plan.route
  // — that's the AI's free-text route prose, and any incidental protocol mention
  // (or substring overlap with an alias like "kamino lend") attaches the wrong
  // badge. When the user did not select a connector at draft time, the card shows
  // no connector badge — matching the create-form's empty connector dropdown state.
  const connector = selectedConnectorForDraftParameters(record.plan.parameters);
  return connector ? connectorChip(connector.id, connector.name) : '';
}

function generatedPlanFailurePill(record: GeneratedPlanRecord): string {
  if (record.status !== 'failed' && !record.error && !record.failureLabel) return '';
  const label = record.failureLabel ||
    (record.plan.actionType === 'swap'
      ? 'Swap failed - try again'
      : record.plan.actionType === 'transfer_sol' || record.plan.actionType === 'transfer_spl'
        ? 'Send failed - try again'
        : 'Action failed - try again');
  return `<span class="status-pill tx-failed">${escapeHtml(label)}</span>`;
}

function generatedPlanReviewSummary(record: GeneratedPlanRecord): string {
  const plan = record.plan;
  if (plan.actionType === 'swap') {
    return '';
  }
  if (plan.actionType === 'manual_review') {
    return 'Prepare the request, expose the route and policy checks, then require a separate wallet approval before signing.';
  }
  if (plan.actionType === 'transfer_sol' || plan.actionType === 'transfer_spl' || plan.actionType === 'recurring_payment') {
    const recipient = planParameter(plan, ['recipient', 'recipientAddress', 'settlementWallet']);
    const recipientCopy = recipient ? ` to ${recipientDisplayLabel(recipient)}` : '';
    return `${planAmountSummary(plan)}${recipientCopy}.`;
  }
  return compactSentence(plan.route || plan.intent);
}

function generatedPlanHeroValue(record: GeneratedPlanRecord): string {
  const plan = record.plan;
  const metric = reviewPlanMetric(plan);
  const subject = marketAmountSubjectForPlan(plan);
  const context = planConnectorContextLabel(plan);
  return `
    <div class="review-plan-value" title="${escapeHtml(marketHeroTitle(metric.primary, metric.secondary, subject))}">
      ${marketAmountLineHtml(metric.primary, subject)}
      ${metric.secondary ? `<span>${escapeHtml(metric.secondary)}</span>` : ''}
      ${context ? `<span class="review-plan-context">${escapeHtml(context)}</span>` : ''}
    </div>
  `;
}

const CONNECTOR_CONTEXT_GENERIC_FIELD_IDS = new Set<string>([
  'amount', 'amountSol', 'msolAmount', 'inputAmount', 'maxAmount', 'plannedAmount',
  'memo', 'reason', 'note',
  'recipient', 'recipientAddress', 'settlementWallet',
  'slippageBps',
  'priceSol', 'bidPriceSol', 'maxEscrowSol', 'maxPriceSol', 'maxPricePerNftSol',
  'count', 'cadence', 'startAt', 'maxOccurrences',
  'inputToken', 'outputToken',
  'cluster', 'walletAddress',
  'protocol', 'connectorId', 'connectorOperationId',
  'operation', 'templateId',
  'dapp', 'provider', 'route',
]);

function connectorContextLabelFromParams(
  params: Record<string, string>,
  formHint?: ConnectorActionForm,
): string {
  const form = formHint ?? selectedConnectorActionForm(params);
  if (!form) return '';
  if (form.subActions) {
    const branch = selectedSubAction(form, params);
    if (branch?.label) return branch.label;
  }
  for (const field of form.fields) {
    if (CONNECTOR_CONTEXT_GENERIC_FIELD_IDS.has(field.id)) continue;
    if (field.type !== 'cascading-select' && field.type !== 'select') continue;
    const value = params[field.id]?.trim();
    if (!value) continue;
    return formatConnectorContextDetail(value, field.label, form.connectorId);
  }
  return '';
}

function planConnectorContextLabel(plan: AgentPlan): string {
  const fromParams = connectorContextLabelFromParams(plan.parameters);
  if (fromParams) return fromParams;
  const form = connectorActionFormByActionType(plan.actionType);
  if (!form) return '';
  return connectorContextLabelFromParams(plan.parameters, form);
}

function preparedActionConnectorContextLabel(action: PreparedAction): string {
  const params: Record<string, string> = {};
  for (const [key, value] of Object.entries(action.params ?? {})) {
    if (typeof value === 'string') params[key] = value;
  }
  const fromParams = connectorContextLabelFromParams(params);
  if (fromParams) return fromParams;
  const form = connectorActionFormByActionType(action.kind);
  if (!form) return '';
  return connectorContextLabelFromParams(params, form);
}

function recurringPaymentConnectorContextLabel(payment: RecurringPayment): string {
  const params: Record<string, string> = {};
  if (payment.token) params.token = payment.token;
  if (payment.inputToken) params.inputToken = payment.inputToken;
  if (payment.outputToken) params.outputToken = payment.outputToken;
  if (payment.amount) params.amount = payment.amount;
  if (payment.recipient) params.recipient = payment.recipient;
  const metadata = payment.metadata;
  if (metadata && typeof metadata === 'object') {
    const meta = metadata as Record<string, unknown>;
    for (const key of ['connectorId', 'connectorOperationId', 'protocol', 'operation', 'templateId', 'connectorTemplateId'] as const) {
      const value = meta[key];
      if (typeof value === 'string') params[key] = value;
    }
  }
  return connectorContextLabelFromParams(params);
}

function completedPlanConnectorContextLabel(plan: CompletedPlanRecord): string {
  const connectorRead = completedPlanConnectorRead(plan);
  if (connectorRead) {
    return stringFromJsonLike(connectorRead.connectorName) || 'Pyth';
  }
  if (plan.actionId) {
    const action = state.preparedActions.find((entry) => entry.id === plan.actionId);
    if (action) {
      const label = preparedActionConnectorContextLabel(action);
      if (label) return label;
    }
  }
  if (plan.generatedPlanId) {
    const record = state.generatedPlans.find((entry) => entry.id === plan.generatedPlanId);
    if (record) {
      const label = planConnectorContextLabel(record.plan);
      if (label) return label;
    }
  }
  if (plan.recurringId) {
    const recurring = state.recurringPayments.find((entry) => entry.id === plan.recurringId);
    if (recurring) {
      const label = recurringPaymentConnectorContextLabel(recurring);
      if (label) return label;
    }
  }
  return '';
}

function formatConnectorContextDetail(value: string, fieldLabel: string, connectorId: string): string {
  const connectorName = PROTOCOL_CONNECTORS.find((entry) => entry.id === connectorId)?.name ?? '';
  let suffix = fieldLabel.trim();
  if (connectorName) {
    const lower = suffix.toLowerCase();
    const prefix = `${connectorName.toLowerCase()} `;
    if (lower.startsWith(prefix)) suffix = suffix.slice(prefix.length);
  }
  const titled = suffix
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
  const looksLikeSymbol = /^[a-zA-Z0-9-]{2,12}$/.test(value);
  const displayValue = looksLikeSymbol ? value.toUpperCase() : `${value.slice(0, 4)}…${value.slice(-4)}`;
  return titled ? `${displayValue} ${titled}` : displayValue;
}

function reviewPlanMetric(plan: AgentPlan): { primary: string; secondary: string } {
  if (plan.actionType === 'swap') {
    const amount = planParameter(plan, ['amount', 'inputAmount', 'plannedAmount']) || 'Amount';
    const input = plan.parameters.inputToken || planParameter(plan, ['token']) || 'Input';
    const output = plan.parameters.outputToken || 'Output';
    const route = tokenRouteDisplaySummary(input, output);
    const slippage = plan.parameters.slippageBps ? `${slippageBpsToPercentInput(plan.parameters.slippageBps)} max` : '';
    return {
      primary: `${amount} ${tokenDisplayLabel(input)}`,
      secondary: `${route.value}${slippage ? ` · ${slippage}` : ''}`,
    };
  }
  if (plan.actionType === 'transfer_sol' || plan.actionType === 'transfer_spl' || plan.actionType === 'recurring_payment') {
    return {
      primary: planAmountSummary(plan),
      secondary: planRecipientOrRoute(plan),
    };
  }
  if (CONNECTOR_APPROVAL_ACTION_TYPES.has(plan.actionType)) {
    const amount = planAmountSummary(plan);
    const connectorDisplay = connectorActionDisplayParts(plan.actionType, plan.parameters);
    return {
      primary: amount === 'n/a' ? compactRiskLabel(plan.risk) : amount,
      secondary: compactSentence(connectorDisplay?.title || plan.templateTitle || plan.actionType.replace(/_/g, ' '), 56),
    };
  }
  if (plan.actionType === 'manual_review') {
    const amount = planAmountSummary(plan);
    return {
      primary: amount === 'n/a' ? 'Review proof' : amount,
      secondary: compactSentence(plan.templateTitle || 'Manual review', 56),
    };
  }
  return {
    primary: plan.actionType === 'read_only' ? 'Evidence only' : compactRiskLabel(plan.risk),
    secondary: compactSentence(plan.templateTitle || plan.actionType.replace(/_/g, ' '), 56),
  };
}

function generatedPlanReviewSummaryGrid(record: GeneratedPlanRecord): string {
  const plan = record.plan;
  const routeSummary = plan.actionType === 'swap'
    ? tokenRouteDisplaySummary(plan.parameters.inputToken || 'input', plan.parameters.outputToken || 'output')
    : undefined;
  const amountCopyActions = plan.actionType === 'swap'
    ? undefined
    : planAmountTokenCopyActions(plan);
  const destination = planParameter(plan, ['destinationAddress', 'destinationRecipient']);
  const rows: WalletActionSummaryRow[] = [
    {
      label: 'Wallet',
      value: record.walletAddress ? short(record.walletAddress) : 'No wallet yet',
      title: record.walletAddress,
      tone: 'wallet',
      copyValue: record.walletAddress,
      copyName: 'Wallet address',
    },
    {
      label: plan.actionType === 'swap' ? 'Slippage' : 'Amount',
      value: plan.actionType === 'swap' ? planSlippageSummary(plan) : planAmountSummary(plan),
      tone: 'amount',
      copyActions: amountCopyActions,
    },
    {
      label: 'Route',
      value: routeSummary?.value ?? planRecipientOrRoute(plan),
      html: routeSummary?.html,
      title: routeSummary?.title,
      copyActions: routeSummary?.copyActions,
    },
    destination
      ? {
          label: 'Recipient',
          value: recipientDisplayLabel(destination),
          title: destination,
          copyValue: destination,
          copyName: 'Destination recipient',
        }
      : { label: 'Risk', value: compactRiskLabel(plan.risk) },
  ];
  return `
    <section class="review-plan-summary" aria-label="Review summary">
      <dl class="review-plan-summary-grid">
        ${rows.map(walletActionSummaryRow).join('')}
      </dl>
    </section>
  `;
}

function generatedPlanUserNote(plan: AgentPlan): string {
  const note = plan.userNotes?.trim();
  if (!note) return '';
  return `
    <section class="review-plan-user-note" aria-label="User note" title="${escapeHtml(note)}">
      <span>Note</span>
      ${expandableCopyHtml(note, {
        className: 'review-plan-user-note-copy',
        showLabel: 'Show full note',
        hideLabel: 'Hide note',
      })}
    </section>
  `;
}

function expandableCopyHtml(
  value: string,
  opts: {
    className?: string;
    previewLength?: number;
    showLabel?: string;
    hideLabel?: string;
    paragraphClassName?: string;
  } = {},
): string {
  const normalized = value.replace(/\s+/g, ' ').trim();
  const previewLength = opts.previewLength ?? 178;
  const className = ['expandable-copy', opts.className].filter(Boolean).join(' ');
  if (normalized.length <= previewLength) {
    return `<p class="${escapeHtml(['expandable-copy-static', opts.paragraphClassName].filter(Boolean).join(' '))}">${escapeHtml(value.trim())}</p>`;
  }
  return `
    <details class="${escapeHtml(className)}">
      <summary>
        <span class="expandable-copy-preview">${escapeHtml(normalized)}</span>
        <span class="expandable-copy-toggle">
          <span class="expandable-copy-show">+ ${escapeHtml(opts.showLabel ?? 'Show full text')}</span>
          <span class="expandable-copy-hide">- ${escapeHtml(opts.hideLabel ?? 'Hide text')}</span>
        </span>
      </summary>
      <p class="expandable-copy-full ${escapeHtml(opts.paragraphClassName ?? '')}">${escapeHtml(value.trim())}</p>
    </details>
  `;
}

function generatedPlanConsistencyWarning(record: GeneratedPlanRecord): string {
  const warning = swapTokenTextMismatchWarning(planWithRuntimeTokenLabels(record.plan), tokenDisplayLabel);
  if (!warning) return '';
  return `
    <section class="review-plan-consistency-warning" aria-label="Draft consistency warning">
      <span>Check token mismatch</span>
      <p>${escapeHtml(warning.message)} Fix the output token or update the draft text before asking the agent or sending for approval.</p>
    </section>
  `;
}

function agentReviewButton(record: GeneratedPlanRecord): string {
  const mockReview = isMockPreSignPolicyPlan(record);
  if (!hasDetectedAgentReviewPath() && !mockReview) return '';
  const review = record.agentReview;
  const checking = state.activeOperation === 'review-agent-plan' && review?.status === 'checking';
  const label = checking
    ? 'Asking agent...'
    : review?.status === 'needs_input'
      ? 'Answer or ask again'
      : review?.status === 'approved' || review?.status === 'denied' || review?.status === 'error'
        ? 'Ask agent again'
        : 'Ask agent';
  return `
    <button
      class="utility review-action-agent ${review ? `agent-${escapeHtml(review.status)}` : ''}"
      data-generated-plan-action="agent-review"
      data-generated-plan-id="${escapeHtml(record.id)}"
      ${!canRunAgentReview(record) || record.status === 'archived' ? 'disabled' : ''}
      title="${escapeHtml(canRunAgentReview(record) ? 'Ask the configured agent to approve, deny, or ask questions about this draft.' : agentReviewUnavailableReason(record))}"
    >
      ${checking ? buttonSpinner() : ''}${escapeHtml(label)}
    </button>
  `;
}

function generatedPlanAgentReviewStrip(record: GeneratedPlanRecord): string {
  const review = record.agentReview;
  if (!review?.required) return '';
  const stale = isAgentReviewStale(record);
  const label = agentReviewStripLabel(review.status);
  const detail = review.checkedAt
    ? `${agentReviewSourceLabel(review)} - ${formatDateTime(review.checkedAt)}`
    : agentReviewSourceLabel(review);
  const badge = agentReviewPathBadge(review.source);
  const watching = isPlanWatchActive(record);
  const watchBadge = watching
    ? `<span class="agent-review-watch-pill" title="Background watch on. Re-checks each draft once an hour while the tab is open.">Watching</span>`
    : '';
  return `
    <section class="agent-review-strip ${escapeHtml(review.status)}${watching ? ' watching' : ''}" aria-label="Agent review">
      <div class="agent-review-strip-head">
        <span>Agent review</span>
        <strong class="agent-review-state ${escapeHtml(review.status)}">${escapeHtml(label)}</strong>
        <em>${escapeHtml(detail)}</em>
        ${badge}
        ${watchBadge}
        ${stale ? '<span class="agent-review-stale-pill" title="The draft changed after this review.">Stale</span>' : ''}
      </div>
      ${agentReviewDecisionCopy(review)}
      ${stale ? '<p class="accent-note">This review is stale because the draft changed. Ask the agent again before relying on the decision.</p>' : ''}
      ${review.status === 'needs_input' ? agentReviewQuestionsForm(record) : ''}
      ${agentEvidenceDrawer(review, { stale, actionType: record.plan.actionType })}
      ${agentDenialActions(record)}
      ${agentAskAnythingPanel(record)}
    </section>
  `;
}

function agentReviewDecisionCopy(
  review: AgentPlanReviewState,
  fallback = 'Agent review is available for context. Sending for approval is still your decision.',
): string {
  const reason = review.reason?.trim() || fallback;
  const summary = review.summary?.trim();
  const summaryHtml = summary && summary !== reason
    ? `
      <section class="agent-review-copy-card">
        <span>Summary</span>
        ${expandableCopyHtml(summary, {
          className: 'agent-review-copy-text',
          showLabel: 'Show full summary',
          hideLabel: 'Hide summary',
          previewLength: 180,
        })}
      </section>
    `
    : '';
  return `
    <div class="agent-review-copy">
      ${summaryHtml}
      ${agentReviewReasonPanel(review, reason)}
    </div>
  `;
}

function agentReviewReasonPanel(review: AgentPlanReviewState, reason: string): string {
  const label = review.status === 'denied' || review.status === 'error'
    ? 'Blocking reason'
    : review.status === 'needs_input'
      ? 'Needs input'
      : review.status === 'approved'
        ? 'Why it passed'
        : 'Review status';
  const tone = review.status === 'denied' || review.status === 'error'
    ? 'danger'
    : review.status === 'needs_input'
      ? 'warn'
      : review.status === 'approved'
        ? 'pass'
        : 'neutral';
  return `
    <section class="agent-review-copy-card agent-review-reason-panel ${escapeHtml(tone)}" aria-label="${escapeHtml(label)}">
      <span>${escapeHtml(label)}</span>
      ${expandableCopyHtml(reason, {
        className: 'agent-review-copy-text',
        showLabel: 'Show full reason',
        hideLabel: 'Hide reason',
        previewLength: 220,
      })}
    </section>
  `;
}

function agentAskAnythingPanel(record: GeneratedPlanRecord): string {
  const review = record.agentReview;
  if (!review?.required) return '';
  const mockOnly = !hasDetectedAgentReviewPath() && isMockPreSignPolicyPlan(record);
  if (!hasDetectedAgentReviewPath() && !mockOnly) return '';
  const exchanges = (review.conversation ?? []).slice(-3);
  const disabled = mockOnly || !canRunAgentReview(record) || record.status === 'archived';
  const placeholder = agentAskPlaceholder(record);
  const exchangesHtml = exchanges.map((exchange) => `
    <div class="agent-ask-exchange ${exchange.pending ? 'pending' : exchange.error ? 'errored' : 'answered'}">
      <div class="agent-ask-question"><strong>You asked:</strong> ${escapeHtml(exchange.question)}</div>
      <div class="agent-ask-answer">
        ${exchange.pending ? '<em>Agent is thinking...</em>' : exchange.error
          ? `<em>${escapeHtml(exchange.error)}</em>`
          : escapeHtml(exchange.answer ?? '')}
      </div>
      ${agentAskCitationsHtml(exchange.citations)}
      ${exchange.answeredAt
        ? `<small>${escapeHtml(formatDateTime(exchange.answeredAt))}${exchange.provider ? ` · ${escapeHtml(exchange.provider)}` : ''}</small>`
        : ''}
    </div>
  `).join('');
  return `
    <details class="agent-ask-panel">
      <summary>Ask agent about this request${exchanges.length ? ` (${exchanges.length})` : ''}</summary>
      <div class="agent-ask-body">
        ${exchangesHtml}
        <form
          class="agent-ask-form"
          data-agent-ask-form
          data-generated-plan-id="${escapeHtml(record.id)}"
        >
          <input
            type="text"
            placeholder="${escapeHtml(placeholder)}"
            maxlength="400"
            data-agent-ask-input
            ${disabled ? 'disabled' : ''}
            required
          />
          <button type="submit" class="primary" ${disabled ? 'disabled' : ''}>Ask</button>
        </form>
      </div>
    </details>
  `;
}

function agentAskCitationsHtml(citations: AgentAskExchange['citations']): string {
  if (!citations?.length) return '';
  const links = citations
    .filter((citation) => /^https?:\/\//i.test(citation.ref))
    .slice(0, 3)
    .map((citation) => `
      <a href="${escapeHtml(citation.ref)}" target="_blank" rel="noreferrer">
        ${escapeHtml(citation.title || citationHost(citation.ref))}
      </a>
    `)
    .join('');
  return links ? `<div class="agent-ask-citations">${links}</div>` : '';
}

function citationHost(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

const AGENT_ASK_PLACEHOLDER_EXAMPLES: ReadonlyArray<string> = [
  'What protocol is this?',
  'Why is this risky?',
  'Is this route weird?',
  'What would make this safer?',
  'Is the recipient known?',
];

function agentAskPlaceholder(record: GeneratedPlanRecord): string {
  const seed = record.id.length;
  return AGENT_ASK_PLACEHOLDER_EXAMPLES[seed % AGENT_ASK_PLACEHOLDER_EXAMPLES.length] ?? AGENT_ASK_PLACEHOLDER_EXAMPLES[0]!;
}

function agentDenialActions(record: GeneratedPlanRecord): string {
  const review = record.agentReview;
  if (!review || review.status !== 'denied') return '';
  if (record.status === 'archived' || record.status === 'failed') return '';
  const disabled = state.busy;
  return `
    <div class="agent-denial-actions">
      <button
        type="button"
        class="utility danger agent-denial-action"
        data-generated-plan-action="agent-deny"
        data-generated-plan-id="${escapeHtml(record.id)}"
        ${disabled ? 'disabled' : ''}
        title="Save a rejection proof using the agent's reason and archive this draft."
      >
        Deny with agent reason
      </button>
    </div>
  `;
}

function agentEvidenceDrawer(
  review: AgentPlanReviewState,
  opts: { stale?: boolean; actionType?: string } = {},
): string {
  const sections = agentEvidenceSections(review, opts);
  const visibleSections = sections.filter((section) => !section.advanced);
  const advancedSection = sections.find((section) => section.advanced);
  const visibleCount = visibleSections.reduce((sum, section) => sum + section.rows.length, 0);
  const advancedCount = advancedSection?.rows.length ?? 0;
  if (!visibleCount && !advancedCount) return '';
  const statusTone = review.status === 'approved'
    ? 'pass'
    : review.status === 'denied' || review.status === 'error'
      ? 'fail'
      : 'neutral';
  const statusLabel = review.status === 'approved'
    ? 'Pass'
    : review.status === 'denied' || review.status === 'error'
      ? 'Fail'
      : 'Review';
  return `
    <details class="agent-evidence-drawer">
      <summary>
        <span class="agent-evidence-summary-left">
          <span class="agent-evidence-summary-label">Agent findings (${visibleCount})</span>
          <span class="agent-evidence-summary-state ${statusTone}">${escapeHtml(statusLabel)}</span>
        </span>
      </summary>
      <div class="agent-evidence-sections">
        ${visibleSections.map(agentEvidenceSectionHtml).join('')}
      </div>
      ${advancedSection ? agentEvidenceAdvancedSectionHtml(advancedSection, review) : ''}
    </details>
  `;
}

function agentEvidenceSectionHtml(section: AgentEvidenceDisplaySection): string {
  return `
    <section class="agent-evidence-section ${escapeHtml(section.id)}">
      <div class="agent-evidence-section-head">
        <span>${escapeHtml(section.label)}</span>
        <strong>${section.rows.length}</strong>
      </div>
      <dl class="agent-evidence-rows">
        ${section.rows.map(agentEvidenceRowHtml).join('')}
      </dl>
    </section>
  `;
}

function agentEvidenceAdvancedSectionHtml(section: AgentEvidenceDisplaySection, review: AgentPlanReviewState): string {
  return `
    <details class="agent-evidence-advanced">
      <summary>
        <span>${escapeHtml(section.label)} (${section.rows.length})</span>
      </summary>
      <dl class="agent-evidence-rows">
        ${section.rows.map(agentEvidenceRowHtml).join('')}
      </dl>
      ${agentEvidenceAdvancedRawHtml(review)}
    </details>
  `;
}

function agentEvidenceRowHtml(row: AgentEvidenceDisplayRow): string {
  return `
    <div class="agent-evidence-row ${row.tone ? escapeHtml(row.tone) : ''}">
      <dt>${escapeHtml(row.label)}</dt>
      <dd>${agentEvidenceValueHtml(row)}</dd>
    </div>
  `;
}

function agentEvidenceAdvancedRawHtml(review: AgentPlanReviewState): string {
  const evidenceDecisionContract = review.evidence?.decisionContract;
  const raw = toJsonObject({
    ...(review.decisionContract ? { decisionContract: review.decisionContract } : {}),
    ...(!review.decisionContract && isJsonObject(evidenceDecisionContract) ? { decisionContract: evidenceDecisionContract } : {}),
    ...(review.evidenceGate ? { evidenceGate: review.evidenceGate } : {}),
    ...(review.auditReceipt ? { auditReceipt: review.auditReceipt } : {}),
    ...(review.decisionViolations?.length ? { decisionViolations: review.decisionViolations } : {}),
  });
  if (!raw || Object.keys(raw).length === 0) return '';
  return `
    <details class="agent-evidence-raw">
      <summary>Raw contract JSON</summary>
      <pre>${escapeHtml(stableJson(raw))}</pre>
    </details>
  `;
}

function agentEvidenceValueHtml(row: { value: string; tone?: AgentEvidenceTone }): string {
  if (/^https?:\/\//i.test(row.value.trim())) {
    const url = row.value.trim();
    return `<a href="${escapeHtml(url)}" target="_blank" rel="noreferrer">${escapeHtml(citationHost(url))}</a>`;
  }
  if (!row.tone || row.tone === 'neutral') return escapeHtml(row.value);
  const sourceSuffix = splitAgentEvidenceSourceSuffix(row.value);
  if (!sourceSuffix) {
    return `<span class="agent-evidence-value-tone">${escapeHtml(row.value)}</span>`;
  }
  return [
    `<span class="agent-evidence-value-tone">${escapeHtml(sourceSuffix.value)}</span>`,
    `<span class="agent-evidence-value-source">${escapeHtml(sourceSuffix.separator)}${escapeHtml(sourceSuffix.source)}</span>`,
  ].join('');
}

function splitAgentEvidenceSourceSuffix(value: string): { value: string; separator: string; source: string } | null {
  const separators = [' — ', ' - '] as const;
  for (const separator of separators) {
    const index = value.lastIndexOf(separator);
    if (index <= 0) continue;
    const source = value.slice(index + separator.length).trim();
    if (!isAgentEvidenceSourceSuffix(source)) continue;
    return {
      value: value.slice(0, index),
      separator,
      source,
    };
  }
  return null;
}

function isAgentEvidenceSourceSuffix(value: string): boolean {
  return /^(?:BirdEye|Jupiter|CoinGecko|alternative\.me|DEX Screener|https?:\/\/|www\.)/i.test(value);
}

function agentEvidenceSections(
  review: AgentPlanReviewState,
  opts: { stale?: boolean; actionType?: string } = {},
): AgentEvidenceDisplaySection[] {
  return reviewEvidenceSections(review, {
    stale: opts.stale,
    stringify: stableJson,
    actionType: opts.actionType,
  });
}

function agentReviewStripLabel(status: AgentPlanReviewStatus): string {
  switch (status) {
    case 'approved':
      return 'Agent approved';
    case 'denied':
      return 'Agent denied';
    case 'checking':
      return 'Agent checking';
    case 'needs_input':
      return 'Agent needs input';
    case 'error':
    default:
      return 'Agent review failed';
  }
}

function agentReviewPathBadge(source: AgentReviewSource | undefined): string {
  const label = agentReviewPathLabel(source);
  const modifier = source ?? 'none';
  return `<span class="agent-path-pill ${escapeHtml(modifier)}" title="Agent review path">${escapeHtml(label)}</span>`;
}

function agentReviewPathLabel(source: AgentReviewSource | undefined): string {
  switch (source) {
    case 'hosted':
      return 'Hosted BYOK';
    case 'bridge':
      return 'Local bridge';
    case 'device-agent':
      return 'Device Agent';
    case 'session':
      return 'Browser session';
    case 'mock':
      return 'Local demo';
    default:
      return 'No agent';
  }
}

function isAgentReviewSource(value: unknown): value is AgentReviewSource {
  return value === 'hosted' || value === 'session' || value === 'bridge' || value === 'device-agent' || value === 'mock';
}

function agentReviewQuestionsForm(record: GeneratedPlanRecord): string {
  const review = record.agentReview;
  if (!review || review.status !== 'needs_input' || !review.questions?.length) return '';
  const disabled = !canRunAgentReview() || record.status === 'archived';
  const inputs = review.questions.map((question, index) => {
    const value = review.answers?.[question.id] ?? '';
    const safeId = `agent-review-q-${escapeHtml(record.id)}-${escapeHtml(question.id)}`;
    const labelHtml = `<label for="${safeId}"><strong>${index + 1}.</strong> ${escapeHtml(question.prompt)}${question.required ? ' <em class="agent-review-required">*</em>' : ''}</label>`;
    if (question.inputKind === 'select' && question.options?.length) {
      const options = question.options.map((option) => `<option value="${escapeHtml(option)}" ${option === value ? 'selected' : ''}>${escapeHtml(option)}</option>`).join('');
      return `
        <div class="agent-review-question">
          ${labelHtml}
          <select
            id="${safeId}"
            data-agent-review-answer-input
            data-generated-plan-id="${escapeHtml(record.id)}"
            data-question-id="${escapeHtml(question.id)}"
            ${disabled ? 'disabled' : ''}
          >
            <option value="" disabled ${value ? '' : 'selected'}>Choose...</option>
            ${options}
          </select>
          ${question.hint ? `<small>${escapeHtml(question.hint)}</small>` : ''}
        </div>
      `;
    }
    const inputType = question.inputKind === 'number' ? 'number' : 'text';
    return `
      <div class="agent-review-question">
        ${labelHtml}
        <input
          id="${safeId}"
          type="${inputType}"
          data-agent-review-answer-input
          data-generated-plan-id="${escapeHtml(record.id)}"
          data-question-id="${escapeHtml(question.id)}"
          value="${escapeHtml(value)}"
          placeholder="Type your answer..."
          ${question.required ? 'required' : ''}
          ${disabled ? 'disabled' : ''}
        />
        ${question.hint ? `<small>${escapeHtml(question.hint)}</small>` : ''}
      </div>
    `;
  }).join('');
  return `
    <form
      class="agent-review-questions"
      data-generated-plan-action="agent-answer"
      data-generated-plan-id="${escapeHtml(record.id)}"
    >
      <p class="agent-review-questions-intro">Answer to continue the agent review.</p>
      ${inputs}
      <div class="agent-review-questions-actions">
        <button type="submit" class="primary" ${disabled ? 'disabled' : ''}>Send answers</button>
        <button
          type="button"
          class="utility"
          data-generated-plan-action="agent-review"
          data-generated-plan-id="${escapeHtml(record.id)}"
          ${disabled ? 'disabled' : ''}
        >Ask agent again</button>
      </div>
    </form>
  `;
}

function agentReviewSourceLabel(review: AgentPlanReviewState): string {
  const parts = [
    review.provider || (review.source ? `${review.source} AI` : 'Agent'),
    review.model,
  ].filter(Boolean);
  return parts.join(' - ') || 'Agent';
}

function agentOverrideStrip(override: AgentReviewOverride | undefined): string {
  if (!override) return '';
  const verdict = overrideShortLabel(override);
  const userReason = override.userReason?.trim();
  const agentReason = override.agentReason?.trim();
  const pathLabel = agentReviewPathLabel(override.source);
  return `
    <section class="agent-override-strip" aria-label="Agent override receipt">
      <div>
        <span>Override</span>
        <strong>User sent despite ${escapeHtml(verdict)}</strong>
        <em>${escapeHtml(formatDateTime(override.overriddenAt))} - ${escapeHtml(pathLabel)}</em>
      </div>
      ${agentReason ? `<p><strong>Agent said:</strong> ${escapeHtml(agentReason)}</p>` : ''}
      ${userReason ? `<p><strong>User reason:</strong> ${escapeHtml(userReason)}</p>` : ''}
    </section>
  `;
}

function reviewPlanDetailRows(record: GeneratedPlanRecord): Array<[string, string]> {
  const plan = record.plan;
  return [
    ['Intent', compactSentence(plan.intent)],
    ['Template', plan.templateTitle],
    ['Action', plan.actionType.replace(/_/g, ' ')],
    ['Route', compactSentence(plan.route)],
    ['Rule', compactSentence(plan.approval)],
    ['Effect', compactSentence(generatedPlanEffectLabel(record))],
  ];
}

function reviewPlanDetailRow(label: string, value: string): string {
  const wide = /^(Rule|Effect|Fields|Safeguards)$/i.test(label) || value.length > 88;
  return `
    <div class="${wide ? 'wide' : ''}" title="${escapeHtml(value)}">
      <dt>${escapeHtml(label)}</dt>
      <dd>${escapeHtml(value)}</dd>
    </div>
  `;
}

function compactRiskLabel(value: string): string {
  if (/high/i.test(value)) return 'High';
  if (/medium/i.test(value)) return 'Medium';
  if (/low/i.test(value)) return 'Low';
  return compactSentence(value);
}

function compactSentence(value: string, maxLength = 132): string {
  const normalized = value.replace(/\s+/g, ' ').trim();
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, maxLength - 1).trimEnd()}...`;
}

function planSlippageSummary(plan: AgentPlan): string {
  const slippage = plan.parameters.slippageBps;
  return slippage ? `${slippageBpsToPercentInput(slippage)} max` : 'Default';
}

function generatedPlanCompactExtras(plan: AgentPlan): string {
  const rows: Array<[string, string]> = [];
  if (plan.fields.length) {
    rows.push(['Fields', plan.fields.map((field) => `${field.label}: ${field.value}`).join('; ')]);
  }
  if (plan.safeguards.length) {
    rows.push(['Safeguards', plan.safeguards.join(' ')]);
  }
  if (!rows.length) return '';
  return `
    <section class="review-plan-detail-section review-plan-detail-section-extra">
      <div class="review-plan-detail-section-head">
        <span>Extra context</span>
      </div>
      <dl class="review-detail-list compact-extra">
        ${rows.map(([label, value]) => reviewPlanDetailRow(label, compactSentence(value, 180))).join('')}
      </dl>
    </section>
  `;
}

