function generatedPlanMetaHint(record: GeneratedPlanRecord, guardrailBlocked: boolean): string {
  if (record.status === 'archived' || guardrailBlocked || state.address) return '';
  return 'Connect wallet to continue';
}

function generatedPlanInlineDetailsContent(plan: AgentPlan): string {
  return `
    ${plan.userNotes ? `
      <section>
        <span>User notes</span>
        <p>${escapeHtml(plan.userNotes)}</p>
      </section>
    ` : ''}
    ${plan.fields.length ? `
      <section>
        <span>Fields</span>
        <ul>${plan.fields.map((field) => `<li>${escapeHtml(`${field.label}: ${field.value}`)}</li>`).join('')}</ul>
      </section>
    ` : ''}
    ${plan.safeguards.length ? `
      <section>
        <span>Safeguards</span>
        <ul>${plan.safeguards.map((safeguard) => `<li>${escapeHtml(safeguard)}</li>`).join('')}</ul>
      </section>
    ` : ''}
  `;
}

function generatedPlanDecisionRows(plan: AgentPlan): Array<[string, string]> {
  const policyCap = plan.fields.find((field) => /policy|cap|limit/i.test(field.label) && field.value.trim().length > 0);
  return [
    ['Risk', plan.risk],
    ['Approval', plan.approval],
    policyCap ? [policyCap.label, policyCap.value] : ['Route', plan.route],
  ];
}

function generatedPlanDecisionItem(label: string, value: string): string {
  return `
    <div title="${escapeHtml(value)}">
      <span>${escapeHtml(label)}</span>
      <p>${escapeHtml(value)}</p>
    </div>
  `;
}

type WalletActionSummaryRow = {
  label: string;
  value: string;
  html?: string;
  title?: string;
  tone?: 'amount' | 'effect' | 'wallet';
  copyName?: string;
  copyValue?: string;
  copyLabel?: string;
  copyActions?: SummaryCopyAction[];
};

function generatedPlanWalletActionSummary(record: GeneratedPlanRecord): string {
  const routeSummary = record.plan.actionType === 'swap'
    ? tokenRouteDisplaySummary(record.plan.parameters.inputToken || 'input', record.plan.parameters.outputToken || 'output')
    : undefined;
  const rows: WalletActionSummaryRow[] = [
    { label: 'Wallet', value: record.walletAddress || 'No wallet at creation', tone: 'wallet' },
    {
      label: 'Amount',
      value: planAmountSummary(record.plan),
      tone: 'amount',
      copyActions: record.plan.actionType === 'swap' ? undefined : planAmountTokenCopyActions(record.plan),
    },
    {
      label: routeSummary ? 'Route' : 'Recipient',
      value: routeSummary?.value ?? planRecipientOrRoute(record.plan),
      html: routeSummary?.html,
      title: routeSummary?.title,
      copyActions: routeSummary?.copyActions,
    },
  ];
  return `
    <section class="wallet-action-summary" aria-label="Wallet action summary">
      <dl class="wallet-action-grid">
        ${rows.map(walletActionSummaryRow).join('')}
      </dl>
    </section>
  `;
}

function walletActionSummaryRow(row: WalletActionSummaryRow): string {
  const copyActions = summaryCopyActions(row);
  const title = row.title ?? row.value;
  return `
    <div class="${row.tone ? `wallet-action-${row.tone}` : ''}" title="${escapeHtml(title)}">
      <dt>${escapeHtml(row.label)}</dt>
      <dd class="${copyActions.length ? 'has-copy' : ''}">
        ${row.html ?? `<span class="wallet-action-value">${escapeHtml(row.value)}</span>`}
        ${row.html ? '' : summaryCopyActionsHtml(copyActions, row.label)}
      </dd>
    </div>
  `;
}

function planGuardrailStrip(plan: AgentPlan): string {
  const report = planGuardrailReport(plan);
  if (!report) return '';
  const tone = report.verdict === 'block' ? 'block' : report.verdict === 'warn' ? 'warn' : 'pass';
  const label = report.verdict === 'block'
    ? 'Blocked'
    : report.verdict === 'warn'
      ? 'Warnings'
      : 'Passed';
  return `
    <section class="plan-guardrail-strip ${tone}" aria-label="Plan guardrails">
      <div>
        <span>Guardrails</span>
        <strong>${escapeHtml(label)}</strong>
      </div>
      <p>${escapeHtml(report.summary)}</p>
      <dl>
        ${definitionRow('Final step', finalizationRequirementLabel(report.finalizationRequirement))}
        ${definitionRow(report.constraintHash ? 'Constraint hash' : 'Constraint fingerprint', report.constraintHash ?? report.constraintFingerprint)}
      </dl>
    </section>
  `;
}

function finalizationRequirementLabel(value: string): string {
  switch (value) {
    case 'transaction_preview':
      return 'Fresh quote, simulate, wallet approve, receipt';
    case 'wallet_decision_proof':
      return 'Wallet decision proof';
    case 'none':
      return 'No wallet action';
    default:
      return value.replace(/_/g, ' ');
  }
}

function walletActionLabelForPlan(plan: AgentPlan): string {
  switch (plan.actionType) {
    case 'transfer_sol':
      return 'SOL transfer';
    case 'transfer_spl':
      return 'SPL token transfer';
    case 'swap':
      return 'Swap review';
    case 'recurring_payment':
      return 'Repeat payment';
    case 'read_only':
      return 'Read-only review';
    case 'manual_review':
      return 'Review proof';
    default:
      return plan.actionType.replace(/_/g, ' ');
  }
}

function planAmountSummary(plan: AgentPlan): string {
  if (plan.actionType === 'swap') {
    const input = plan.parameters.inputToken || planParameter(plan, ['token']) || 'Input token';
    const output = plan.parameters.outputToken || 'Output token';
    const amount = planParameter(plan, ['amount', 'inputAmount', 'plannedAmount']) || 'Amount';
    return `${amount} ${tokenDisplayLabel(input)} -> ${tokenDisplayLabel(output)}`;
  }
  if (CONNECTOR_APPROVAL_ACTION_TYPES.has(plan.actionType)) {
    return connectorPlanAmountInfo(plan)?.label ?? 'n/a';
  }
  const amount = planParameter(plan, ['amountSol', 'amount', 'plannedAmount', 'maxAmount']) || 'n/a';
  const token = planParameter(plan, ['token', 'inputToken']) || (plan.actionType === 'transfer_sol' ? 'SOL' : '');
  return token ? `${amount} ${tokenDisplayLabel(token)}` : amount;
}

function planAmountTokenCopyActions(plan: AgentPlan): SummaryCopyAction[] {
  if (CONNECTOR_APPROVAL_ACTION_TYPES.has(plan.actionType)) {
    const token = connectorPlanAmountInfo(plan)?.token ?? '';
    return token ? tokenCopyActions(token, 'Copy token', 'Token mint') : [];
  }
  const token = planParameter(plan, ['token', 'inputToken']) || (plan.actionType === 'transfer_sol' ? 'SOL' : '');
  return token ? tokenCopyActions(token, 'Copy token', 'Token mint') : [];
}

function connectorPlanAmountInfo(plan: AgentPlan): ConnectorActionAmountInfo | undefined {
  const liquidity = connectorPlanLiquidityAmountInfo(plan);
  if (liquidity) return liquidity;
  const solAmountKey = [
    'bidPriceSol',
    'priceSol',
    'maxPriceSol',
    'maxPricePerNftSol',
    'amountSol',
    'solAmount',
    'maxEscrowSol',
  ].find((key) => planParameter(plan, [key]));
  if (solAmountKey) {
    const amount = planParameter(plan, [solAmountKey]);
    return {
      amount,
      label: `${amount} SOL`,
      token: 'SOL',
      marketToken: 'SOL',
    };
  }
  const amount = planParameter(plan, [
    'amount',
    'inputAmount',
    'plannedAmount',
    'maxAmount',
    'collateralAmount',
    'borrowAmount',
    'makingAmount',
    'takingAmount',
    'liquidityAmount',
    'shares',
    'percentage',
  ]);
  if (!amount) return undefined;
  const token = connectorPlanAmountToken(plan);
  const displayToken = token ? connectorActionAmountTokenLabel(token.value) : '';
  return {
    amount,
    label: displayToken && !/[a-z%]/i.test(amount) ? `${amount} ${displayToken}` : amount,
    ...(displayToken ? { token: displayToken } : {}),
    ...(token?.marketEligible ? { marketToken: token.value } : {}),
  };
}

function connectorPlanLiquidityAmountInfo(plan: AgentPlan): ConnectorActionAmountInfo | undefined {
  if (plan.actionType === 'meteora_add_liquidity') return meteoraPlanAddLiquidityAmountInfo(plan);
  if (plan.actionType !== 'orca_increase_liquidity' && plan.actionType !== 'raydium_add_liquidity') return undefined;
  const tokenAAmount = planParameter(plan, ['tokenAAmount']);
  const tokenBAmount = planParameter(plan, ['tokenBAmount']);
  const maxTokenAAmount = planParameter(plan, ['maxTokenAAmount']);
  const maxTokenBAmount = planParameter(plan, ['maxTokenBAmount']);
  const tokenA = connectorPlanLiquidityTokenSymbol(plan, 'tokenA');
  const tokenB = connectorPlanLiquidityTokenSymbol(plan, 'tokenB');
  return connectorLiquidityAmountInfo({
    tokenAAmount,
    tokenBAmount,
    maxTokenAAmount,
    maxTokenBAmount,
    tokenA,
    tokenB,
    pairLabel: connectorPlanLiquidityPairLabel(plan),
  });
}

function meteoraPlanAddLiquidityAmountInfo(plan: AgentPlan): ConnectorActionAmountInfo | undefined {
  const tokenXAmount = planParameter(plan, ['tokenXAmount']);
  const tokenYAmount = planParameter(plan, ['tokenYAmount']);
  const tokenX = meteoraPlanPoolTokenSymbol(plan, 'x') ?? 'token X';
  const tokenY = meteoraPlanPoolTokenSymbol(plan, 'y') ?? 'token Y';
  const parts = [
    tokenXAmount ? `${tokenXAmount} ${connectorActionAmountTokenLabel(tokenX)}` : '',
    tokenYAmount ? `${tokenYAmount} ${connectorActionAmountTokenLabel(tokenY)}` : '',
  ].filter(Boolean);
  if (!parts.length) return undefined;
  return {
    amount: parts.join(' + '),
    label: parts.join(' + '),
    token: meteoraPlanPoolTokenLabel(plan),
  };
}

function meteoraPlanPoolTokenSymbol(plan: AgentPlan, side: 'x' | 'y'): string | undefined {
  const symbolKey = side === 'x' ? 'tokenXSymbol' : 'tokenYSymbol';
  const mintKey = side === 'x' ? 'tokenMintX' : 'tokenMintY';
  const symbol = planParameter(plan, [symbolKey]);
  if (symbol) return symbol;
  const mint = planParameter(plan, [mintKey]);
  if (mint) return resolveTokenDisplay(mint) || tokenDisplayLabel(mint);
  const label = planParameter(plan, ['poolAddressLabel']) || planParameter(plan, ['poolName']);
  return meteoraPairSymbolFromLabel(label, side);
}

function meteoraPlanPoolTokenLabel(plan: AgentPlan): string {
  const explicit = planParameter(plan, ['poolName']) || planParameter(plan, ['poolAddressLabel']);
  if (explicit) return /\bDLMM\b/i.test(explicit) ? explicit : `${explicit} DLMM`;
  const tokenX = meteoraPlanPoolTokenSymbol(plan, 'x');
  const tokenY = meteoraPlanPoolTokenSymbol(plan, 'y');
  if (tokenX && tokenY) return `${tokenDisplayLabel(tokenX)}-${tokenDisplayLabel(tokenY)} DLMM`;
  return planParameter(plan, ['poolAddress']) || 'Meteora DLMM';
}

function connectorPlanAmountToken(plan: AgentPlan): ConnectorActionAmountToken | undefined {
  const params = plan.parameters;
  const labeledToken = connectorAmountTokenFromTargetLabels((key) => planParameter(plan, [key]));
  if (labeledToken) return labeledToken;
  const tokenKeys = [
    'sourceTokenLabel',
    'tokenLabel',
    'tokenSymbol',
    'depositSymbol',
    'inputSymbol',
    'outputSymbol',
    'token',
    'sourceToken',
    'inputToken',
    'sourceMint',
    'assetMint',
    'assetMintSymbol',
    'assetMintLabel',
    'mint',
    'mintAddress',
    'mintAddressSymbol',
    'mintAddressLabel',
    'inputMint',
    'inputMintSymbol',
    'inputMintLabel',
    'depositMint',
    'lstMint',
    'lstMintSymbol',
    'lstMintLabel',
    'inputLstMint',
    'governingTokenMint',
    'governingTokenMintSymbol',
    'governingTokenMintLabel',
    'vaultAddressSymbol',
    'vaultAddressMint',
    'reserveAddressSymbol',
    'reserveAddressMint',
    'bankAddressSymbol',
    'bankAddressMint',
  ];
  for (const key of tokenKeys) {
    const value = planParameter(plan, [key]);
    if (value) return { value, marketEligible: true };
  }
  for (const key of ['bankAddress', 'reserveAddress']) {
    const label = params[`${key}Label`]?.trim();
    if (label) return { value: label, marketEligible: true };
    const value = planParameter(plan, [key]);
    if (value && !looksLikeMintAddress(value)) return { value, marketEligible: true };
  }
  return undefined;
}

function planRecipientOrRoute(plan: AgentPlan): string {
  const recipient = planParameter(plan, ['recipient', 'recipientAddress', 'settlementWallet']);
  if (recipient) return recipientDisplayLabel(recipient);
  if (plan.actionType === 'swap') {
    return tokenRouteDisplaySummary(plan.parameters.inputToken || 'input', plan.parameters.outputToken || 'output').value;
  }
  if (CONNECTOR_APPROVAL_ACTION_TYPES.has(plan.actionType)) {
    const target = connectorPlanTargetSummary(plan);
    if (target) return target.value;
    const connectorDisplay = connectorActionDisplayParts(plan.actionType, plan.parameters);
    return connectorDisplay?.selectionLabel || connectorDisplay?.operationLabel || plan.route;
  }
  return plan.route;
}

function generatedPlanDestinationLabel(record: GeneratedPlanRecord): string {
  if (record.preparedActionId) {
    return workflowSourceLabel(record.workflowSource);
  }
  return activeWorkflowLabel();
}

function workflowSourceLabel(source: WorkflowRecordSource | undefined): string {
  switch (source) {
    case 'cloud':
      return 'Agentic Cloud workspace';
    case 'local-bridge':
      return 'Private local mode';
    case 'browser':
      return 'Saved on this device';
    default:
      return activeWorkflowLabel();
  }
}

function generatedPlanEffectLabel(record: GeneratedPlanRecord): string {
  const plan = record.plan;
  const report = planGuardrailReport(plan);
  if (report?.verdict === 'block') {
    return 'Blocked by guardrails. Recreate or edit the plan before sending for approval.';
  }
  if (!canQueueAgentPlan(plan)) {
    return 'Signs review evidence only. No approval, transaction, or funds movement.';
  }
  if (plan.actionType === 'recurring_payment') {
    return 'Creates a repeat payment. Each payment still needs wallet review.';
  }
  const source = record.workflowSource ?? (activeWorkflowMode() === 'agentic-cloud' ? 'cloud' : activeWorkflowMode() === 'local-bridge' ? 'local-bridge' : 'browser');
  if (source === 'local-bridge') {
    return 'Creates a local approval request. The wallet still approves the final request.';
  }
  if (source === 'cloud') {
    return 'Creates a cloud approval request. A later wallet proof records approve or deny.';
  }
  return 'Creates a saved-on-device approval request. A later wallet proof records approve or deny.';
}

function generatedPlanFact(label: string, value: string): string {
  return `
    <div title="${escapeHtml(value)}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

function generatedPlanInlineDetails(plan: AgentPlan, detailsCount: number): string {
  if (detailsCount === 0) return '';
  return `
    <details class="generated-plan-inline-details">
      <summary>${escapeHtml(`${detailsCount} review details`)}</summary>
      <div>
        ${plan.userNotes ? generatedPlanMiniSection('User notes', [plan.userNotes]) : ''}
        ${plan.fields.length ? generatedPlanMiniSection('Fields', plan.fields.map((field) => `${field.label}: ${field.value}`)) : ''}
        ${plan.safeguards.length ? generatedPlanMiniSection('Safeguards', plan.safeguards) : ''}
      </div>
    </details>
  `;
}

function generatedPlanMiniSection(label: string, values: string[]): string {
  return `
    <section>
      <span>${escapeHtml(label)}</span>
      <ul>
        ${values.map((value) => `<li>${escapeHtml(value)}</li>`).join('')}
      </ul>
    </section>
  `;
}

function generatedPlanOutcomeStrip(record: GeneratedPlanRecord): string {
  if (!record.signature && !record.preparedActionId) return '';
  return `
    <div class="generated-plan-outcomes">
      ${record.signature ? `<span title="${escapeHtml(record.signature)}">Proof ${escapeHtml(short(record.signature))}</span>` : ''}
      ${record.preparedActionId ? `<span title="${escapeHtml(record.preparedActionId)}">Approval ${escapeHtml(short(record.preparedActionId))}</span>` : ''}
    </div>
  `;
}

function generatedPlanActionHint(record: GeneratedPlanRecord): string {
  if (record.status === 'archived') return '';
  const report = planGuardrailReport(record.plan);
  if (report?.verdict === 'block') {
    return `<p class="generated-plan-action-helper danger">${escapeHtml(report.summary)}</p>`;
  }
  if (!state.address) {
    return canQueueAgentPlan(record.plan)
      ? '<p class="generated-plan-action-helper">Connect a wallet to send this plan for approval.</p>'
      : '<p class="generated-plan-action-helper">Connect a wallet to sign a review proof.</p>';
  }
  const mode = activeWorkflowMode();
  if (canQueueAgentPlan(record.plan) && mode === 'agentic-cloud') {
    return '<p class="generated-plan-action-helper">Signed in: this will use Agentic Cloud and still require wallet approval.</p>';
  }
  if (canQueueAgentPlan(record.plan) && mode === 'browser-workflow') {
    return '<p class="generated-plan-action-helper">Signed out: this will use saved-on-device storage in this browser.</p>';
  }
  if (!canQueueAgentPlan(record.plan)) {
    return '<p class="generated-plan-action-helper">Review-only plan: sign a proof to complete it. It will not need approval.</p>';
  }
  return '';
}

function bridgeRequiredNotice(message: string): string {
  if (state.bridgeActive) return '';
  return `
    <div class="bridge-required-notice">
      <p>${escapeHtml(message)}</p>
      <div class="bridge-required-actions">
        <button type="button" class="utility" data-bridge-action="connect" ${!state.address || state.busy ? 'disabled' : ''}>Check local bridge</button>
        ${bridgeSetupDetails('inline-bridge-setup', true)}
      </div>
    </div>
  `;
}

function bridgeSetupDetails(extraClass = '', open = false): string {
  return `
    <details class="bridge-setup-details ${escapeHtml(extraClass)}" ${open ? 'open' : ''}>
      <summary>Start local runtime</summary>
      <div class="bridge-setup-card">
        ${localRuntimeGuide('setup-popover')}
      </div>
    </details>
  `;
}

function localRuntimeGuide(extraClass = ''): string {
  return `
    <div class="local-runtime-guide ${escapeHtml(extraClass)}">
      <div class="local-runtime-guide-head">
        <span>Required on this computer</span>
        <strong>${escapeHtml(compactEndpoint(state.bridgeUrl))}</strong>
      </div>
      <p>This website cannot start the approval bridge directly. Start the local runtime, keep that terminal window open, then return here and click Check local bridge.</p>
      <ol class="local-runtime-steps">
        <li>Copy and run the one-shot command in Terminal.</li>
        <li>Connect your wallet in the browser tab it opens.</li>
        <li>Come back here and check the local bridge.</li>
      </ol>
      <span class="local-runtime-command-label">Install once or use CLI</span>
      <div class="bridge-command-row primary-runtime-command">
        <code>${escapeHtml(NPM_EXEC_COMMAND)}</code>
        <button type="button" data-copy="${escapeHtml(NPM_EXEC_COMMAND)}" data-copy-name="local runtime command">Copy</button>
      </div>
      <details class="local-runtime-alt">
        <summary>Install CLI once or use Desktop App</summary>
        <div class="local-runtime-alt-body">
          <span class="local-runtime-alt-label">Install CLI globally</span>
          <div class="bridge-command-row">
            <code>${escapeHtml(NPM_GLOBAL_INSTALL_COMMAND)}</code>
            <button type="button" data-copy="${escapeHtml(NPM_GLOBAL_INSTALL_COMMAND)}" data-copy-name="CLI install command">Copy</button>
          </div>
          <span class="local-runtime-alt-label">Run installed CLI</span>
          <div class="bridge-command-row">
            <code>${escapeHtml(INSTALLED_APP_COMMAND)}</code>
            <button type="button" data-copy="${escapeHtml(INSTALLED_APP_COMMAND)}" data-copy-name="installed CLI command">Copy</button>
          </div>
          <a class="button-link local-runtime-desktop-link" href="/desktop">Desktop App downloads</a>
        </div>
      </details>
    </div>
  `;
}

function cloudWorkspaceDeleteModal(): string {
  if (!state.cloudWorkspaceDeleteModalOpen) return '';
  const wallet = state.cloudSession.status === 'signed-in'
    ? short(state.cloudSession.walletAddress)
    : 'this wallet';
  return `
    <div class="generated-plan-modal-backdrop cloud-delete-modal-backdrop delete-confirmation-backdrop" role="presentation">
      <section class="generated-plan-modal cloud-delete-modal delete-confirmation-modal" role="dialog" aria-modal="true" aria-labelledby="cloud-delete-title">
        <div class="generated-plan-modal-head">
          <div>
            <span class="workbench-kicker">Cloud workspace deletion</span>
            <h2 id="cloud-delete-title">Delete Cloud Workspace Data?</h2>
            <p>This permanently removes the Agentic Cloud workspace for ${escapeHtml(wallet)}.</p>
          </div>
          <button class="utility" data-cloud-delete-cancel aria-label="Close cloud deletion confirmation">Close</button>
        </div>
        <div class="cloud-delete-warning delete-confirmation-content">
          <strong>Requires wallet signature</strong>
          <p>Cloud drafts, approval items, repeat payments, proofs, done work, finalization records, and app audit events for this wallet will be deleted. Saved-on-device data and on-chain history are not deleted.</p>
        </div>
        <div class="generated-plan-modal-actions cloud-delete-actions">
          <button type="button" class="utility" data-cloud-delete-cancel ${state.busy ? 'disabled' : ''}>Cancel</button>
          <button type="button" class="utility danger" data-cloud-delete-confirm ${state.busy ? 'disabled' : ''}>Sign and delete cloud data</button>
        </div>
      </section>
    </div>
  `;
}

function completedDeleteModal(): string {
  if (!state.completedDeleteModalId) return '';
  const record = completedPlanRecords().find((candidate) => candidate.id === state.completedDeleteModalId);
  if (!record) return '';
  const source = record.workflowSource === 'cloud'
    ? 'Agentic Cloud'
    : record.workflowSource === 'local-bridge'
      ? 'the local bridge archive'
      : 'this browser';
  const descriptor = [
    record.kind === 'recurring' ? 'Repeat payment' : 'One-time approval',
    record.status,
    formatDateTime(record.completedAt),
  ].join(' - ');
  return `
    <div class="generated-plan-modal-backdrop completed-delete-modal-backdrop delete-confirmation-backdrop" role="presentation">
      <section class="generated-plan-modal completed-delete-modal delete-confirmation-modal" role="dialog" aria-modal="true" aria-labelledby="completed-delete-title">
        <div class="generated-plan-modal-head">
          <div>
            <span class="workbench-kicker">Done deletion</span>
            <h2 id="completed-delete-title">Delete from Done?</h2>
            <p>${escapeHtml(record.title)}</p>
          </div>
          <button class="utility" data-completed-delete-cancel aria-label="Close Done deletion confirmation">Close</button>
        </div>
        <div class="completed-delete-warning delete-confirmation-content">
          <strong>${escapeHtml(descriptor)}</strong>
          <p>This removes the saved Done card and linked local metadata from ${escapeHtml(source)}. On-chain history is not deleted.</p>
        </div>
        <div class="generated-plan-modal-actions completed-delete-actions">
          <button type="button" class="utility" data-completed-delete-cancel ${state.busy ? 'disabled' : ''}>Cancel</button>
          <button type="button" class="utility danger" data-completed-delete-confirm="${escapeHtml(record.id)}" ${state.busy ? 'disabled' : ''}>Delete item</button>
        </div>
      </section>
    </div>
  `;
}

function generatedPlanDeleteModal(): string {
  if (!state.generatedPlanDeleteModalId) return '';
  const record = generatedPlanById(state.generatedPlanDeleteModalId);
  if (!record) return '';
  const status = record.status === 'archived' ? 'Archived draft' : generatedPlanStatusLabel(record);
  return `
    <div class="generated-plan-modal-backdrop generated-plan-delete-modal-backdrop delete-confirmation-backdrop" role="presentation">
      <section class="generated-plan-modal generated-plan-delete-modal delete-confirmation-modal" role="dialog" aria-modal="true" aria-labelledby="generated-plan-delete-title">
        <div class="generated-plan-modal-head">
          <div>
            <span class="workbench-kicker">Check deletion</span>
            <h2 id="generated-plan-delete-title">Delete from Check?</h2>
            <p>${escapeHtml(record.plan.templateTitle || record.plan.intent)}</p>
          </div>
          <button class="utility" data-generated-plan-delete-cancel aria-label="Close Check deletion confirmation">Close</button>
        </div>
        <div class="generated-plan-delete-warning delete-confirmation-content">
          <strong>${escapeHtml(status)}</strong>
          <p>This removes the draft from Check and linked local planning state. If it already produced a receipt or approval, those records stay in Done.</p>
        </div>
        <div class="generated-plan-modal-actions generated-plan-delete-actions">
          <button type="button" class="utility" data-generated-plan-delete-cancel ${state.busy ? 'disabled' : ''}>Cancel</button>
          <button type="button" class="utility danger" data-generated-plan-delete-confirm="${escapeHtml(record.id)}" ${state.busy ? 'disabled' : ''}>Delete plan</button>
        </div>
      </section>
    </div>
  `;
}

function inboxDeleteModal(): string {
  if (!state.inboxDeleteModalId) return '';
  const action = state.preparedActions.find((candidate) => candidate.id === state.inboxDeleteModalId);
  if (!action) return '';
  const title = preparedActionCardTitle(action);
  return `
    <div class="generated-plan-modal-backdrop inbox-delete-modal-backdrop delete-confirmation-backdrop" role="presentation">
      <section class="generated-plan-modal inbox-delete-modal delete-confirmation-modal" role="dialog" aria-modal="true" aria-labelledby="inbox-delete-title">
        <div class="generated-plan-modal-head">
          <div>
            <span class="workbench-kicker">Needs Approval deletion</span>
            <h2 id="inbox-delete-title">Delete this approval request?</h2>
            <p>${escapeHtml(title)}</p>
          </div>
          <button class="utility" data-inbox-delete-cancel aria-label="Close Needs Approval deletion confirmation">Close</button>
        </div>
        <div class="completed-delete-warning delete-confirmation-content">
          <strong>This request will be removed entirely.</strong>
          <p>Cloud and local copies are deleted. No receipt is saved in Done because the request was neither approved nor denied.</p>
        </div>
        <div class="generated-plan-modal-actions completed-delete-actions">
          <button type="button" class="utility" data-inbox-delete-cancel ${state.busy ? 'disabled' : ''}>Cancel</button>
          <button type="button" class="utility danger" data-inbox-delete-confirm="${escapeHtml(action.id)}" ${state.busy ? 'disabled' : ''}>Delete request</button>
        </div>
      </section>
    </div>
  `;
}

function deleteAllInboxModal(): string {
  if (!state.deleteAllInboxModalOpen) return '';
  const count = filteredPreparedActions().length;
  const filterNote = state.inboxFilter === 'all'
    ? ''
    : ` matching the ${escapeHtml(state.inboxFilter)} filter`;
  return `
    <div class="generated-plan-modal-backdrop delete-all-modal-backdrop delete-confirmation-backdrop" role="presentation">
      <section class="generated-plan-modal delete-all-modal delete-confirmation-modal" role="dialog" aria-modal="true" aria-labelledby="delete-all-inbox-title">
        <div class="generated-plan-modal-head">
          <div>
            <span class="workbench-kicker">Clear Needs Approval</span>
            <h2 id="delete-all-inbox-title">Delete ${count} visible request${count === 1 ? '' : 's'}?</h2>
            <p>${count === 0 ? 'No visible requests to delete.' : `Every visible approval request${filterNote} will be removed.`}</p>
          </div>
          <button class="utility" data-delete-all-inbox-cancel aria-label="Close Needs Approval bulk deletion">Close</button>
        </div>
        <div class="completed-delete-warning delete-confirmation-content">
          <strong>This cannot be undone.</strong>
          <p>Cloud and local copies are deleted. No receipts are left in Done because the requests were neither approved nor denied. Items already in Done are not affected.</p>
        </div>
        <div class="generated-plan-modal-actions completed-delete-actions">
          <button type="button" class="utility" data-delete-all-inbox-cancel ${state.busy ? 'disabled' : ''}>Cancel</button>
          <button type="button" class="utility danger" data-delete-all-inbox-confirm ${state.busy || count === 0 ? 'disabled' : ''}>Delete all ${count}</button>
        </div>
      </section>
    </div>
  `;
}

