function runGuidedDemoAction(action: string): void {
  const currentScenarioId = state.guidedDemo.selectedScenarioId;
  switch (action) {
    case 'prepare':
      clearGuidedDemoSwapFlowTimer();
      clearGuidedDemoAgentFlowTimer();
      if (selectedGuidedDemoScenario().id === 'policy-swap') {
        startGuidedDemoAgentFlow();
        return;
      }
      state.guidedDemo = {
        ...defaultGuidedDemoState(currentScenarioId),
        stage: 'prepared',
      };
      pushToast('success', 'Demo request prepared', 'Review the constraints, then move it to wallet review.');
      render();
      return;
    case 'queue':
      clearGuidedDemoSwapFlowTimer();
      clearGuidedDemoAgentFlowTimer();
      state.guidedDemo = {
        ...state.guidedDemo,
        stage: 'queued',
        decision: 'pending',
        receiptId: '',
        receiptCreatedAt: '',
        receiptJson: '',
        signedReceipt: '',
      };
      pushToast('success', 'Moved to wallet review', 'Approve or deny the simulated request.');
      render();
      return;
    case 'approve':
      clearGuidedDemoAgentFlowTimer();
      if (selectedGuidedDemoScenario().id === 'policy-swap') {
        startGuidedDemoSwapFlow();
        return;
      }
      completeGuidedDemo('approved');
      return;
    case 'deny':
      clearGuidedDemoSwapFlowTimer();
      clearGuidedDemoAgentFlowTimer();
      completeGuidedDemo('denied');
      return;
    case 'reset':
      clearGuidedDemoSwapFlowTimer();
      clearGuidedDemoAgentFlowTimer();
      state.guidedDemo = defaultGuidedDemoState(currentScenarioId);
      pushToast('success', 'Demo reset', 'Choose a scenario or prepare the current one again.');
      render();
      return;
    default:
      return;
  }
}

function clearGuidedDemoSwapFlowTimer(): void {
  guidedDemoSwapFlowRunId += 1;
  if (guidedDemoSwapFlowTimer !== undefined) {
    window.clearTimeout(guidedDemoSwapFlowTimer);
    guidedDemoSwapFlowTimer = undefined;
  }
}

function clearGuidedDemoAgentFlowTimer(): void {
  guidedDemoAgentFlowRunId += 1;
  if (guidedDemoAgentFlowTimer !== undefined) {
    window.clearTimeout(guidedDemoAgentFlowTimer);
    guidedDemoAgentFlowTimer = undefined;
  }
}

function startGuidedDemoAgentFlow(): void {
  clearGuidedDemoAgentFlowTimer();
  const runId = guidedDemoAgentFlowRunId;
  state.guidedDemo = {
    ...defaultGuidedDemoState(state.guidedDemo.selectedScenarioId),
    agentFlowStep: 'asking',
  };
  render();
  scheduleGuidedDemoAgentFlowStep(runId, 'drafting');
}

function scheduleGuidedDemoAgentFlowStep(runId: number, step: GuidedDemoAgentFlowStep | 'approved'): void {
  guidedDemoAgentFlowTimer = window.setTimeout(() => {
    if (runId !== guidedDemoAgentFlowRunId || selectedGuidedDemoScenario().id !== 'policy-swap') return;
    if (step === 'approved') {
      state.guidedDemo = {
        ...state.guidedDemo,
        stage: 'prepared',
        agentFlowStep: 'idle',
      };
      guidedDemoAgentFlowTimer = undefined;
      render();
      return;
    }
    state.guidedDemo = {
      ...state.guidedDemo,
      agentFlowStep: step,
    };
    render();
    scheduleGuidedDemoAgentFlowStep(runId, step === 'drafting' ? 'reviewing' : 'approved');
  }, GUIDED_DEMO_AGENT_FLOW_DELAY_MS);
}

function startGuidedDemoSwapFlow(): void {
  clearGuidedDemoSwapFlowTimer();
  const runId = guidedDemoSwapFlowRunId;
  state.guidedDemo = {
    ...state.guidedDemo,
    swapFlowStep: 'preparing',
  };
  render();
  scheduleGuidedDemoSwapFlowStep(runId, 'signing');
}

function scheduleGuidedDemoSwapFlowStep(runId: number, step: GuidedDemoSwapFlowStep): void {
  guidedDemoSwapFlowTimer = window.setTimeout(() => {
    if (runId !== guidedDemoSwapFlowRunId || selectedGuidedDemoScenario().id !== 'policy-swap') return;
    if (step === 'confirmed') {
      state.guidedDemo = {
        ...state.guidedDemo,
        swapFlowStep: 'confirmed',
      };
      completeGuidedDemo('approved', { toast: false });
      guidedDemoSwapFlowTimer = undefined;
      return;
    }
    state.guidedDemo = {
      ...state.guidedDemo,
      swapFlowStep: step,
    };
    render();
    scheduleGuidedDemoSwapFlowStep(runId, step === 'signing' ? 'sending' : 'confirmed');
  }, GUIDED_DEMO_SWAP_FLOW_DELAY_MS);
}

function completeGuidedDemo(
  decision: Exclude<GuidedDemoDecision, 'pending'>,
  options: { toast?: boolean } = {},
): void {
  const scenario = selectedGuidedDemoScenario();
  const receiptId = newId('demo');
  const receiptCreatedAt = new Date().toISOString();
  const mockSignature = scenario.id === 'policy-swap' && decision === 'approved'
    ? `demo_sig_${receiptId.replace(/[^a-z0-9_-]/gi, '').slice(0, 32)}`
    : '';
  state.guidedDemo = {
    ...state.guidedDemo,
    stage: 'receipt',
    decision,
    receiptId,
    receiptCreatedAt,
    receiptJson: stableJson(guidedDemoReceiptPayload(scenario, decision, receiptId, receiptCreatedAt, mockSignature)),
    signedReceipt: mockSignature,
  };
  if (options.toast !== false) {
    pushToast(
      'success',
      decision === 'approved' ? 'Simulation approved' : 'Simulation denied',
      mockSignature ? 'Demo signature and approval receipt saved.' : 'Demo receipt created. Nothing was signed or submitted.',
    );
  }
  render();
}

function guidedDemoReceiptPayload(
  scenario: GuidedDemoScenario,
  decision: GuidedDemoDecision,
  receiptId: string,
  createdAt: string,
  signature = '',
): Record<string, unknown> {
  return {
    version: 'agentic-demo-v1',
    demoOnly: true,
    receiptId,
    receiptType: scenario.receiptType,
    createdAt,
    cluster: state.cluster,
    wallet: state.address || 'demo-wallet',
    decision,
    scenario: {
      id: scenario.id,
      title: scenario.title,
      request: scenario.prompt,
    },
    route: scenario.route,
    constraints: scenario.constraints,
    risk: scenario.risk,
    approvalBoundary: scenario.approvalBoundary,
    summary: scenario.receiptSummary,
    signature: signature || undefined,
  };
}

async function runSignGuidedDemoReceipt(): Promise<void> {
  await run('sign', async () => {
    if (state.guidedDemo.stage !== 'receipt' || !state.guidedDemo.receiptJson) {
      throw new Error('Complete the demo decision before signing a demo receipt.');
    }
    const signingMessage = [
      'Agentic demo receipt',
      `Receipt: ${state.guidedDemo.receiptId}`,
      state.guidedDemo.receiptJson,
    ].join('\n');
    const result = await signWalletProofMessage(signingMessage, 'Demo receipt signature', state.cluster);
    const scenario = selectedGuidedDemoScenario();
    state.guidedDemo.signedReceipt = result.signature;
    state.guidedDemo.receiptJson = stableJson(
      guidedDemoReceiptPayload(
        scenario,
        state.guidedDemo.decision,
        state.guidedDemo.receiptId,
        state.guidedDemo.receiptCreatedAt,
        result.signature,
      ),
    );
    pushToast('success', 'Demo receipt signed', 'Signature saved only inside this simulated demo.');
  });
}

async function runSignMessage(): Promise<void> {
  await run('sign', async () => {
    const result = await signWalletProofMessage(DEMO_MESSAGE, 'Home message signature', state.cluster);
    state.signature = result.signature;
    pushToast('success', 'Message signed', short(result.signature));
  });
}

async function runAirdrop(): Promise<void> {
  await run('transaction', async () => {
    if (state.cluster !== 'devnet') {
      throw new Error('Devnet SOL is available only when the cluster is devnet.');
    }
    const publicKey = publicKeyFromConnectedWallet();
    state.transactionStatus = 'Requesting 1 devnet SOL from the Solana faucet...';
    render();

    const connection = new Connection(defaultRpcUrl('devnet'), 'confirmed');
    const signature = await connection.requestAirdrop(publicKey, 1_000_000_000);
    await connection.confirmTransaction(signature, 'confirmed');

    state.transactionStatus = `Airdrop confirmed: ${short(signature)}. Create and sign a demo transaction now.`;
    pushToast('success', 'Devnet SOL requested', short(signature));
  });
}

async function runCreateDemoTransaction(): Promise<void> {
  await run('transaction', async () => {
    if (state.cluster !== 'devnet') {
      throw new Error('The built-in memo transaction is devnet-only.');
    }
    const feePayer = publicKeyFromConnectedWallet();
    const connection = new Connection(defaultRpcUrl('devnet'), 'confirmed');
    const balance = await connection.getBalance(feePayer, 'confirmed');
    if (balance === 0) {
      state.transactionStatus = 'This devnet account has 0 SOL. Request devnet SOL before signing the demo transaction.';
      throw new Error('Not enough devnet SOL for transaction fees. Click Request devnet SOL, then try again.');
    }

    const { blockhash } = await connection.getLatestBlockhash();
    const tx = new Transaction({
      feePayer,
      recentBlockhash: blockhash,
    }).add(
      new TransactionInstruction({
        keys: [{ pubkey: feePayer, isSigner: true, isWritable: false }],
        programId: MEMO_PROGRAM_ID,
        data: new TextEncoder().encode(DEMO_MEMO) as unknown as InstructionData,
      }),
    );

    state.customTransactionBase64 = encodeBase64(
      tx.serialize({
        requireAllSignatures: false,
        verifySignatures: false,
      }),
    );
    state.txSignature = '';
    state.txid = '';
    state.transactionStatus = 'Demo transaction created. Sign it without broadcasting, or sign and send it on devnet.';
    pushToast('success', 'Transaction created', 'Demo transaction ready.');
  });
}

async function runSignTransaction(): Promise<void> {
  await run('transaction', async () => {
    const signingClient = requireClient();
    state.transactionStatus = 'Opening wallet approval for transaction signature...';
    const result = await signingClient.signTransaction(
      state.customTransactionBase64,
      signOptions('Transaction signature request'),
    );
    state.txSignature = result.signature;
    state.txid = '';
    state.transactionStatus = 'Transaction signed by wallet. The signed transaction bytes were not broadcast.';
    pushToast('success', 'Transaction signed', 'Signed bytes returned.');
  });
}

async function runSignAndSendTransaction(): Promise<void> {
  await run('transaction', async () => {
    const signingClient = requireClient();
    if (!state.capabilities?.supports.signAndSendTransaction) {
      throw new Error('Selected wallet does not support sign and send.');
    }

    state.transactionStatus = `Opening wallet approval to sign and send on ${state.cluster}...`;
    const result = await signingClient.signAndSendTransaction(
      state.customTransactionBase64,
      signOptions('Transaction broadcast request'),
    );
    state.txid = result.txid ?? result.signature;
    state.txSignature = '';
    state.transactionStatus = 'Transaction sent. The transaction id is shown below.';
    pushToast('success', 'Transaction sent', short(state.txid));
  });
}

async function runGenerateAgentPlan(): Promise<void> {
  const template = selectedTemplate();
  trackGenerateTemplatePlan(template.id);
  state.activeOperation = 'generate-template-plan';
  const toastId = pushToast('pending', 'Creating template plan', 'Preparing a saved plan for review.');
  let reviewAfterDraftId = '';
  try {
    await run(
      'sign',
      async () => {
        const parameters = normalizeConnectorDraftParameters(template, readTemplateFields(template));
        state.templateFields = parameters;
        const userNotes = state.agentPrompt.trim();
        assertValidTemplatePlanInput(template, parameters, userNotes, { mode: 'template' });
        state.templateFields = parameters;
        const plan = planWithRuntimeTokenLabels(buildTemplatePlan(template, parameters, 'template', userNotes));
        state.agentPlan = plan;
        state.agentSignature = '';
        state.agentPreparedActionId = '';
        const record = await saveGeneratedPlan(plan, template, userNotes || template.description);
        state.selectedGeneratedPlanId = record.id;
        state.oneTimePlanView = 'review';
        if (state.askAgentAfterDraft && (hasDetectedAgentReviewPath() || isMockPreSignPolicyPlan(record))) {
          reviewAfterDraftId = record.id;
        }
        replaceToast(toastId, 'success', 'Plan created', `${template.title} is ready in Check request.`);
      },
      { onError: (message) => replaceToast(toastId, 'error', 'Template plan failed', message) },
    );
  } finally {
    state.activeOperation = null;
    render();
  }
  if (reviewAfterDraftId) {
    await runReviewGeneratedPlan(reviewAfterDraftId);
  }
}

function startAiDraftOperation(templateTitle: string, prompt: string, toastId: number): ActiveAiDraftOperation {
  const operation: ActiveAiDraftOperation = {
    id: nextAiDraftOperationId,
    controller: new AbortController(),
    toastId,
    templateTitle,
    prompt,
    cancelled: false,
    planRecordId: '',
  };
  nextAiDraftOperationId += 1;
  activeAiDraftOperation = operation;
  state.activeOperation = 'generate-ai-plan';
  state.steps.ai = 'active';
  state.error = '';
  return operation;
}

const AI_DRAFT_PLACEHOLDER_LABEL = 'Drafting…';
const AI_DRAFT_FAILED_LABEL = 'AI draft failed — try again';

function placeholderAgentPlanFromTemplate(
  template: AgentPlanTemplate,
  parameters: Record<string, string>,
  userNotes: string,
): AgentPlan {
  return {
    intent: userNotes || template.description || `Drafting ${template.title}…`,
    route: template.route || '',
    risk: template.riskText || template.risk || 'Medium',
    approval: template.approval || 'Pending agent draft.',
    source: 'ai',
    category: template.category,
    actionType: template.actionType,
    templateTitle: template.title,
    userNotes,
    parameters,
    fields: [],
    safeguards: template.safeguards ? [...template.safeguards] : [],
  };
}

function materializeAiDraftPlaceholder(
  template: AgentPlanTemplate,
  parameters: Record<string, string>,
  userNotes: string,
): string {
  const now = new Date().toISOString();
  const placeholder: GeneratedPlanRecord = {
    id: newId('plan'),
    plan: placeholderAgentPlanFromTemplate(template, parameters, userNotes),
    createdAt: now,
    updatedAt: now,
    source: 'ai',
    templateId: template.id,
    templateTitle: template.title,
    prompt: userNotes || template.description,
    walletAddress: state.address,
    cluster: state.cluster,
    status: 'draft',
    failureLabel: AI_DRAFT_PLACEHOLDER_LABEL,
    workflowSource: activeWorkflowMode() === 'local-bridge' ? 'local-bridge' : 'browser',
  };
  state.generatedPlans = mergeGeneratedPlans([placeholder], state.generatedPlans);
  saveGeneratedPlans();
  return placeholder.id;
}

function removeGeneratedPlanLocally(planId: string): void {
  if (!planId) return;
  if (!state.generatedPlans.some((record) => record.id === planId)) return;
  state.generatedPlans = state.generatedPlans.filter((record) => record.id !== planId);
  if (state.selectedGeneratedPlanId === planId) {
    state.selectedGeneratedPlanId = '';
  }
  saveGeneratedPlans();
}

function cancelActiveAiDraft(): void {
  const operation = activeAiDraftOperation;
  if (!operation || state.activeOperation !== 'generate-ai-plan') return;
  operation.cancelled = true;
  operation.controller.abort();
  state.activeOperation = null;
  state.steps.ai = 'idle';
  state.error = '';
  replaceToast(operation.toastId, 'success', 'Draft cancelled', 'No plan was saved.');
  render();
}

function assertAiDraftActive(operation: ActiveAiDraftOperation): void {
  if (operation.cancelled || operation.controller.signal.aborted) {
    throw new Error('AI draft cancelled.');
  }
}

function isAbortError(err: unknown): boolean {
  return err instanceof Error && err.name === 'AbortError';
}

async function runGenerateAiPlan(): Promise<void> {
  if (!canGenerateAiPlanFromSettings()) {
    pushToast('error', 'AI setup incomplete', aiGenerateDisabledReason());
    render();
    return;
  }
  if (activeAiDraftOperation && state.activeOperation === 'generate-ai-plan') {
    pushToast('pending', 'AI draft already working', 'Cancel the current draft or wait for it to finish.');
    render();
    return;
  }
  if (state.busy) {
    pushToast('pending', 'Action in progress', 'Finish the current wallet or approval action before starting another AI draft.');
    render();
    return;
  }
  const selectedTemplateForUi = selectedTemplate();
  trackGenerateAiPlan(selectedTemplateForUi.id, state.aiSettings.mode, state.aiSettings.provider);
  const toastId = pushToast('pending', 'Creating AI plan', 'Preparing through your configured AI Planner.');
  const operation = startAiDraftOperation(selectedTemplateForUi.title, state.agentPrompt.trim(), toastId);
  let reviewAfterDraftId = '';
  try {
    const selectedParameters = normalizeConnectorDraftParameters(
      selectedTemplateForUi,
      readTemplateFields(selectedTemplateForUi),
    );
    const userNotes = state.agentPrompt.trim();
    const connectorLocked = Boolean(selectedConnectorForDraftParameters(selectedParameters));
    const inferredTemplateId = connectorLocked
      ? selectedTemplateForUi.id
      : inferTemplateIdForPrompt(userNotes, selectedTemplateForUi.id);
    const template = templateById(inferredTemplateId);
    const inferredFromPrompt = template.id !== selectedTemplateForUi.id;
    const parameters = normalizeConnectorDraftParameters(
      template,
      inferredFromPrompt
        ? inferredTemplateParameters(template, userNotes, selectedParameters)
        : selectedParameters,
    );
    if (inferredFromPrompt) {
      state.templateFieldErrors = {};
      if (isConnectorCapableTemplate(template)) {
        assertValidTemplatePlanInput(template, parameters, userNotes, { mode: 'ai' });
      }
    } else {
      assertValidTemplatePlanInput(template, parameters, userNotes, { mode: 'ai' });
    }
    assertAiDraftActive(operation);
    operation.templateTitle = template.title;
    operation.prompt = userNotes || template.description;
    state.templateFields = parameters;
    operation.planRecordId = materializeAiDraftPlaceholder(template, parameters, userNotes);
    state.selectedGeneratedPlanId = operation.planRecordId;
    const effectiveUserNotes = injectHouseRules(connectorAiUserNotes(template, parameters, userNotes));
    state.oneTimePlanView = 'review';
    render();
    const request = {
      prompt: userNotes || template.description,
      userNotes: effectiveUserNotes,
      template: {
        id: template.id,
        category: template.category,
        title: template.title,
        description: template.description,
        actionType: template.actionType,
        risk: template.risk,
      },
      parameters,
      connectorContext: connectorAiPlannerContext(template, parameters, connectorDraftEnvironment()),
    };
    state.aiDiagnostics = [
      aiRouteDiagnostic(aiDraftRoutePath('generate-plan')),
    ];
    render();
    const generatedPlan = state.aiSettings.mode === 'bridge'
      ? await bridgeRequest<AgentPlan>('/bridge/ai/generate-plan', {
        method: 'POST',
        body: JSON.stringify(request),
        signal: operation.controller.signal,
      })
      : state.aiSettings.mode === 'hosted'
        ? await generateHostedAiPlan(state.aiSettings, request, hostedAiRequestOptions({ signal: operation.controller.signal }))
        : state.aiSettings.mode === 'device-agent'
          ? await generateDeviceAgentPlan(request, { signal: operation.controller.signal })
          : await generateSessionAiPlan(state.aiSettings, request, { signal: operation.controller.signal });
    assertAiDraftActive(operation);
    const plan = planWithRuntimeTokenLabels(generatedPlan);
    state.agentPlan = plan;
    state.agentSignature = '';
    state.agentPreparedActionId = '';
    const upgradeToCloud = activeWorkflowMode() === 'agentic-cloud' && plan.actionType !== 'recurring_payment';
    let finalRecordId: string;
    if (upgradeToCloud) {
      const cloudRecord = await saveGeneratedPlan(plan, template, request.prompt, { signal: operation.controller.signal });
      assertAiDraftActive(operation);
      removeGeneratedPlanLocally(operation.planRecordId);
      operation.planRecordId = cloudRecord.id;
      finalRecordId = cloudRecord.id;
    } else {
      updateGeneratedPlanLocalOnly(operation.planRecordId, {
        plan,
        status: 'draft',
        failureLabel: undefined,
        error: undefined,
      });
      finalRecordId = operation.planRecordId;
    }
    state.selectedGeneratedPlanId = finalRecordId;
    state.oneTimePlanView = 'review';
    const finalRecord = generatedPlanById(finalRecordId);
    if (state.askAgentAfterDraft && (hasDetectedAgentReviewPath() || Boolean(finalRecord && isMockPreSignPolicyPlan(finalRecord)))) {
      reviewAfterDraftId = finalRecordId;
    }
    appendAiDiagnostic({
      code: 'AI_PLAN_READY',
      message: 'AI Planner returned a valid plan.',
      detail: `${state.aiSettings.provider} ${state.aiSettings.model || 'model configured'}`,
    });
    state.steps.ai = 'done';
    replaceToast(toastId, 'success', 'AI plan created', `${plan.templateTitle} is ready in Check request.`);
  } catch (err) {
    const isCurrentOperation = activeAiDraftOperation?.id === operation.id;
    if (operation.cancelled || isAbortError(err)) {
      if (isCurrentOperation) {
        state.steps.ai = 'idle';
        state.error = '';
      }
      removeGeneratedPlanLocally(operation.planRecordId);
      if (!operation.cancelled) {
        replaceToast(toastId, 'success', 'Draft cancelled', 'No plan was saved.');
      }
    } else {
      const message = redactSecrets(err instanceof Error ? err.message : String(err));
      if (isCurrentOperation) {
        state.steps.ai = 'error';
        state.error = message;
      }
      if (operation.planRecordId) {
        updateGeneratedPlanLocalOnly(operation.planRecordId, {
          status: 'failed',
          error: message,
          failureLabel: AI_DRAFT_FAILED_LABEL,
        });
        state.selectedGeneratedPlanId = operation.planRecordId;
      }
      const toastMessage = applyAiErrorDiagnostics(err, message);
      replaceToast(toastId, 'error', aiErrorToastTitle(err), toastMessage);
    }
  } finally {
    const isCurrentOperation = activeAiDraftOperation?.id === operation.id;
    if (isCurrentOperation) {
      activeAiDraftOperation = null;
      if (state.activeOperation === 'generate-ai-plan') {
        state.activeOperation = null;
      }
    }
    render();
  }
  if (reviewAfterDraftId) {
    await runReviewGeneratedPlan(reviewAfterDraftId);
  }
}

async function runSignAgentPlan(): Promise<void> {
  await run('sign', async () => {
    if (!state.agentPlan) {
      throw new Error('Create a plan before signing a review proof.');
    }
    const plan = planWithRuntimeTokenLabels(state.agentPlan);
    state.agentPlan = plan;
    const activeRecord = generatedPlanById(state.selectedGeneratedPlanId);
    const proof = await signGeneratedPlanProof(activeRecord, plan);
    const signature = proof.signature;
    state.agentSignature = signature;
    await updateActiveGeneratedPlanRecord({
      signature,
      status: 'signed',
      error: undefined,
      failureLabel: undefined,
      ...(proof.metadata ? { metadata: proof.metadata } : {}),
    });
    if (activeRecord?.workflowSource === 'cloud') {
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    if (activeRecord && samePlan(planWithRuntimeTokenLabels(activeRecord.plan), plan)) {
      if (state.generatedPlanAuditId === activeRecord.id) {
        state.generatedPlanAuditId = '';
      }
      selectFallbackGeneratedPlan();
    }
    const syncPending = state.selectedGeneratedPlanId && cloudSyncPending(state.selectedGeneratedPlanId);
    if (syncPending) {
      pushToast('info', 'Signed locally', 'Cloud sync will retry when reachable.');
    } else {
      pushToast('success', 'Plan completed', 'Review proof saved in Done.');
    }
  }, {
    onError: async (message, err) => {
      // Defensive: if the local wallet signature already landed and the failure is
      // purely cloud-reachability, don't mark the record failed — the user did sign.
      // (Phase 4 in updateGeneratedPlan should already swallow this; this guard
      // protects against future cloud writes that bypass that path.)
      if (state.agentSignature && isCloudUnreachableError(err)) {
        pushToast('info', 'Signed locally', 'Cloud sync will retry when reachable.');
        return;
      }
      if (state.selectedGeneratedPlanId) {
        await updateGeneratedPlan(state.selectedGeneratedPlanId, {
          status: 'failed',
          error: message,
          failureLabel: 'Sign failed - try again',
        }).catch(() => undefined);
      }
      pushToast('error', 'Sign proof failed', message);
    },
  });
}

async function runQueueAgentPlan(): Promise<void> {
  await run('inbox', async () => {
    if (!state.agentPlan) {
      throw new Error('Create a plan before sending it for approval.');
    }
    const plan = planWithRuntimeTokenLabels(state.agentPlan);
    state.agentPlan = plan;
    const activeRecord = generatedPlanById(state.selectedGeneratedPlanId);
    const response = await queuePlanThroughActiveWorkflow(plan, activeRecord);
    state.agentPreparedActionId = response.id;
    if (response.mode === 'agentic-cloud' && response.planRecordId) {
      state.selectedGeneratedPlanId = response.planRecordId;
    } else if (activeRecord?.workflowSource === 'cloud') {
      markGeneratedPlanQueuedLocally(activeRecord.id, response.id, response.mode === 'local-bridge' ? 'local-bridge' : 'browser');
    } else {
      await updateActiveGeneratedPlanRecord({ preparedActionId: response.id, status: 'queued', error: undefined, failureLabel: undefined });
    }
    const queuedRecordId = response.planRecordId ?? activeRecord?.id ?? '';
    if (queuedRecordId && activeRecord && samePlan(planWithRuntimeTokenLabels(activeRecord.plan), plan)) {
      if (state.generatedPlanAuditId === queuedRecordId || state.generatedPlanAuditId === activeRecord.id) {
        state.generatedPlanAuditId = '';
      }
      selectFallbackGeneratedPlan();
    }
    if (plan.actionType === 'recurring_payment') {
      state.activeTab = 'schedule';
      state.recurringView = 'active';
    } else {
      state.activeTab = 'inbox';
      state.inboxFilter = 'ready';
    }
    if (response.mode === 'local-bridge') {
      await refreshInboxData();
    } else if (response.mode === 'agentic-cloud') {
      // Queue already succeeded cloud-side. A transient refresh failure must not
      // roll the success back — swallow CloudUnreachableError (and other refresh errors).
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    pushToast(
      'success',
      plan.actionType === 'recurring_payment' ? 'Repeat payment created' : 'Sent for approval',
      plan.actionType === 'recurring_payment'
        ? response.mode === 'browser-workflow'
          ? 'Created one local approval now. Saved-on-device workflow does not run background repeats after this tab closes.'
          : 'Future payments will appear in Needs Approval.'
        : response.mode === 'agentic-cloud'
          ? 'Saved to Agentic Cloud. No localhost required.'
          : response.mode === 'browser-workflow'
            ? 'Saved on this device.'
            : response.id,
    );
  }, {
    onError: async (message) => {
      if (state.selectedGeneratedPlanId) {
        await updateGeneratedPlan(state.selectedGeneratedPlanId, {
          status: 'failed',
          error: message,
          failureLabel: 'Send failed - try again',
        }).catch(() => undefined);
      }
      pushToast('error', 'Send for approval failed', message);
    },
  });
}

async function runGeneratedPlanAction(planId: string, action: string): Promise<void> {
  const record = generatedPlanById(planId);
  if (!record) return;

  if (action === 'view') {
    state.selectedGeneratedPlanId = planId;
    state.generatedPlanAuditId = planId;
    state.error = '';
    render();
    return;
  }
  if (action === 'reuse' || action === 'make-active') {
    useGeneratedPlanAsStartingPoint(record);
    pushToast('success', 'Starting point loaded', `${record.plan.templateTitle} is ready in Create Plan.`);
    render();
    return;
  }
  if (action === 'archive') {
    await updateGeneratedPlan(planId, { status: 'archived' });
    if (state.generatedPlanAuditId === planId) {
      state.generatedPlanAuditId = '';
    }
    selectFallbackGeneratedPlan();
    pushToast('success', 'Plan archived', record.plan.templateTitle);
    render();
    return;
  }
  if (action === 'restore') {
    await updateGeneratedPlan(planId, { status: restoredGeneratedPlanStatus(record) });
    state.selectedGeneratedPlanId = planId;
    pushToast('success', 'Plan restored', record.plan.templateTitle);
    render();
    return;
  }
  if (action === 'delete') {
    openGeneratedPlanDeleteModal(planId);
    return;
  }
  if (action === 'sign-proof') {
    await runSignGeneratedPlan(planId);
    return;
  }
  if (action === 'agent-review') {
    await runReviewGeneratedPlan(planId);
    return;
  }
  if (action === 'agent-answer') {
    await runReviewGeneratedPlanWithAnswers(planId);
    return;
  }
  if (action === 'agent-deny') {
    await runDenyGeneratedPlanWithAgentReason(planId);
    return;
  }
  if (action === 'queue') {
    await runQueueGeneratedPlan(planId);
  }
}

async function runDenyGeneratedPlanWithAgentReason(planId: string): Promise<void> {
  const record = generatedPlanById(planId);
  if (!record) return;
  const review = record.agentReview;
  if (!review || review.status !== 'denied') {
    pushToast('error', 'Cannot deny', 'Agent has not denied this draft yet.');
    return;
  }
  const confirmMessage = `Deny this draft using the agent's reason?\n\nAgent said: ${review.reason || 'No reason recorded.'}`;
  if (!window.confirm(confirmMessage)) return;
  const blockingPolicies = review.policies?.filter((policy) => policy.outcome === 'block') ?? [];
  const deniedAt = new Date().toISOString();
  const actionId = `browser-agent-denial-${record.id}-${Date.now().toString(36)}`;
  const planSummary = compactSentence(record.plan.intent || record.plan.templateTitle || 'Agent draft', 132);
  const policyLabels = blockingPolicies.map((policy) => policy.label).filter(Boolean);
  const policyClause = policyLabels.length ? ` Policies that flagged: ${policyLabels.join(', ')}.` : '';
  const summary = compactSentence(
    `Denied based on agent review. Agent reason: ${review.reason || 'No reason recorded.'}.${policyClause}`,
    240,
  );
  const note = compactSentence(
    `Agent path: ${agentReviewPathLabel(review.source)}. Agent denied at ${formatDateTime(review.checkedAt ?? deniedAt)}.`,
    240,
  );
  let proofSignature: string | undefined;
  let signedNote = note;
  if (state.address) {
    try {
      proofSignature = await signAgentDenialProof(record.plan, review, `Agent denial: ${planSummary}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      signedNote = compactSentence(`${note} (Could not sign proof: ${redactSecrets(message)}.)`, 360);
    }
  } else {
    signedNote = compactSentence(`${note} (Wallet not connected; proof saved unsigned.)`, 360);
  }
  const receipt: ActionReceipt = {
    actionId,
    status: 'rejected',
    summary,
    note: signedNote,
    walletAddress: state.address || record.walletAddress,
    cluster: record.cluster,
    createdAt: deniedAt,
    completedAt: deniedAt,
    evidenceKind: 'rejection_receipt',
    ...(proofSignature ? { proofSignature } : {}),
  };
  state.receipts = mergeActionReceipts([receipt], state.receipts);
  saveBrowserWorkflowState();
  await updateGeneratedPlan(planId, {
    status: 'archived',
    error: undefined,
    failureLabel: 'Denied by agent review',
  }).catch(() => undefined);
  pushToast(
    'success',
    'Agent denial saved',
    proofSignature
      ? `${planSummary} archived. Signed denial proof saved in Done.`
      : `${planSummary} archived. Proof saved in Done (unsigned — wallet was unavailable).`,
  );
  if (state.generatedPlanAuditId === planId) {
    state.generatedPlanAuditId = '';
  }
  selectFallbackGeneratedPlan();
  render();
}

async function runAskAgentAnything(planId: string, question: string): Promise<void> {
  const record = generatedPlanById(planId);
  if (!record) return;
  if (record.status === 'archived') {
    pushToast('error', 'Restore plan first', 'Archived drafts cannot be queried.');
    return;
  }
  if (!canRunAgentReview()) {
    pushToast('error', 'Agent not detected', agentReviewUnavailableReason());
    return;
  }
  const review = record.agentReview ?? {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: true,
    status: 'checking',
    reason: 'Ask-agent conversation only. No decision recorded.',
    source: state.aiSettings.mode,
  };
  const exchangeId = `ask_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
  const askedAt = new Date().toISOString();
  const pendingExchange: AgentAskExchange = {
    id: exchangeId,
    question: question.slice(0, 400),
    askedAt,
    pending: true,
    source: state.aiSettings.mode,
    provider: agentReviewProviderLabel(),
    model: agentReviewModelLabel(),
  };
  const initialConversation = [...(review.conversation ?? []), pendingExchange].slice(-6);
  await updateGeneratedPlan(planId, {
    agentReview: { ...review, conversation: initialConversation },
  });

  const deterministicFacts = await gatherAgentReviewFacts(record, { question: pendingExchange.question });
  const factsForContext = factSetForContext(deterministicFacts);
  const walletContext = walletContextForAgent(record);
  const request: AgentPlanAskRequest = {
    plan: record.plan,
    question: pendingExchange.question,
    walletAddress: walletContext.address,
    cluster: record.cluster,
    context: {
      activeWorkflow: activeWorkflowLabel(),
      connectedWallet: walletContext.address,
      wallet: walletContext,
      route: record.plan.route,
      amount: planAmountSummary(record.plan),
      risk: record.plan.risk,
      approval: record.plan.approval,
      protocolConnectors: protocolConnectorPlannerContext(state.connectedDapps, state.cluster, {
        dialectClientKeyConfigured: Boolean(state.protocolConnectorPrefs.dialectClientKey.trim()),
        includeDisabled: true,
      }),
      ...(factsForContext ? { facts: factsForContext } : {}),
      ...(planBehavesLikeSwap(record.plan)
        ? {
            executionPath: {
              kind: record.plan.actionType === 'recurring_payment' ? 'recurring_swap' : 'swap',
              aggregator: 'Jupiter',
              routeSelection: 'Jupiter selects the executable route when the quote/order is fetched.',
              userInputRequired: 'Do not ask the user which DEX/protocol to use unless their intent explicitly requires a specific venue.',
            },
          }
        : {}),
    },
  };

  try {
    let result: AgentPlanAskResult;
    if (state.aiSettings.mode === 'bridge') {
      result = await bridgeRequest<AgentPlanAskResult>('/bridge/ai/ask-about-plan', {
        method: 'POST',
        body: JSON.stringify(request),
      });
    } else if (state.aiSettings.mode === 'hosted') {
      result = await generateHostedAiAsk(state.aiSettings, request, hostedAiRequestOptions());
    } else if (state.aiSettings.mode === 'device-agent') {
      result = await generateDeviceAgentAsk(request);
    } else {
      result = await generateSessionAiAsk(state.aiSettings, request);
    }
    const updatedExchange: AgentAskExchange = {
      ...pendingExchange,
      pending: false,
      answer: result.answer,
      ...(result.citations?.length ? { citations: result.citations } : {}),
      answeredAt: result.checkedAt,
    };
    const refreshed = generatedPlanById(planId);
    const baseConversation = refreshed?.agentReview?.conversation ?? initialConversation;
    const conversation = baseConversation.map((entry) => entry.id === exchangeId ? updatedExchange : entry);
    await updateGeneratedPlan(planId, {
      agentReview: { ...(refreshed?.agentReview ?? review), conversation: conversation.slice(-6) },
    });
  } catch (err) {
    const message = redactSecrets(err instanceof Error ? err.message : String(err));
    const erroredExchange: AgentAskExchange = {
      ...pendingExchange,
      pending: false,
      error: message,
      answeredAt: new Date().toISOString(),
    };
    const refreshed = generatedPlanById(planId);
    const baseConversation = refreshed?.agentReview?.conversation ?? initialConversation;
    const conversation = baseConversation.map((entry) => entry.id === exchangeId ? erroredExchange : entry);
    await updateGeneratedPlan(planId, {
      agentReview: { ...(refreshed?.agentReview ?? review), conversation: conversation.slice(-6) },
    });
    pushToast('error', 'Ask agent failed', message);
  }
  render();
}

async function runReviewGeneratedPlan(planId: string): Promise<void> {
  const record = requireGeneratedPlanRecord(planId);
  if (record.status === 'archived') {
    pushToast('error', 'Restore plan first', 'Archived drafts cannot be reviewed by the agent.');
    render();
    return;
  }
  if (isMockPreSignPolicyPlan(record)) {
    if (!canRunAgentReview(record)) {
      pushToast('error', 'Agent review unavailable', agentReviewUnavailableReason(record));
      render();
      return;
    }
    await runMockPreSignPolicyReview(planId);
    return;
  }
  if (!canRunAgentReview(record)) {
    pushToast('error', 'Agent not detected', agentReviewUnavailableReason(record));
    render();
    return;
  }

  const previousReview = record.agentReview;
  const checkingReview: AgentPlanReviewState = {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: true,
    status: 'checking',
    reason: 'Agent is reviewing this draft before it can move forward.',
    provider: agentReviewProviderLabel(),
    model: agentReviewModelLabel(),
    source: state.aiSettings.mode,
    ...(previousReview?.history?.length ? { history: previousReview.history } : {}),
  };
  state.activeOperation = 'review-agent-plan';
  const toastId = pushToast('pending', 'Asking agent', 'Reviewing this draft before approval.');
  try {
    await updateGeneratedPlan(planId, { agentReview: checkingReview, error: undefined, failureLabel: undefined });
    if (state.agentPlan && samePlan(planWithRuntimeTokenLabels(state.agentPlan), planWithRuntimeTokenLabels(record.plan))) {
      state.selectedGeneratedPlanId = planId;
    }
    await run('ai', async () => {
      const refreshed = generatedPlanById(planId) ?? record;
      const reviewPlan = planWithRuntimeTokenLabels(refreshed.plan);
      const appliedPolicyIds = enabledUserAgentPolicies().map((policy) => policy.id);
      const deterministicFacts = await gatherAgentReviewFacts(refreshed, {
        instruction: agentReviewInstruction(refreshed, reviewPlan),
      });
      const orchestration = await runAgentReviewWithEvidence(refreshed, reviewPlan, deterministicFacts);
      const result = normalizeAgentReviewResultForFacts(orchestration.rawResult, reviewPlan, deterministicFacts, {
        instruction: agentReviewInstruction(refreshed, reviewPlan),
      });
      const review = agentReviewStateFromResult(result, previousReview, reviewPlan, appliedPolicyIds, orchestration);
      review.facts = mergeReviewFacts(deterministicFacts, result.evidence);
      await updateGeneratedPlan(planId, { agentReview: review, error: undefined, failureLabel: undefined });
      if (state.agentPlan && samePlan(planWithRuntimeTokenLabels(state.agentPlan), reviewPlan)) {
        state.selectedGeneratedPlanId = planId;
      }
      const toastKind: ToastKind = review.status === 'approved'
        ? 'success'
        : review.status === 'needs_input'
          ? 'pending'
          : 'error';
      const toastTitle = review.status === 'approved'
        ? 'Agent approved'
        : review.status === 'needs_input'
          ? 'Agent needs input'
          : 'Agent denied';
      replaceToast(toastId, toastKind, toastTitle, review.reason);
    }, {
      onError: async (message, err) => {
        const toastMessage = applyAiErrorDiagnostics(err, message);
        const failedReview: AgentPlanReviewState = {
          ...checkingReview,
          status: 'error',
          reason: toastMessage,
          checkedAt: new Date().toISOString(),
        };
        await updateGeneratedPlan(planId, { agentReview: failedReview });
        replaceToast(toastId, 'error', 'Agent review failed', toastMessage);
      },
    });
  } catch (err) {
    const message = redactSecrets(err instanceof Error ? err.message : String(err));
    replaceToast(toastId, 'error', 'Agent review failed', message);
  } finally {
    state.activeOperation = null;
    render();
  }
}

function isMockPreSignDemoCreateFlow(template = selectedTemplate()): boolean {
  if (template.id !== 'swap') return false;
  const fields = { ...defaultTemplateFieldValues(template), ...state.templateFields };
  return fields.inputToken?.trim().toUpperCase() === 'SOL' &&
    fields.outputToken?.trim().toUpperCase() === 'POPCAT';
}

function isMockPreSignPolicyPlan(record: GeneratedPlanRecord): boolean {
  const plan = record.plan;
  const inputToken = (plan.parameters.inputTokenLabel || plan.parameters.inputToken || '').trim().toUpperCase();
  const outputToken = (plan.parameters.outputTokenLabel || plan.parameters.outputToken || '').trim().toUpperCase();
  const amount = (plan.parameters.amount || '').trim();
  const notes = `${plan.userNotes || ''} ${record.prompt || ''}`.toLowerCase();
  return plan.actionType === 'swap' &&
    inputToken === 'SOL' &&
    outputToken === 'POPCAT' &&
    amount === '0.04' &&
    (notes.includes('agent pre-signing decision') || notes.includes('pre-signing policy')) &&
    notes.includes('$60');
}

async function runMockPreSignPolicyReview(planId: string): Promise<void> {
  const record = requireGeneratedPlanRecord(planId);
  const previousReview = record.agentReview;
  const checkedAt = new Date().toISOString();
  const checkingReview: AgentPlanReviewState = {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: true,
    status: 'checking',
    reason: 'Agent is checking market, token, and transaction gates.',
    provider: MOCK_PRE_SIGN_POLICY_AGENT_PROVIDER,
    model: MOCK_PRE_SIGN_POLICY_AGENT_MODEL,
    source: 'mock',
    checkedAt,
    ...(previousReview?.history?.length ? { history: previousReview.history } : {}),
  };
  state.activeOperation = 'review-agent-plan';
  const toastId = pushToast('pending', 'Agent checking', 'Running the pre-signing decision locally.');
  try {
    await updateGeneratedPlan(planId, { agentReview: checkingReview, error: undefined, failureLabel: undefined });
    render();
    await sleep(350);
    const refreshed = generatedPlanById(planId) ?? record;
    const review = mockPreSignPolicyReviewState(refreshed, previousReview);
    await updateGeneratedPlan(planId, { agentReview: review, error: undefined, failureLabel: undefined });
    completeMockPreSignApproval(refreshed, review);
    replaceToast(toastId, 'success', 'Agent approved', 'Demo signature and approval receipt saved.');
  } catch (err) {
    const message = redactSecrets(err instanceof Error ? err.message : String(err));
    const failedReview: AgentPlanReviewState = {
      ...checkingReview,
      status: 'error',
      reason: message,
      checkedAt: new Date().toISOString(),
    };
    await updateGeneratedPlan(planId, { agentReview: failedReview }).catch(() => undefined);
    replaceToast(toastId, 'error', 'Agent review failed', message);
  } finally {
    state.activeOperation = null;
    render();
  }
}

function mockPreSignPolicyReviewState(
  record: GeneratedPlanRecord,
  previousReview: AgentPlanReviewState | undefined,
): AgentPlanReviewState {
  const checkedAt = new Date().toISOString();
  const reason = 'APPROVE: SOL price $90.96 is above the $60 gate, BTC Fear & Greed is 42 above the 20 gate, POPCAT mint/freeze authorities are disabled, token age is above 24h, and the transaction contains only the requested swap with no extra transfers, unknown recipients, or unrelated instructions.';
  const history = appendReviewAttempt(previousReview?.history, {
    attemptId: `attempt_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
    startedAt: checkedAt,
    finishedAt: checkedAt,
    decision: 'approve',
    reason,
  });
  return {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: true,
    status: 'approved',
    decision: 'approve',
    reason,
    summary: 'APPROVE - all requested decision gates passed.',
    checkedAt,
    provider: MOCK_PRE_SIGN_POLICY_AGENT_PROVIDER,
    model: MOCK_PRE_SIGN_POLICY_AGENT_MODEL,
    source: 'mock',
    checks: mockPreSignPolicyChecks(),
    evidence: {
      sources: [
        { title: 'BirdEye - Solana token prices', url: 'https://birdeye.so/' },
        { title: 'Jupiter - Solana swap aggregator', url: 'https://jup.ag/' },
        { title: 'alternative.me - Crypto Fear & Greed Index', url: 'https://alternative.me/crypto/fear-and-greed-index/' },
        { title: 'CoinGecko - Global market dominance & volume', url: 'https://www.coingecko.com/en/global-charts' },
      ],
    },
    ...(history.length ? { history } : {}),
    reviewedPlanFingerprint: planFingerprint(planWithRuntimeTokenLabels(record.plan)),
  };
}

function mockPreSignPolicyChecks(): AgentReviewCheck[] {
  const row = (label: string, value: string, tone: AgentEvidenceTone = 'good'): AgentReviewCheck => ({
    label,
    value,
    tone,
    source: 'deterministic',
  });
  return [
    row('BTC Fear & Greed', '42 is above the required 20 gate - alternative.me'),
    row('SOL price', '$90.96 is above the required $60 gate - BirdEye'),
    row('Mint authority', 'POPCAT mint authority disabled (null) - BirdEye'),
    row('Freeze authority', 'POPCAT freeze authority disabled (null) - BirdEye'),
    row('Token age', 'POPCAT token age 29.4 months, above 24h - BirdEye'),
    row('Requested swap only', 'Transaction scope contains only SOL -> POPCAT'),
    row('Extra transfers', 'No extra transfers detected'),
    row('Unknown recipients', 'No unknown recipients detected'),
    row('Unrelated instructions', 'No unrelated instructions detected'),
    row('Slippage protection', '0.50% (50 bps)'),
    row('Swap amount', '0.04 SOL (~$3.6383)'),
    row('Agent result', 'APPROVE'),
  ];
}

function completeMockPreSignApproval(record: GeneratedPlanRecord, review: AgentPlanReviewState): void {
  const completedAt = new Date().toISOString();
  const plan = planWithRuntimeTokenLabels(record.plan);
  const actionId = `browser-mock-pre-sign-${record.id}`;
  const kind: PreparedActionKind = 'swap';
  const action: PreparedAction = {
    id: actionId,
    kind,
    status: 'ready',
    walletAddress: state.address || record.walletAddress || '',
    cluster: record.cluster,
    summary: `Approved swap: ${plan.parameters.amount || '0.04'} ${plan.parameters.inputToken || 'SOL'} to ${plan.parameters.outputTokenLabel || plan.parameters.outputToken || 'POPCAT'}`,
    params: browserActionParams(plan, kind),
    dueAt: completedAt,
    createdAt: record.createdAt,
    updatedAt: completedAt,
    note: plan.userNotes || record.prompt || '',
    planDraftId: record.id,
    agentReview: review,
    metadata: {
      mockPreSignDemo: true,
      mockPreSignApprovedAt: completedAt,
    },
    workflowSource: 'browser',
  };
  completeBrowserPreparedAction(action, 'approved', `demo_sig_${record.id.replace(/[^a-z0-9_-]/gi, '').slice(0, 32)}`);
  void updateGeneratedPlan(record.id, {
    metadata: {
      ...(record.metadata ?? {}),
      mockPreSignDemo: true,
      mockPreSignActionId: actionId,
      mockPreSignApprovedAt: completedAt,
    },
  }).catch(() => undefined);
}

async function runReviewGeneratedPlanWithAnswers(planId: string): Promise<void> {
  const record = generatedPlanById(planId);
  if (!record) return;
  const review = record.agentReview;
  if (!review || review.status !== 'needs_input' || !review.questions?.length) {
    await runReviewGeneratedPlan(planId);
    return;
  }
  const answers: Record<string, string> = {};
  const form = document.querySelector<HTMLFormElement>(
    `form.agent-review-questions[data-generated-plan-id="${cssEscape(planId)}"]`,
  );
  if (form) {
    for (const input of form.querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-agent-review-answer-input]')) {
      const questionId = input.dataset.questionId;
      if (!questionId) continue;
      answers[questionId] = input.value.trim();
    }
  } else {
    for (const question of review.questions) {
      answers[question.id] = review.answers?.[question.id] ?? '';
    }
  }
  const missing = review.questions.filter((question) => question.required && !answers[question.id]?.trim());
  if (missing.length) {
    pushToast('error', 'Answer required', `Answer ${missing.length} question${missing.length === 1 ? '' : 's'} before sending.`);
    return;
  }
  await updateGeneratedPlan(planId, {
    agentReview: { ...review, answers },
  });
  await runReviewGeneratedPlan(planId);
}

function cssEscape(value: string): string {
  if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
    return CSS.escape(value);
  }
  return value.replace(/[^a-zA-Z0-9_-]/g, (char) => `\\${char}`);
}

function cacheAgentReviewAnswerInputs(form: HTMLFormElement): void {
  const planId = form.dataset.generatedPlanId;
  if (!planId) return;
  const record = generatedPlanById(planId);
  const review = record?.agentReview;
  if (!review || review.status !== 'needs_input') return;
  const answers: Record<string, string> = { ...(review.answers ?? {}) };
  for (const input of form.querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-agent-review-answer-input]')) {
    const questionId = input.dataset.questionId;
    if (!questionId) continue;
    answers[questionId] = input.value;
  }
  void updateGeneratedPlan(planId, { agentReview: { ...review, answers } });
}

