async function deletePreparedActionWithoutReceipt(action: PreparedAction): Promise<void> {
  const source = action.workflowSource;
  if (source === 'cloud') {
    await cloudRequest(`/api/approvals/${encodeURIComponent(action.id)}/cancel`, {
      method: 'POST',
      body: JSON.stringify({ note: 'Deleted from Needs Approval inbox.' }),
    });
    await refreshCloudWorkspaceData();
    const receipt = state.cloudCompletedPlans.find((record) => record.actionId === action.id);
    if (receipt) {
      await cloudRequest(`/api/completed/${encodeURIComponent(receipt.id)}`, { method: 'DELETE' });
      state.cloudCompletedPlans = state.cloudCompletedPlans.filter((candidate) => candidate.id !== receipt.id);
    }
    return;
  }
  if (isBrowserWorkflowId(action.id)) {
    state.preparedActions = state.preparedActions.filter((candidate) => candidate.id !== action.id);
    state.materializedActions = state.preparedActions;
    state.receipts = state.receipts.filter((receipt) => receipt.actionId !== action.id);
    saveBrowserWorkflowState();
    return;
  }
  if (!state.bridgeActive) {
    throw new Error('Connect the local bridge before deleting bridge-backed requests.');
  }
  await bridgeRequest('/bridge/prepared-actions/delete', {
    method: 'POST',
    body: JSON.stringify({ actionId: action.id }),
  });
}

async function runDeleteAllInbox(): Promise<void> {
  state.deleteAllInboxModalOpen = false;
  const items = filteredPreparedActions().slice();
  if (items.length === 0) {
    render();
    return;
  }
  await run('inbox', async () => {
    let ok = 0;
    let failed = 0;
    let touchedBridge = false;
    for (const action of items) {
      try {
        if (action.workflowSource === 'local-bridge') {
          touchedBridge = true;
        }
        await deletePreparedActionWithoutReceipt(action);
        ok += 1;
      } catch {
        failed += 1;
      }
    }
    if (touchedBridge) {
      await refreshInboxData().catch(() => undefined);
    }
    pushToast(
      failed ? 'pending' : 'success',
      failed ? 'Needs Approval partially cleared' : 'Needs Approval cleared',
      `${ok} deleted${failed ? `, ${failed} failed` : ''}.`,
    );
  });
}

async function runDeleteAllCheck(): Promise<void> {
  state.deleteAllCheckModalOpen = false;
  const items = filterGeneratedPlansByAgentReview(visibleGeneratedPlans(true)).slice();
  if (items.length === 0) {
    render();
    return;
  }
  await run('inbox', async () => {
    let ok = 0;
    let failed = 0;
    const removedIds = new Set<string>();
    for (const record of items) {
      try {
        if (record.workflowSource === 'cloud') {
          await cloudRequest(`/api/plans/${encodeURIComponent(record.id)}`, { method: 'DELETE' });
        }
        removedIds.add(record.id);
        ok += 1;
      } catch {
        failed += 1;
      }
    }
    if (removedIds.size > 0) {
      state.generatedPlans = state.generatedPlans.filter((candidate) => !removedIds.has(candidate.id));
      if (removedIds.has(state.generatedPlanAuditId)) {
        state.generatedPlanAuditId = '';
      }
      if (removedIds.has(state.selectedGeneratedPlanId)) {
        selectFallbackGeneratedPlan();
      }
      saveGeneratedPlans();
    }
    pushToast(
      failed ? 'pending' : 'success',
      failed ? 'Check partially cleared' : 'Check cleared',
      `${ok} draft${ok === 1 ? '' : 's'} deleted${failed ? `, ${failed} failed` : ''}.`,
    );
  });
}

async function runDeleteAllRepeats(): Promise<void> {
  state.deleteAllRepeatsModalOpen = false;
  const items = filterRecurringPaymentsByAgentReview(activeWorkflowRecurringPayments()).slice();
  if (items.length === 0) {
    render();
    return;
  }
  await run('inbox', async () => {
    let ok = 0;
    let failed = 0;
    let touchedCloud = false;
    let touchedBridge = false;
    for (const payment of items) {
      try {
        const source = recurringPaymentWorkflowSource(payment);
        if (source === 'browser') {
          state.recurringPayments = state.recurringPayments.filter((candidate) => candidate.id !== payment.id);
          state.preparedActions = state.preparedActions.filter((candidate) => (
            candidate.recurringId !== payment.id || isTerminalPreparedAction(candidate)
          ));
          state.materializedActions = state.preparedActions;
          saveBrowserWorkflowState();
        } else if (source === 'cloud') {
          await cloudDeleteRecurring(payment.id);
          touchedCloud = true;
        } else {
          if (!state.bridgeActive) {
            throw new Error('Connect the local bridge before deleting bridge-backed repeats.');
          }
          await bridgeRequest('/bridge/recurring-payments/delete', {
            method: 'POST',
            body: JSON.stringify({ recurringId: payment.id }),
          });
          touchedBridge = true;
        }
        ok += 1;
      } catch {
        failed += 1;
      }
    }
    if (touchedCloud) {
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    if (touchedBridge) {
      await refreshInboxData().catch(() => undefined);
    }
    pushToast(
      failed ? 'pending' : 'success',
      failed ? 'Repeats partially cleared' : 'Active Repeats cleared',
      `${ok} repeat${ok === 1 ? '' : 's'} deleted${failed ? `, ${failed} failed` : ''}.`,
    );
  });
}

async function runDeleteAllDone(): Promise<void> {
  state.deleteAllDoneModalOpen = false;
  const items = filteredCompletedPlans(completedPlanRecords()).slice();
  if (items.length === 0) {
    render();
    return;
  }
  await run('inbox', async () => {
    let ok = 0;
    let failed = 0;
    let touchedCloud = false;
    let touchedBridge = false;
    const removedLocalIds = new Set<string>();
    const removedCloudIds = new Set<string>();
    const removedGeneratedPlanIds = new Set<string>();
    for (const record of items) {
      try {
        if (
          record.workflowSource === 'cloud' &&
          record.kind === 'recurring' &&
          record.recurringId &&
          record.id.startsWith('recurring:')
        ) {
          await cloudDeleteRecurring(record.recurringId);
          touchedCloud = true;
        } else if (record.workflowSource === 'cloud') {
          await cloudRequest(`/api/completed/${encodeURIComponent(record.id)}`, { method: 'DELETE' });
          touchedCloud = true;
          removedCloudIds.add(record.id);
        } else {
          if (record.actionId) {
            if (isBrowserWorkflowId(record.actionId)) {
              state.preparedActions = state.preparedActions.filter((candidate) => candidate.id !== record.actionId);
              state.materializedActions = state.preparedActions;
              state.receipts = state.receipts.filter((receipt) => receipt.actionId !== record.actionId);
            } else {
              if (!state.bridgeActive) {
                throw new Error('Connect the local bridge before deleting bridge-backed Done work.');
              }
              await bridgeRequest('/bridge/prepared-actions/delete', {
                method: 'POST',
                body: JSON.stringify({ actionId: record.actionId }),
              });
              touchedBridge = true;
            }
          }
          if (completedPlanIsEndedSchedule(record) && record.recurringId) {
            if (record.workflowSource === 'browser' || isBrowserWorkflowId(record.recurringId)) {
              state.recurringPayments = state.recurringPayments.filter((candidate) => candidate.id !== record.recurringId);
            } else {
              if (!state.bridgeActive) {
                throw new Error('Connect the local bridge before deleting repeat payment history.');
              }
              await bridgeRequest('/bridge/recurring-payments/delete', {
                method: 'POST',
                body: JSON.stringify({ recurringId: record.recurringId }),
              });
              touchedBridge = true;
            }
          }
          if (record.generatedPlanId) {
            removedGeneratedPlanIds.add(record.generatedPlanId);
          }
          removedLocalIds.add(record.id);
        }
        ok += 1;
      } catch {
        failed += 1;
      }
    }
    if (removedLocalIds.size > 0) {
      state.localCompletedPlans = state.localCompletedPlans.filter((candidate) => !removedLocalIds.has(candidate.id));
      saveLocalCompletedPlans();
      saveBrowserWorkflowState();
    }
    if (removedCloudIds.size > 0) {
      state.cloudCompletedPlans = state.cloudCompletedPlans.filter((candidate) => !removedCloudIds.has(candidate.id));
    }
    if (removedGeneratedPlanIds.size > 0) {
      state.generatedPlans = state.generatedPlans.filter((candidate) => !removedGeneratedPlanIds.has(candidate.id));
      if (removedGeneratedPlanIds.has(state.generatedPlanAuditId)) {
        state.generatedPlanAuditId = '';
      }
      if (removedGeneratedPlanIds.has(state.selectedGeneratedPlanId)) {
        selectFallbackGeneratedPlan();
      }
      saveGeneratedPlans();
    }
    if (touchedCloud) {
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    if (touchedBridge) {
      await refreshInboxData().catch(() => undefined);
    }
    pushToast(
      failed ? 'pending' : 'success',
      failed ? 'Done partially cleared' : 'Done cleared',
      `${ok} item${ok === 1 ? '' : 's'} deleted${failed ? `, ${failed} failed` : ''}.`,
    );
  });
}

async function runSignGeneratedPlan(planId: string): Promise<void> {
  let signedLocally = false;
  await run('sign', async () => {
    const record = requireGeneratedPlanRecord(planId);
    if (record.status === 'archived') {
      throw new Error('Restore this plan before signing a review proof.');
    }
    const plan = planWithRuntimeTokenLabels(record.plan);
    const proof = await signGeneratedPlanProof(record, plan);
    const signature = proof.signature;
    signedLocally = true;
    await updateGeneratedPlan(planId, {
      signature,
      status: 'signed',
      error: undefined,
      failureLabel: undefined,
      ...(proof.metadata ? { metadata: proof.metadata } : {}),
    });
    if (record.workflowSource === 'cloud') {
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    if (state.generatedPlanAuditId === planId) {
      state.generatedPlanAuditId = '';
    }
    selectFallbackGeneratedPlan();
    if (state.agentPlan && samePlan(planWithRuntimeTokenLabels(state.agentPlan), plan)) {
      state.agentSignature = signature;
    }
    if (cloudSyncPending(planId)) {
      pushToast('info', 'Signed locally', 'Cloud sync will retry when reachable.');
    } else {
      pushToast('success', 'Plan completed', 'Review proof saved in Done.');
    }
  }, {
    onError: async (message, err) => {
      if (signedLocally && isCloudUnreachableError(err)) {
        pushToast('info', 'Signed locally', 'Cloud sync will retry when reachable.');
        return;
      }
      await updateGeneratedPlan(planId, {
        status: 'failed',
        error: message,
        failureLabel: 'Sign failed - try again',
      });
      pushToast('error', 'Sign proof failed', message);
    },
  });
}

async function runQueueGeneratedPlan(planId: string): Promise<void> {
  await run('inbox', async () => {
    const record = requireGeneratedPlanRecord(planId);
    if (record.status === 'archived') {
      throw new Error('Restore this plan before sending it for approval.');
    }
    const plan = planWithRuntimeTokenLabels(record.plan);
    assertPlanCanQueue(plan);
    const response = await queuePlanThroughActiveWorkflow(plan, record);
    if (response.mode === 'agentic-cloud' && response.planRecordId) {
      state.selectedGeneratedPlanId = response.planRecordId;
    } else if (record.workflowSource === 'cloud') {
      markGeneratedPlanQueuedLocally(planId, response.id, response.mode === 'local-bridge' ? 'local-bridge' : 'browser');
    } else {
      await updateGeneratedPlan(planId, { preparedActionId: response.id, status: 'queued', error: undefined, failureLabel: undefined });
    }
    if (state.generatedPlanAuditId === planId || (response.planRecordId && state.generatedPlanAuditId === response.planRecordId)) {
      state.generatedPlanAuditId = '';
    }
    selectFallbackGeneratedPlan();
    if (state.agentPlan && samePlan(planWithRuntimeTokenLabels(state.agentPlan), plan)) {
      state.agentPreparedActionId = response.id;
    }
    if (plan.actionType === 'recurring_payment') {
      state.activeTab = 'schedule';
      state.recurringView = 'active';
    } else {
      state.activeTab = 'inbox';
      state.inboxFilter = 'ready';
    }
    if (response.mode === 'local-bridge') {
      await refreshInboxData();
    } else if (response.mode === 'agentic-cloud') {
      // Queue already succeeded cloud-side. A transient refresh failure must not
      // roll the success back — swallow CloudUnreachableError (and other refresh errors).
      await refreshCloudWorkspaceData().catch(() => undefined);
    }
    pushToast(
      'success',
      plan.actionType === 'recurring_payment' ? 'Repeat payment created' : 'Sent for approval',
      plan.actionType === 'recurring_payment'
        ? response.mode === 'browser-workflow'
          ? 'Created one local approval now. Saved-on-device workflow does not run background repeats after this tab closes.'
          : 'Future payments will appear in Needs Approval.'
        : response.mode === 'agentic-cloud'
          ? 'Saved to Agentic Cloud. No localhost required.'
          : response.mode === 'browser-workflow'
            ? 'Saved on this device.'
            : response.id,
    );
  }, {
    onError: async (message) => {
      await updateGeneratedPlan(planId, {
        status: 'failed',
        error: message,
        failureLabel: 'Send failed - try again',
      });
      pushToast('error', 'Send for approval failed', message);
    },
  });
}

async function saveGeneratedPlan(
  plan: AgentPlan,
  template: AgentPlanTemplate,
  prompt: string,
  options: { signal?: AbortSignal } = {},
): Promise<GeneratedPlanRecord> {
  plan = planWithRuntimeTokenLabels(plan);
  if (activeWorkflowMode() === 'agentic-cloud' && plan.actionType !== 'recurring_payment') {
    const cloudPlan = parseCloudPlanResponse(await cloudRequest('/api/plans', {
      method: 'POST',
      ...(options.signal ? { signal: options.signal } : {}),
      body: JSON.stringify({
        plan,
        source: plan.source,
        templateId: template.id,
        templateTitle: template.title,
        prompt,
        cluster: state.cluster,
        status: 'draft',
      }),
    }));
    if (options.signal?.aborted) {
      throw new Error('AI draft cancelled.');
    }
    const record = cloudPlanToGeneratedPlan(cloudPlan);
    if (!record) {
      throw new Error('Agentic Cloud did not return a valid plan draft.');
    }
    state.generatedPlans = mergeGeneratedPlans([record], state.generatedPlans.filter((candidate) => candidate.id !== record.id));
    return record;
  }
  if (options.signal?.aborted) {
    throw new Error('AI draft cancelled.');
  }
  const now = new Date().toISOString();
  const record: GeneratedPlanRecord = {
    id: newId('plan'),
    plan,
    createdAt: now,
    updatedAt: now,
    source: plan.source,
    templateId: template.id,
    templateTitle: template.title,
    prompt,
    walletAddress: state.address,
    cluster: state.cluster,
    status: 'draft',
    workflowSource: activeWorkflowMode() === 'local-bridge' ? 'local-bridge' : 'browser',
  };
  state.generatedPlans = mergeGeneratedPlans([record], state.generatedPlans);
  saveGeneratedPlans();
  return record;
}

function enqueuePendingCloudSync(entry: Omit<PendingCloudSync, 'attemptedAt' | 'attempts'> & { attempts?: number }): void {
  const attemptedAt = new Date().toISOString();
  const next = state.pendingCloudSyncs.filter((existing) => !(existing.kind === entry.kind && existing.id === entry.id));
  next.push({
    id: entry.id,
    kind: entry.kind,
    patch: entry.patch,
    attemptedAt,
    attempts: entry.attempts ?? 1,
  });
  state.pendingCloudSyncs = next;
}

function cloudSyncPending(planId: string): boolean {
  return state.pendingCloudSyncs.some((entry) => entry.kind === 'plan-patch' && entry.id === planId);
}

async function drainPendingCloudSyncs(): Promise<void> {
  if (!state.pendingCloudSyncs.length) return;
  const queue = [...state.pendingCloudSyncs];
  state.pendingCloudSyncs = [];
  for (const entry of queue) {
    if (entry.kind !== 'plan-patch') continue;
    try {
      await updateGeneratedPlan(entry.id, entry.patch);
    } catch (err) {
      if (isCloudUnreachableError(err)) {
        // Re-enqueue and stop draining — cloud is still down.
        state.pendingCloudSyncs.push({
          ...entry,
          attemptedAt: new Date().toISOString(),
          attempts: entry.attempts + 1,
        });
      }
      // Other errors: drop the entry (real cloud-side rejection). The local record keeps
      // its `cloudSyncStatus` flag; subsequent user action can repatch.
    }
  }
}

async function updateGeneratedPlan(
  planId: string,
  patch: Partial<Pick<GeneratedPlanRecord, 'status' | 'signature' | 'preparedActionId' | 'error' | 'failureLabel' | 'agentReview' | 'agentOverride' | 'metadata'>>,
): Promise<void> {
  const existing = generatedPlanById(planId);
  if (existing?.workflowSource === 'cloud' && patch.error === undefined && patch.failureLabel === undefined && patch.status !== 'failed') {
    const metadata = patch.metadata !== undefined || patch.agentReview !== undefined
      ? toJsonObject({
          ...(existing.metadata ?? {}),
          ...(patch.metadata ?? {}),
          ...(patch.agentReview !== undefined ? { agentReview: patch.agentReview } : {}),
        })
      : undefined;
    try {
      const cloudPlan = parseCloudPlanResponse(await cloudRequest(`/api/plans/${encodeURIComponent(planId)}`, {
        method: 'PATCH',
        body: JSON.stringify({
          ...(patch.status !== undefined && { status: patch.status }),
          ...(patch.signature !== undefined && { signature: patch.signature }),
          ...(patch.preparedActionId !== undefined && { approvalRequestId: patch.preparedActionId }),
          ...(metadata !== undefined && { metadata }),
        }),
      }));
      const record = cloudPlanToGeneratedPlan(cloudPlan);
      if (!record) {
        throw new Error('Agentic Cloud did not return a valid plan update.');
      }
      state.generatedPlans = mergeGeneratedPlans(
        [{ ...record, cloudSyncStatus: 'synced', cloudSyncError: undefined }],
        state.generatedPlans.filter((candidate) => candidate.id !== planId),
      );
      saveGeneratedPlans();
      return;
    } catch (err) {
      if (!isCloudUnreachableError(err)) throw err;
      // Cloud unreachable. Wallet/local action already succeeded; preserve local truth,
      // mark sync as pending, and queue a retry. Caller treats this as success.
      updateGeneratedPlanLocalOnly(planId, {
        ...patch,
        cloudSyncStatus: 'pending',
        cloudSyncError: err.message,
      });
      enqueuePendingCloudSync({ id: planId, kind: 'plan-patch', patch });
      return;
    }
  }
  const updatedAt = new Date().toISOString();
  state.generatedPlans = state.generatedPlans.map((record) => {
    if (record.id !== planId) return record;
    return {
      ...record,
      ...patch,
      updatedAt,
    };
  });
  saveGeneratedPlans();
}

function updateGeneratedPlanLocalOnly(planId: string, patch: Partial<GeneratedPlanRecord>): void {
  const updatedAt = new Date().toISOString();
  state.generatedPlans = state.generatedPlans.map((record) => {
    if (record.id !== planId) return record;
    return {
      ...record,
      ...patch,
      updatedAt,
    };
  });
  saveGeneratedPlans();
}

function markGeneratedPlanQueuedLocally(planId: string, preparedActionId: string, workflowSource: WorkflowRecordSource): void {
  updateGeneratedPlanLocalOnly(planId, {
    preparedActionId,
    status: 'queued',
    error: undefined,
    failureLabel: undefined,
    workflowSource,
  });
}

async function updateActiveGeneratedPlanRecord(
  patch: Partial<Pick<GeneratedPlanRecord, 'status' | 'signature' | 'preparedActionId' | 'error' | 'failureLabel' | 'agentReview' | 'agentOverride' | 'metadata'>>,
): Promise<void> {
  if (!state.agentPlan) return;
  const record = generatedPlanById(state.selectedGeneratedPlanId);
  if (record && samePlan(planWithRuntimeTokenLabels(record.plan), planWithRuntimeTokenLabels(state.agentPlan))) {
    await updateGeneratedPlan(record.id, patch);
  }
}

function makeGeneratedPlanActive(record: GeneratedPlanRecord): void {
  state.agentPlan = planWithRuntimeTokenLabels(record.plan);
  state.agentSignature = record.signature ?? '';
  state.agentPreparedActionId = record.preparedActionId ?? '';
  state.selectedGeneratedPlanId = record.id;
  state.generatedPlanAuditId = '';
  state.activeTab = 'agent';
  state.oneTimePlanView = 'review';
  state.error = '';
}

function useGeneratedPlanAsStartingPoint(record: GeneratedPlanRecord): void {
  const template = templateById(record.templateId);
  const plan = planWithRuntimeTokenLabels(record.plan);
  state.selectedTemplateId = template.id;
  state.templateOutcomeFilter = templateOutcome(template);
  state.templateFields = {
    ...defaultTemplateFieldValues(template),
    ...plan.parameters,
  };
  state.templateTokenModes = defaultTemplateTokenModes(template, state.templateFields);
  state.templateTokenSelections = defaultTemplateTokenSelections(template, state.templateFields);
  state.templateFieldErrors = {};
  state.agentPrompt = plan.userNotes || record.prompt || template.description;
  state.agentPlan = null;
  state.agentSignature = '';
  state.agentPreparedActionId = '';
  state.selectedGeneratedPlanId = record.id;
  state.generatedPlanAuditId = '';
  state.activeTab = 'agent';
  state.oneTimePlanView = 'create';
  state.error = '';
}

function openDcaReviewProofTemplate(): void {
  const template = templateById('dca');
  state.selectedTemplateId = template.id;
  state.templateOutcomeFilter = templateOutcome(template);
  state.templateFields = {
    ...defaultTemplateFieldValues(template),
    token: state.recurringDraft.token || defaultTemplateFieldValues(template).token || '',
    amount: state.recurringDraft.amount || defaultTemplateFieldValues(template).amount || '',
    recipient: state.recurringDraft.recipient || '',
    cadence: state.recurringDraft.cadence || defaultTemplateFieldValues(template).cadence || 'weekly',
    memo: state.recurringDraft.note || defaultTemplateFieldValues(template).memo || 'Repeat DCA approval',
  };
  state.templateTokenModes = defaultTemplateTokenModes(template, state.templateFields);
  state.templateTokenSelections = defaultTemplateTokenSelections(template, state.templateFields);
  state.templateFieldErrors = {};
  state.agentPrompt = 'Create a review proof for this recurring DCA strategy before any active schedule is created.';
  state.agentPlan = null;
  state.agentSignature = '';
  state.agentPreparedActionId = '';
  state.activeTab = 'agent';
  state.oneTimePlanView = 'create';
  state.error = '';
  pushToast(
    'success',
    'DCA review proof selected',
    'This creates evidence only. Active repeat payments use the selected workflow and each run still returns to Needs Approval.',
  );
  render();
}

function generatedPlansForPanel(oneTimeOnly = false): GeneratedPlanRecord[] {
  const walletScoped = state.generatedPlans.filter((record) => recordMatchesWalletScope(record, state.address));
  return oneTimeOnly ? walletScoped.filter(isOneTimeGeneratedPlan) : walletScoped;
}

function isOneTimeGeneratedPlan(record: GeneratedPlanRecord): boolean {
  return record.plan.actionType !== 'recurring_payment';
}

function visibleGeneratedPlans(oneTimeOnly = false): GeneratedPlanRecord[] {
  const records = generatedPlansForPanel(oneTimeOnly);
  return records.filter((record) => !record.template && isGeneratedPlanVisibleInReview(record));
}

function filterGeneratedPlansByAgentReview(records: GeneratedPlanRecord[]): GeneratedPlanRecord[] {
  return records.filter((record) => matchesAgentReviewFilter(record.agentReview, state.generatedPlanAgentReviewFilter));
}

function templateGeneratedPlans(oneTimeOnly = false): GeneratedPlanRecord[] {
  return generatedPlansForPanel(oneTimeOnly).filter((record) => record.template === true);
}

function isGeneratedPlanVisibleInReview(record: GeneratedPlanRecord): boolean {
  if (record.status === 'archived') return state.showArchivedGeneratedPlans;
  return isGeneratedPlanActiveInReview(record);
}

function isGeneratedPlanActiveInReview(record: GeneratedPlanRecord): boolean {
  return record.status !== 'archived' && !hasGeneratedPlanMovedPastReview(record);
}

function hasGeneratedPlanMovedPastReview(record: GeneratedPlanRecord): boolean {
  return Boolean(record.signature || record.preparedActionId || record.status === 'signed' || record.status === 'queued');
}

function completedPlanRecords(options: { includeLocalLedger?: boolean } = {}): CompletedPlanRecord[] {
  const mode = activeWorkflowMode();
  const includeBrowserHistory = mode === 'browser-workflow' || mode === 'agentic-cloud';
  const historyActions = includeBrowserHistory
    ? state.preparedActions.filter((action) => isBrowserWorkflowId(action.id))
    : state.preparedActions.filter((action) => action.workflowSource === 'local-bridge');
  const historyReceipts = includeBrowserHistory
    ? state.receipts.filter((receipt) => isBrowserWorkflowId(receipt.actionId))
    : state.receipts.filter((receipt) => !isBrowserWorkflowId(receipt.actionId));
  const historyPlans = includeBrowserHistory
    ? state.generatedPlans.filter((record) => record.workflowSource === 'browser' || !record.workflowSource)
    : state.generatedPlans.filter((record) => record.workflowSource === 'local-bridge');
  const walletHistoryActions = historyActions.filter((action) => recordMatchesWalletScope(action, state.address));
  const walletHistoryReceipts = historyReceipts.filter((receipt) => recordMatchesWalletScope(receipt, state.address));
  const walletHistoryPlans = historyPlans.filter((record) => recordMatchesWalletScope(record, state.address));
  const receiptsByActionId = new Map(walletHistoryReceipts.map((receipt) => [receipt.actionId, receipt]));
  const actionsById = new Map(walletHistoryActions.map((action) => [action.id, action]));
  const usedActionIds = new Set<string>();
  const records: CompletedPlanRecord[] = mode === 'agentic-cloud'
    ? state.cloudCompletedPlans.filter((record) => recordMatchesWalletScope(record, state.address))
    : [];

  for (const record of walletHistoryPlans.filter(isOneTimeGeneratedPlan)) {
    const action = record.preparedActionId ? actionsById.get(record.preparedActionId) : undefined;
    const receipt = record.preparedActionId ? receiptsByActionId.get(record.preparedActionId) : undefined;
    const hasTerminalAction = Boolean(action && isTerminalPreparedAction(action));
    const hasPendingWalletAction = Boolean(record.preparedActionId && !receipt && !hasTerminalAction);
    const isComplete = Boolean(receipt || hasTerminalAction || (record.signature && !hasPendingWalletAction));
    if (!isComplete) continue;
    records.push(completedPlanFromGeneratedPlan(record, receipt, action));
    if (record.preparedActionId) usedActionIds.add(record.preparedActionId);
  }

  for (const receipt of walletHistoryReceipts) {
    if (usedActionIds.has(receipt.actionId)) continue;
    records.push(completedPlanFromReceipt(receipt, actionsById.get(receipt.actionId)));
    usedActionIds.add(receipt.actionId);
  }

  for (const action of walletHistoryActions) {
    if (usedActionIds.has(action.id) || !isTerminalPreparedAction(action)) continue;
    records.push(completedPlanFromAction(action));
    usedActionIds.add(action.id);
  }

  const historyRecurring = activeWorkflowRecurringPayments();
  for (const payment of historyRecurring.filter(isRecurringPaymentCompleted)) {
    records.push(completedPlanFromEndedRecurring(payment));
  }

  const localLedger = options.includeLocalLedger === false
    ? []
    : state.localCompletedPlans
        .filter((record) => recordMatchesWalletScope(record, state.address))
        .filter((record) => {
          if (mode === 'local-bridge') return record.workflowSource === 'local-bridge';
          return record.workflowSource !== 'local-bridge';
        });

  return mergeCompletedPlanRecords(records, localLedger);
}

function showCompletedHistoryForAction(actionId?: string): void {
  const records = completedPlanRecords();
  const focused = actionId
    ? records.find((record) => record.actionId === actionId || record.id.includes(actionId))
    : records[0];
  state.activeTab = 'completed';
  state.completedPlanFilter = 'receipts';
  state.lastCompletedFocusId = focused?.id ?? actionId ?? records[0]?.id ?? '';
}

function filteredCompletedPlans(records = completedPlanRecords()): CompletedPlanRecord[] {
  switch (state.completedPlanFilter) {
    case 'one-time':
      return records.filter((record) => record.kind === 'one-time');
    case 'recurring':
      return records.filter((record) => record.kind === 'recurring');
    case 'proofs':
      return records.filter((record) => Boolean(record.signature));
    case 'receipts':
      return records.filter(completedPlanHasReceipt);
    case 'all':
      return records;
  }
}

function completedPlanHasReceipt(record: CompletedPlanRecord): boolean {
  return Boolean(record.actionId || record.txid || completedPlanConnectorRead(record));
}

function completedPlanConnectorRead(record: CompletedPlanRecord): JsonObject | undefined {
  return connectorReadFromMetadata(record.metadata);
}

function connectorReadFromMetadata(metadata: JsonObject | undefined): JsonObject | undefined {
  const value = metadata?.connectorRead;
  return isJsonObject(value) ? value : undefined;
}

function connectorReadDetailRows(connectorRead: JsonObject | undefined): Array<[string, string]> {
  if (!connectorRead) return [];
  const rows: Array<[string, string] | undefined> = [
    ['Question', pythQuestionDisplayLabel(stringFromJsonLike(connectorRead.question))],
    ['Result', stringFromJsonLike(connectorRead.resultSummary)],
    ['Feed', stringFromJsonLike(connectorRead.feedLabel) || stringFromJsonLike(connectorRead.symbol) || stringFromJsonLike(connectorRead.priceFeedId)],
    ['Read source', stringFromJsonLike(connectorRead.source)],
    ['Read checked', stringFromJsonLike(connectorRead.checkedAt)],
  ];
  return completedRows(rows);
}

function pythQuestionDisplayLabel(value: string): string {
  switch (value) {
    case 'oracle_evidence':
      return 'Oracle evidence';
    case 'freshness':
      return 'Freshness';
    case 'confidence':
      return 'Confidence';
    case 'price':
      return 'Price';
    default:
      return value ? titleCase(value.replace(/_/g, ' ')) : 'Price';
  }
}

function completedPlanFromGeneratedPlan(
  record: GeneratedPlanRecord,
  receipt: ActionReceipt | undefined,
  action: PreparedAction | undefined,
): CompletedPlanRecord {
  const connectorRead = connectorReadFromMetadata(record.metadata);
  const connectorReadSummary = stringFromJsonLike(connectorRead?.resultSummary);
  const note = completedPlanUserNote(record.plan.userNotes, receipt?.note, action?.note);
  const terminalStatus = receipt?.status ?? (action && isTerminalPreparedAction(action) ? action.status : undefined);
  const txStatus = receipt?.txStatus ?? action?.txStatus;
  const txid = receipt?.txid ?? action?.txid;
  const actionId = receipt?.actionId ?? action?.id ?? record.preparedActionId;
  const status = terminalStatus
    ? completedActionStatusLabel(terminalStatus, txStatus)
    : record.status === 'archived'
      ? 'archived'
      : 'proof signed';
  const completedAt = receipt?.completedAt ?? actionCompletedAt(action) ?? record.updatedAt;
  const amount = receipt?.amount ?? (action ? amountLabel(action) : planParameter(record.plan, ['amountSol', 'amount', 'inputAmount', 'plannedAmount']));
  const token = receipt?.token ?? (action ? tokenLabel(action) : completedPlanTokenFromPlan(record.plan));
  const recipient = receipt?.recipient ?? (action ? recipientParam(action) : planParameter(record.plan, ['recipient', 'recipientAddress']));
  const workflowSource = record.workflowSource ?? action?.workflowSource ?? (actionId && isBrowserWorkflowId(actionId) ? 'browser' : undefined);
  const payload = {
    type: 'completed_one_time_plan',
    status,
    plan: record.plan,
    signature: record.signature,
    metadata: record.metadata,
    actionId: receipt?.actionId ?? action?.id ?? record.preparedActionId,
    txid: receipt?.txid ?? action?.txid,
    completedAt,
  };
  return {
    id: `generated:${record.id}`,
    kind: 'one-time',
    status,
    tone: terminalStatus ? completedActionTone(terminalStatus, txStatus) : record.status === 'archived' ? 'neutral' : 'tx-confirmed',
    title: record.plan.intent,
    summary: connectorReadSummary || note,
    completedAt,
    createdAt: record.createdAt,
    walletAddress: receipt?.walletAddress ?? action?.walletAddress ?? record.walletAddress,
    cluster: receipt?.cluster ?? action?.cluster ?? record.cluster,
    ...(amount && { amount }),
    ...(token && { token }),
    ...(recipient && { recipient }),
    ...(record.signature && { signature: record.signature }),
    ...(txid ? { txid } : {}),
    ...(receipt?.explorerUrl && { explorerUrl: receipt.explorerUrl }),
    generatedPlanId: record.id,
    ...(actionId ? { actionId } : {}),
    ...(workflowSource ? { workflowSource } : {}),
    ...(record.metadata ? { metadata: record.metadata } : {}),
    copyPayload: stableJson(payload),
    detailRows: completedRows([
      ['Type', 'One-time plan'],
      ['Status', status],
      ['Template', record.templateTitle],
      ['Action', record.plan.actionType.replace(/_/g, ' ')],
      ...connectorReadDetailRows(connectorRead),
      ['Source', planSourceLabel(record.plan)],
      ['Wallet', (receipt?.walletAddress ?? action?.walletAddress ?? record.walletAddress) || 'No wallet at creation'],
      ['Created', formatDateTime(record.createdAt)],
      ['Completed', formatDateTime(completedAt)],
      actionId ? ['Approval id', actionId] : undefined,
      record.signature ? ['Review proof', record.signature] : undefined,
      txid ? ['Transaction', txid] : undefined,
      ['Approval rule', record.plan.approval],
      ['Route', record.plan.route],
    ]),
  };
}

function completedPlanTokenFromPlan(plan: AgentPlan): string {
  if (plan.actionType === 'swap') {
    return `${plan.parameters.inputToken || 'input'} to ${plan.parameters.outputToken || 'output'}`;
  }
  if (CONNECTOR_APPROVAL_ACTION_TYPES.has(plan.actionType)) {
    return connectorPlanTokenOrTargetSummary(plan)?.value ?? '';
  }
  return planParameter(plan, ['token', 'inputToken', 'outputToken']);
}

function completedPlanFromReceipt(receipt: ActionReceipt, action: PreparedAction | undefined): CompletedPlanRecord {
  if (receipt.evidenceKind === 'agent_override_receipt' && receipt.agentOverride) {
    return completedPlanFromAgentOverride(receipt);
  }
  const note = completedPlanUserNote(receipt.note, action?.note);
  const kind: CompletedPlanRecord['kind'] = receipt.recurringId || action?.recurringId ? 'recurring' : 'one-time';
  const status = completedActionStatusLabel(receipt.status, receipt.txStatus);
  const recurringId = receipt.recurringId ?? action?.recurringId;
  const occurrenceKey = receipt.occurrenceKey ?? action?.occurrenceKey;
  const workflowSource = action?.workflowSource ?? (isBrowserWorkflowId(receipt.actionId) ? 'browser' : undefined);
  const payload = {
    type: kind === 'recurring' ? 'completed_recurring_occurrence' : 'completed_one_time_approval',
    receipt,
    action,
  };
  return {
    id: `receipt:${receipt.actionId}`,
    kind,
    status,
    tone: completedActionTone(receipt.status, receipt.txStatus),
    title: receipt.summary,
    summary: note,
    completedAt: receipt.completedAt,
    createdAt: receipt.createdAt,
    walletAddress: receipt.walletAddress,
    cluster: receipt.cluster,
    ...(receipt.amount && { amount: receipt.amount }),
    ...(receipt.token && { token: receipt.token }),
    ...(receipt.recipient && { recipient: receipt.recipient }),
    ...(receipt.txid && { txid: receipt.txid }),
    ...(receipt.explorerUrl && { explorerUrl: receipt.explorerUrl }),
    ...(receipt.proofSignature && { signature: receipt.proofSignature }),
    actionId: receipt.actionId,
    ...(action?.kind ? { actionKind: action.kind } : {}),
    ...(recurringId ? { recurringId } : {}),
    ...(occurrenceKey ? { occurrenceKey } : {}),
    ...(workflowSource ? { workflowSource } : {}),
    copyPayload: stableJson(payload),
    detailRows: completedRows([
      ['Type', kind === 'recurring' ? 'Repeat payment' : 'One-time approval'],
      ['Status', status],
      ['Action id', receipt.actionId],
      recurringId ? ['Repeat id', recurringId] : undefined,
      occurrenceKey ? ['Occurrence', occurrenceKey] : undefined,
      ['Wallet', receipt.walletAddress],
      receipt.recipient ? ['Recipient', receipt.recipient] : undefined,
      receipt.amount ? ['Amount', `${receipt.amount} ${receipt.token ?? ''}`.trim()] : undefined,
      ['Created', formatDateTime(receipt.createdAt)],
      ['Completed', formatDateTime(receipt.completedAt)],
      receipt.proofSignature ? ['Decision proof', receipt.proofSignature] : undefined,
      receipt.txid ? ['Transaction', receipt.txid] : undefined,
      receipt.error ? ['Error', receipt.error] : undefined,
    ]),
  };
}

function completedPlanFromAgentOverride(receipt: ActionReceipt): CompletedPlanRecord {
  const override = receipt.agentOverride!;
  const review = override.reviewSnapshot;
  const status = 'agent override';
  const payload = {
    type: 'agent_override_receipt',
    receipt,
    override,
  };
  return {
    id: `override:${receipt.actionId}`,
    kind: 'one-time',
    status,
    tone: 'warn',
    title: 'Overrode agent warning',
    summary: receipt.summary,
    completedAt: receipt.completedAt,
    createdAt: receipt.createdAt,
    walletAddress: receipt.walletAddress,
    cluster: receipt.cluster,
    actionId: receipt.actionId,
    workflowSource: 'browser',
    copyPayload: stableJson(payload),
    detailRows: completedRows([
      ['Type', 'Agent override proof'],
      ['Status', status],
      ['Plan', override.planSummary],
      ['Agent path', agentReviewPathLabel(review.source)],
      ['Agent said', review.reason || 'No reason recorded.'],
      review.summary ? ['Agent summary', review.summary] : undefined,
      review.provider ? ['Agent provider', review.provider] : undefined,
      review.model ? ['Agent model', review.model] : undefined,
      ['Agent decided', review.checkedAt ? formatDateTime(review.checkedAt) : 'not recorded'],
      ['User overrode', formatDateTime(override.overriddenAt)],
      override.userReason ? ['User reason', override.userReason] : ['User reason', 'No reason given'],
      ['Wallet', receipt.walletAddress || 'No wallet at override'],
    ]),
  };
}

function completedPlanFromAction(action: PreparedAction): CompletedPlanRecord {
  const kind: CompletedPlanRecord['kind'] = action.recurringId ? 'recurring' : 'one-time';
  const status = action.archived ? 'cancelled' : completedActionStatusLabel(action.status, action.txStatus);
  const completedAt = actionCompletedAt(action) ?? action.updatedAt;
  const recipient = recipientParam(action);
  const amount = amountLabel(action);
  const token = tokenLabel(action);
  return {
    id: `action:${action.id}`,
    kind,
    status,
    tone: action.archived ? 'neutral' : completedActionTone(action.status, action.txStatus),
    title: action.summary,
    summary: completedPlanUserNote(action.note),
    completedAt,
    createdAt: action.createdAt,
    walletAddress: action.walletAddress,
    cluster: action.cluster,
    ...(amount !== 'n/a' && { amount }),
    ...(token !== 'n/a' && { token }),
    ...(recipient && { recipient }),
    ...(action.txid && { txid: action.txid }),
    actionId: action.id,
    ...(action.kind ? { actionKind: action.kind } : {}),
    ...(action.recurringId && { recurringId: action.recurringId }),
    ...(action.occurrenceKey && { occurrenceKey: action.occurrenceKey }),
    ...(action.workflowSource ? { workflowSource: action.workflowSource } : {}),
    copyPayload: stableJson({ type: kind === 'recurring' ? 'completed_recurring_occurrence' : 'completed_one_time_approval', action }),
    detailRows: completedRows([
      ['Type', kind === 'recurring' ? 'Repeat payment' : 'One-time approval'],
      ['Status', status],
      ['Action id', action.id],
      action.recurringId ? ['Repeat id', action.recurringId] : undefined,
      action.occurrenceKey ? ['Occurrence', action.occurrenceKey] : undefined,
      ['Wallet', action.walletAddress],
      recipient ? ['Recipient', recipient] : undefined,
      amount !== 'n/a' ? ['Amount', `${amount} ${token !== 'n/a' ? token : ''}`.trim()] : undefined,
      ['Created', formatDateTime(action.createdAt)],
      ['Completed', formatDateTime(completedAt)],
      action.txid ? ['Transaction', action.txid] : undefined,
      action.error ? ['Error', action.error] : undefined,
    ]),
  };
}

function completedPlanFromEndedRecurring(payment: RecurringPayment): CompletedPlanRecord {
  const occurrenceCount = payment.occurrencesCreated ?? 0;
  const max = payment.maxOccurrences ?? occurrenceCount;
  const title = `${payment.amount} ${payment.token} repeat payment completed`;
  return {
    id: `recurring-schedule:${payment.id}`,
    kind: 'recurring',
    status: 'schedule complete',
    tone: 'tx-confirmed',
    title,
    summary: `Reached ${occurrenceCount} of ${max} scheduled occurrence${max === 1 ? '' : 's'}.`,
    completedAt: payment.updatedAt,
    createdAt: payment.createdAt,
    walletAddress: payment.walletAddress,
    cluster: payment.cluster,
    amount: payment.amount,
    token: payment.token,
    recipient: payment.recipient,
    recurringId: payment.id,
    workflowSource: recurringPaymentWorkflowSource(payment),
    copyPayload: stableJson({ type: 'completed_recurring_schedule', recurringPayment: payment }),
    detailRows: completedRows([
      ['Type', 'Repeat payment'],
      ['Status', 'schedule complete'],
      ['Repeat id', payment.id],
      ['Wallet', payment.walletAddress],
      ['Recipient', payment.recipient],
      ['Amount', `${payment.amount} ${payment.token}`],
      ['Cadence', payment.cadence],
      ['Schedule', scheduleLabel(payment)],
      ['Occurrences', `${occurrenceCount} of ${max}`],
      ['Created', formatDateTime(payment.createdAt)],
      ['Completed', formatDateTime(payment.updatedAt)],
      payment.note ? ['Note', payment.note] : undefined,
    ]),
  };
}

function completedRows(rows: Array<[string, string] | undefined>): Array<[string, string]> {
  return rows.filter((row): row is [string, string] => Boolean(row && row[1]));
}

function isTerminalPreparedAction(action: PreparedAction): boolean {
  return Boolean(action.archived) || isTerminalPreparedActionStatus(action.status);
}

function isTerminalPreparedActionStatus(status: PreparedActionStatus): boolean {
  return (
    status === 'approved' ||
    status === 'rejected' ||
    status === 'cancelled' ||
    status === 'blocked' ||
    status === 'failed' ||
    status === 'expired'
  );
}

function actionCompletedAt(action: PreparedAction | undefined): string | undefined {
  if (!action || !isTerminalPreparedAction(action)) return undefined;
  if (action.archived) return action.updatedAt;
  return action.confirmedAt ?? action.updatedAt;
}

function completedActionStatusLabel(status: PreparedActionStatus, txStatus?: PreparedActionTxStatus): string {
  if (txStatus === 'confirmed') return 'approved';
  if (txStatus === 'failed') return 'failed';
  return status;
}

function completedActionTone(status: PreparedActionStatus, txStatus?: PreparedActionTxStatus): string {
  if (
    txStatus === 'failed' ||
    status === 'failed' ||
    status === 'blocked' ||
    status === 'rejected' ||
    status === 'cancelled' ||
    status === 'expired'
  ) return 'tx-failed';
  if (status === 'approved' || txStatus === 'confirmed') return 'tx-confirmed';
  return 'neutral';
}

function isRecurringPaymentCompleted(payment: RecurringPayment): boolean {
  return payment.maxOccurrences !== undefined && (payment.occurrencesCreated ?? 0) >= payment.maxOccurrences;
}

function completedPlanIsEndedSchedule(plan: CompletedPlanRecord): boolean {
  return plan.id.startsWith('recurring-schedule:');
}

function planParameter(plan: AgentPlan, keys: string[]): string {
  for (const key of keys) {
    const value = plan.parameters[key];
    if (value?.trim()) return value;
  }
  return '';
}

function selectedGeneratedPlan(): GeneratedPlanRecord | undefined {
  const selected = generatedPlanById(state.selectedGeneratedPlanId);
  if (!selected) return undefined;
  if (!state.showArchivedGeneratedPlans && selected.status === 'archived') return undefined;
  return selected;
}

function generatedPlanById(planId: string): GeneratedPlanRecord | undefined {
  return state.generatedPlans.find((record) => record.id === planId);
}

function requireGeneratedPlanRecord(planId: string): GeneratedPlanRecord {
  const record = generatedPlanById(planId);
  if (!record) {
    throw new Error('Plan was not found.');
  }
  return record;
}

function selectFallbackGeneratedPlan(): void {
  const filtered = filterGeneratedPlansByAgentReview(visibleGeneratedPlans());
  const next = filtered[0] ?? visibleGeneratedPlans()[0] ?? state.generatedPlans[0];
  state.selectedGeneratedPlanId = next?.id ?? '';
  if (state.generatedPlanAuditId && !generatedPlanById(state.generatedPlanAuditId)) {
    state.generatedPlanAuditId = '';
  }
}

function closeGeneratedPlanAuditModal(): void {
  state.generatedPlanAuditId = '';
  render();
}

function restoredGeneratedPlanStatus(record: GeneratedPlanRecord): GeneratedPlanStatus {
  if (record.preparedActionId) return 'queued';
  if (record.signature) return 'signed';
  return 'draft';
}

function generatedPlanStatusLabel(record: GeneratedPlanRecord): string {
  if (record.status === 'archived') return 'archived';
  if (record.preparedActionId || record.status === 'queued') return 'queued';
  if (record.signature || record.status === 'signed') return 'proof signed';
  return 'drafted';
}

function generatedPlanStatusTone(record: GeneratedPlanRecord): string {
  if (record.status === 'archived') return 'neutral';
  if (record.status === 'failed') return 'needs-review';
  if (record.preparedActionId || record.status === 'queued') return 'tx-pending';
  if (record.signature || record.status === 'signed') return 'tx-confirmed';
  return 'neutral';
}

function signedGeneratedPlanCount(): number {
  return state.generatedPlans.filter((record) => Boolean(record.signature)).length;
}

function generatedPlanMeta(record: GeneratedPlanRecord): string {
  const wallet = record.walletAddress ? short(record.walletAddress) : 'No wallet at creation';
  return `${formatDateTime(record.createdAt)} · ${titleCaseCluster(record.cluster)} · ${wallet}`;
}

function signProofTitle(record: GeneratedPlanRecord): string {
  if (record.status === 'archived') return 'Restore this plan before signing review evidence.';
  if (!state.address) return 'Connect a wallet before signing a review proof.';
  return record.signature
    ? 'Sign a fresh review proof. This does not queue, approve, or submit a transaction.'
    : 'Sign that you reviewed this plan. This creates audit evidence only.';
}

function generatedQueuePlanTitle(record: GeneratedPlanRecord): string {
  if (record.status === 'archived') return 'Restore this plan before sending it for approval.';
  if (!state.address) return 'Connect a wallet before sending for approval.';
  if (!canQueueAgentPlan(record.plan)) return 'Only transfers, swaps, Blink actions, custom transactions, and repeat payments can be queued.';
  const report = planGuardrailReport(record.plan);
  if (report?.verdict === 'block') return report.summary;
  const connectorError = protocolConnectorQueueBlockReason(record.plan);
  if (connectorError) return connectorError;
  const mode = activeWorkflowMode();
  if (record.plan.actionType === 'recurring_payment') {
    if (mode === 'agentic-cloud') return 'Create an Agentic Cloud repeat payment. Each due payment appears in Needs Approval.';
    return mode === 'local-bridge'
      ? 'Create a local repeat payment. Each due payment appears in Needs Approval.'
      : 'Create one browser-local repeat approval now. Background repeats need Agentic Cloud or Private local mode.';
  }
  if (record.plan.actionType === 'blink_action') {
    return 'Resolve the Blink/Solana Action into a browser-local transaction draft before wallet approval.';
  }
  if (mode === 'agentic-cloud') return 'Send this plan to Agentic Cloud Needs Approval for wallet review.';
  return mode === 'local-bridge'
    ? 'Send this plan to local Needs Approval for wallet review.'
    : 'Send this plan to browser Needs Approval. It stays local to this device.';
}

function samePlan(left: AgentPlan, right: AgentPlan): boolean {
  return stableJson(left) === stableJson(right);
}

interface SignedPlanProofDetails {
  signature: string;
  message: string;
  messageHash: string;
  metadata?: JsonObject;
  proofEncoding?: 'utf8-message' | 'tx-memo-proof';
  proofTxBase64?: string;
}

async function signGeneratedPlanProof(
  record: GeneratedPlanRecord | undefined,
  plan: AgentPlan,
): Promise<SignedPlanProofDetails> {
  const connectorRead = await connectorReadReceiptForPlan(record, plan);
  const signed = await signAgentPlanProofDetails(
    plan,
    connectorRead ? 'Pyth oracle read proof' : 'Plan review proof',
    connectorRead ? { connectorRead } : undefined,
  );
  return {
    ...signed,
    metadata: toJsonObject({
      ...(record?.metadata ?? {}),
      ...(connectorRead ? { connectorRead } : {}),
      signedProof: {
        message: signed.message,
        messageHash: signed.messageHash,
        signature: signed.signature,
        signatureEncoding: 'base58',
        ...(signed.proofEncoding ? { proofEncoding: signed.proofEncoding } : {}),
        ...(signed.proofTxBase64 ? { proofTxBase64: signed.proofTxBase64 } : {}),
      },
    }),
  };
}

async function signAgentPlanProof(plan: AgentPlan, summary: string): Promise<string> {
  const result = await signAgentPlanProofDetails(plan, summary);
  return result.signature;
}

async function signAgentPlanProofDetails(
  plan: AgentPlan,
  summary: string,
  proofContext?: { connectorRead?: JsonObject },
): Promise<SignedPlanProofDetails> {
  const message = agentPlanApprovalMessage(plan, proofContext);
  const result = await signWalletProofMessage(message, summary, state.cluster);
  return {
    signature: result.signature,
    message,
    messageHash: await sha256(message),
    proofEncoding: result.proofEncoding,
    proofTxBase64: result.proofTxBase64,
  };
}

function agentPlanApprovalMessage(plan: AgentPlan, proofContext?: { connectorRead?: JsonObject }): string {
  const lines = [
    'Solana Agent Wallet Adapter plan review proof',
    `Address: ${state.address}`,
    `Cluster: ${state.cluster}`,
    `Source: ${plan.source}`,
    `Template: ${plan.templateTitle}`,
    `Action: ${plan.actionType}`,
    `Prepared by: ${planPreparedBy(plan)}`,
    `Intent: ${plan.intent}`,
    `Route: ${plan.route}`,
    `Risk: ${plan.risk}`,
    `Approval: ${plan.approval}`,
    `Parameters: ${stableJson(plan.parameters)}`,
    `User notes: ${plan.userNotes || 'None'}`,
    `Safeguards: ${plan.safeguards.join(' | ')}`,
    `Time: ${new Date().toISOString()}`,
  ];
  if (proofContext?.connectorRead) {
    const read = proofContext.connectorRead;
    lines.push(`Connector read result: ${stringFromJsonLike(read.resultSummary) || 'Recorded'}`);
    lines.push(`Connector read question: ${stringFromJsonLike(read.question) || 'unspecified'}`);
    lines.push(`Connector facts: ${stableJson(read)}`);
  }
  return lines.join('\n');
}

type PythReadQuestion = 'price' | 'freshness' | 'confidence' | 'oracle_evidence';

async function connectorReadReceiptForPlan(
  record: GeneratedPlanRecord | undefined,
  plan: AgentPlan,
): Promise<JsonObject | undefined> {
  if (!isPythReadOnlyPlan(plan)) return undefined;
  const question = normalizedPythReadQuestion(plan.parameters.question);
  const request = pythConnectorReadRequest(plan, question);
  const source = connectorReadSourceForPlan(record);
  // Degraded proof: neither cloud nor bridge available. Sign without oracle facts
  // rather than blocking the wallet signature.
  if (source === undefined) return undefined;
  let response: Record<string, unknown>;
  try {
    response = source === 'cloud'
      ? await cloudRequest<Record<string, unknown>>('/api/connector/read-facts', {
          method: 'POST',
          body: JSON.stringify({
            ...request,
            cluster: record?.cluster ?? state.cluster,
            walletAddress: state.address,
          }),
        })
      : await bridgeRequest<Record<string, unknown>>('/bridge/action/connector-read-facts', {
          method: 'POST',
          body: JSON.stringify(request),
        });
  } catch (err) {
    // Transport-level cloud failure → fall back to degraded proof rather than failing
    // the wallet sign. Real cloud-side errors (4xx/5xx) still surface.
    if (isCloudUnreachableError(err)) return undefined;
    throw err;
  }
  const facts = connectorFactsFromReadResponse(response);
  if (!facts.length) {
    throw new Error('Pyth did not return connector facts for this price feed.');
  }
  const selectedFact = pythFactForQuestion(facts, question) ?? facts[0];
  if (!selectedFact) {
    throw new Error('Pyth did not return a usable connector fact for this price feed.');
  }
  const resultSummary = connectorFactSummary(selectedFact) || 'Pyth facts recorded';
  const feedLabel = pythFeedLabelFromRead(plan, response, selectedFact);
  const checkedAt = stringFromJsonLike(selectedFact.checkedAt) || new Date().toISOString();
  return toJsonObject({
    connectorId: 'pyth',
    connectorName: 'Pyth',
    capability: request.capability,
    question,
    originalQuestion: plan.parameters.question || '',
    resultSummary,
    feedLabel,
    ...(typeof request.priceFeedId === 'string' ? { priceFeedId: request.priceFeedId } : {}),
    ...(typeof request.symbol === 'string' ? { symbol: request.symbol } : {}),
    source,
    checkedAt,
    facts,
    response,
  });
}

function isPythReadOnlyPlan(plan: AgentPlan): boolean {
  if (plan.actionType !== 'read_only') return false;
  const connector = selectedConnectorForDraftParameters(plan.parameters) ??
    findProtocolConnectorByInput(plan.parameters.protocol || plan.parameters.dapp || plan.route);
  return connector?.id === 'pyth';
}

function normalizedPythReadQuestion(value: string | undefined): PythReadQuestion {
  const normalized = (value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (normalized === 'freshness' || normalized === 'age' || normalized === 'staleness') return 'freshness';
  if (normalized === 'confidence' || normalized === 'conf') return 'confidence';
  if (normalized === 'oracle_evidence' || normalized === 'evidence' || normalized === 'proof' || normalized === 'risk' || normalized === 'rewards') {
    return 'oracle_evidence';
  }
  return 'price';
}

function pythConnectorReadRequest(plan: AgentPlan, question: PythReadQuestion): Record<string, unknown> {
  const rawFeed = planParameter(plan, ['priceFeedIds', 'priceFeedId', 'feedId', 'position', 'market']);
  const rawLabel = planParameter(plan, ['priceFeedIdsLabel', 'priceFeedIdLabel', 'feedLabel', 'symbol']);
  const feedId = looksLikePythFeedId(rawFeed) ? rawFeed : '';
  const symbol = feedId ? rawLabel : rawFeed || rawLabel;
  if (!feedId && !symbol) {
    throw new Error('Choose a Pyth price feed before signing this read proof.');
  }
  const maxAgeSeconds = numericPlanParam(plan, ['maxAgeSeconds']);
  const maxConfidenceBps = numericPlanParam(plan, ['maxConfidenceBps']);
  return stripUndefined({
    connectorId: 'pyth',
    capability: question === 'oracle_evidence' ? 'oracle' : 'markets',
    ...(feedId ? { priceFeedId: feedId } : { symbol }),
    ...(maxAgeSeconds !== undefined ? { maxAgeSeconds } : {}),
    ...(maxConfidenceBps !== undefined ? { maxConfidenceBps } : {}),
    consumerProtocol: 'Solana Agent Wallet Adapter Protocol position check',
    includeEma: true,
  }) as Record<string, unknown>;
}

function connectorReadSourceForPlan(record: GeneratedPlanRecord | undefined): 'cloud' | 'local-bridge' | undefined {
  if (record?.workflowSource === 'local-bridge' && state.bridgeActive && state.bridgeToken && isTrustedBridgeUrl(state.bridgeUrl)) {
    return 'local-bridge';
  }
  if (record?.workflowSource === 'cloud' || activeWorkflowMode() === 'agentic-cloud') {
    if (cloudSessionMatchesWallet()) return 'cloud';
  }
  if (state.bridgeActive && state.bridgeToken && isTrustedBridgeUrl(state.bridgeUrl)) {
    return 'local-bridge';
  }
  if (cloudSessionMatchesWallet()) return 'cloud';
  // Neither cloud nor bridge is available. Signal degraded proof — caller will sign
  // without oracle facts rather than block the wallet operation. Wallet ops must remain
  // independent of cloud reachability.
  return undefined;
}

function connectorFactsFromReadResponse(response: unknown): JsonObject[] {
  if (!isJsonObject(response) || !Array.isArray(response.facts)) return [];
  return response.facts
    .filter(isJsonObject)
    .map((fact) => toJsonObject(fact))
    .filter((fact) => stringFromJsonLike(fact.label) || stringFromJsonLike(fact.value));
}

function pythFactForQuestion(facts: JsonObject[], question: PythReadQuestion): JsonObject | undefined {
  if (question === 'freshness') return facts.find((fact) => /freshness|age/i.test(stringFromJsonLike(fact.label)));
  if (question === 'confidence') return facts.find((fact) => /confidence/i.test(stringFromJsonLike(fact.label)));
  if (question === 'price') return facts.find((fact) => !/freshness|confidence/i.test(stringFromJsonLike(fact.label)));
  return facts[0];
}

function connectorFactSummary(fact: JsonObject | undefined): string {
  if (!fact) return '';
  const label = stringFromJsonLike(fact.label);
  const value = stringFromJsonLike(fact.value);
  if (label && value) return `${label}: ${value}`;
  return value || label;
}

function pythFeedLabelFromRead(plan: AgentPlan, response: unknown, fact: JsonObject | undefined): string {
  const explicit = planParameter(plan, ['priceFeedIdsLabel', 'priceFeedIdLabel', 'feedLabel', 'symbol']);
  if (explicit) return explicit;
  const responseObject = isJsonObject(response) ? response : {};
  const snapshot = isJsonObject(responseObject.snapshot)
    ? responseObject.snapshot
    : isJsonObject(responseObject.evidence)
      ? responseObject.evidence
      : {};
  return stringFromJsonLike(snapshot.symbol) ||
    stringFromJsonLike(snapshot.displayName) ||
    stringFromJsonLike(fact?.label).replace(/^Pyth(?: oracle)?\s+/i, '') ||
    'Pyth feed';
}

function looksLikePythFeedId(value: string): boolean {
  return /^(0x)?[0-9a-f]{64}$/i.test(value.trim());
}

function numericPlanParam(plan: AgentPlan, keys: string[]): number | undefined {
  const raw = planParameter(plan, keys);
  if (!raw) return undefined;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : undefined;
}

async function signAgentDenialProof(plan: AgentPlan, review: AgentPlanReviewState, summary: string): Promise<string> {
  const result = await signWalletProofMessage(agentDenialProofMessage(plan, review), summary, state.cluster);
  return result.signature;
}

function agentDenialProofMessage(plan: AgentPlan, review: AgentPlanReviewState): string {
  const policyLabels = (review.policies ?? [])
    .filter((policy) => policy.outcome === 'block' || policy.outcome === 'warn')
    .map((policy) => policy.label)
    .filter(Boolean);
  return [
    'Solana Agent Wallet Adapter plan DENIAL proof',
    `Address: ${state.address}`,
    `Cluster: ${state.cluster}`,
    `Source: ${plan.source}`,
    `Template: ${plan.templateTitle}`,
    `Action: ${plan.actionType}`,
    `Intent: ${plan.intent}`,
    `Route: ${plan.route}`,
    `Risk: ${plan.risk}`,
    `Approval: ${plan.approval}`,
    `Parameters: ${stableJson(plan.parameters)}`,
    `User notes: ${plan.userNotes || 'None'}`,
    `Agent path: ${agentReviewPathLabel(review.source)}`,
    `Agent provider: ${review.provider || 'unspecified'}`,
    `Agent model: ${review.model || 'unspecified'}`,
    `Agent decided at: ${review.checkedAt ?? 'not recorded'}`,
    `Agent reason: ${review.reason || 'No reason recorded.'}`,
    `Policies that flagged: ${policyLabels.length ? policyLabels.join(' | ') : 'none'}`,
    `Time: ${new Date().toISOString()}`,
  ].join('\n');
}

async function runAgentReview(
  record: GeneratedPlanRecord,
  deterministicFacts = gatherDeterministicFacts(record),
  bundle?: AgentReviewEvidenceBundle,
): Promise<AgentPlanReviewResult> {
  const request = agentReviewRequest(record, deterministicFacts, bundle);
  state.aiDiagnostics = [
    aiRouteDiagnostic(aiDraftRoutePath('review-plan')),
  ];
  render();
  if (state.aiSettings.mode === 'bridge') {
    return bridgeRequest<AgentPlanReviewResult>('/bridge/ai/review-plan', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }
  if (state.aiSettings.mode === 'hosted') {
    return generateHostedAiReview(state.aiSettings, request, hostedAiRequestOptions());
  }
  if (state.aiSettings.mode === 'device-agent') {
    return generateDeviceAgentReview(request);
  }
  return generateSessionAiReview(state.aiSettings, request);
}

interface AgentReviewOrchestrationResult {
  rawResult: AgentPlanReviewResult;
  bundle: AgentReviewEvidenceBundle;
  decisionContract: AgentDecisionContract;
  validationViolations: string[];
  auditReceipt: AgentDecisionAuditReceipt;
}

async function runAgentReviewWithEvidence(
  record: GeneratedPlanRecord,
  plan: AgentPlan,
  deterministicFacts: AgentReviewFactSet,
): Promise<AgentReviewOrchestrationResult> {
  const bundle = buildAgentReviewEvidenceBundle(record, plan, deterministicFacts);
  const rawResult = await runAgentReview(record, deterministicFacts, bundle);
  const validated = validateAgentReviewDecision({
    aiResult: rawResult,
    gate: bundle.gate,
    facts: bundle.evidenceFacts,
    requirements: bundle.requirements,
    context: bundle.evidenceContext,
  });
  const auditReceipt = await createDecisionAuditReceipt({
    finalDecision: validated.final.decision,
    decisionContract: validated.decisionContract,
    gate: bundle.gate,
    facts: bundle.evidenceFacts,
    requirements: bundle.requirements,
    routes: bundle.routePlan,
    walletAddress: bundle.evidenceContext.walletAddress ?? 'not_connected',
    cluster: bundle.evidenceContext.cluster ?? 'unknown',
    planFingerprint: bundle.evidenceContext.planFingerprint ?? planFingerprint(plan),
    ...(bundle.evidenceContext.connectorId ? { connectorId: bundle.evidenceContext.connectorId } : {}),
    ...(bundle.evidenceContext.connectorProfile ? { connectorProfile: bundle.evidenceContext.connectorProfile } : {}),
  });
  // Attach the spot prices captured at review time and the plan's total USD-at-risk.
  // Both are best-effort annotations — token-native amounts on the plan remain canonical.
  const spotPrices = spotPricesForPlan(plan);
  const totalUsdAtRisk = planTotalUsdAtRisk(plan);
  if (Object.keys(spotPrices).length > 0) {
    auditReceipt.spotPrices = Object.fromEntries(
      Object.entries(spotPrices).map(([mint, snap]) => [mint, {
        usdPerToken: snap.usdPerToken,
        source: snap.source,
        checkedAt: snap.checkedAt,
        ...(typeof snap.confidence === 'number' ? { confidence: snap.confidence } : {}),
      }]),
    );
  }
  if (typeof totalUsdAtRisk === 'number') {
    auditReceipt.totalUsdAtRisk = totalUsdAtRisk;
  }
  return {
    rawResult: validated.final,
    bundle,
    decisionContract: validated.decisionContract,
    validationViolations: validated.violations,
    auditReceipt,
  };
}

function agentReviewInstruction(record: GeneratedPlanRecord, plan: AgentPlan = record.plan): string {
  return [
    plan.userNotes,
    record.prompt && record.prompt !== plan.userNotes ? record.prompt : '',
  ]
    .filter((entry): entry is string => Boolean(entry?.trim()))
    .join('\n')
    .trim() || 'Review this draft before it is sent for wallet approval. Decide approve, deny, or needs_input and explain why.';
}

function agentReviewRequest(
  record: GeneratedPlanRecord,
  deterministicFacts = gatherDeterministicFacts(record),
  bundle?: AgentReviewEvidenceBundle,
): AgentPlanReviewRequest {
  const reviewPlan = planWithRuntimeTokenLabels(record.plan);
  // Layer 2: wrap user-controlled prose in UNTRUSTED_USER_TEXT delimiters so the model can
  // distinguish data from instructions. The matching system-prompt rule tells the model
  // not to follow commands embedded inside those delimiters.
  const sanitizedReviewPlan = reviewPlan.userNotes
    ? { ...reviewPlan, userNotes: sanitizeUserTextOrEmpty(reviewPlan.userNotes, 'userNotes') }
    : reviewPlan;
  const review = record.agentReview;
  const priorAnswers = review?.answers;
  const sanitizedPriorAnswers = priorAnswers
    ? Object.fromEntries(Object.entries(priorAnswers).map(([key, value]) => [
        key,
        typeof value === 'string' ? sanitizeUserTextOrEmpty(value, `answer.${key}`) : value,
      ]))
    : priorAnswers;
  const priorQuestions = review?.questions;
  const rawInstruction = agentReviewInstruction(record, reviewPlan);
  const instruction = sanitizeUserTextOrEmpty(rawInstruction, 'instruction') || rawInstruction;
  const priorHistorySnippet = review?.history?.slice(-2).map((attempt) => ({
    decision: attempt.decision,
    reason: attempt.reason,
    questionIds: attempt.followUpQuestionIds,
  })).filter((entry) => entry.decision || entry.reason);
  const userPolicies = enabledUserAgentPolicies().map((policy) => ({
    id: policy.id,
    label: policy.label,
    kind: policy.kind,
    detail: policy.detail,
    ...(policy.params && Object.keys(policy.params).length ? { params: policy.params } : {}),
  }));
  const factsForContext = factSetForContext(deterministicFacts);
  const walletContext = walletContextForAgent(record);
  return {
    plan: sanitizedReviewPlan,
    instruction,
    walletAddress: walletContext.address,
    cluster: record.cluster,
    context: {
      activeWorkflow: activeWorkflowLabel(),
      connectedWallet: walletContext.address,
      wallet: walletContext,
      draftCreatedAt: record.createdAt,
      route: reviewPlan.route,
      amount: planAmountSummary(reviewPlan),
      risk: reviewPlan.risk,
      approval: reviewPlan.approval,
      protocolConnectors: protocolConnectorPlannerContext(state.connectedDapps, state.cluster, {
        dialectClientKeyConfigured: Boolean(state.protocolConnectorPrefs.dialectClientKey.trim()),
        includeDisabled: true,
      }),
      ...(factsForContext ? { facts: factsForContext } : {}),
      ...(planBehavesLikeSwap(reviewPlan)
        ? {
            executionPath: {
              kind: reviewPlan.actionType === 'recurring_payment' ? 'recurring_swap' : 'swap',
              aggregator: 'Jupiter',
              routeSelection: 'Jupiter selects the executable route when the quote/order is fetched.',
              userInputRequired: 'Do not ask the user which DEX/protocol to use unless their intent explicitly requires a specific venue.',
            },
          }
        : {}),
      ...(userPolicies.length ? { userPolicies } : {}),
      ...(priorAnswers && Object.keys(priorAnswers).length
        ? {
            priorAnswers: sanitizedPriorAnswers ?? priorAnswers,
            priorQuestions: priorQuestions?.map((question) => ({ id: question.id, prompt: question.prompt })) ?? [],
          }
        : {}),
      ...(priorHistorySnippet?.length ? { priorAttempts: priorHistorySnippet } : {}),
      ...(bundle
        ? {
            evidenceRequirements: bundle.requirements,
            evidenceFacts: bundle.evidenceFacts,
            evidenceGate: bundle.gate,
          }
        : {}),
    },
    ...(state.aiSettings.multiReviewer ? { mode: 'multi' as const } : {}),
  };
}

function agentReviewStateFromResult(
  result: AgentPlanReviewResult,
  previous?: AgentPlanReviewState | undefined,
  reviewedPlan?: AgentPlan | undefined,
  appliedUserPolicyIds?: string[],
  orchestration?: AgentReviewOrchestrationResult,
): AgentPlanReviewState {
  const status: AgentPlanReviewStatus = result.decision === 'approve'
    ? 'approved'
    : result.decision === 'needs_input'
      ? 'needs_input'
      : 'denied';
  const history = appendReviewAttempt(previous?.history, {
    attemptId: `attempt_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
    startedAt: result.checkedAt,
    finishedAt: new Date().toISOString(),
    decision: result.decision,
    reason: result.reason,
    ...(result.questions?.length ? { followUpQuestionIds: result.questions.map((q) => q.id) } : {}),
    ...(previous?.answers && Object.keys(previous.answers).length ? { answersSnapshot: previous.answers } : {}),
  });
  const carriedAnswers = result.decision === 'needs_input' ? previous?.answers : undefined;
  const fingerprint = reviewedPlan ? planFingerprint(reviewedPlan) : previous?.reviewedPlanFingerprint;
  const checks = agentReviewChecksFromEvidence(result.evidence);
  return {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: true,
    status,
    decision: result.decision,
    reason: result.reason,
    summary: result.summary,
    checkedAt: result.checkedAt,
    provider: agentReviewProviderLabel(),
    model: agentReviewModelLabel(),
    source: state.aiSettings.mode,
    evidence: result.evidence,
    ...(checks?.length ? { checks } : {}),
    ...(result.questions?.length ? { questions: result.questions } : {}),
    ...(carriedAnswers ? { answers: carriedAnswers } : {}),
    ...(history.length ? { history } : {}),
    ...(fingerprint ? { reviewedPlanFingerprint: fingerprint } : {}),
    ...(appliedUserPolicyIds && appliedUserPolicyIds.length ? { appliedUserPolicyIds } : {}),
    ...(result.reviewers?.length ? { reviewers: result.reviewers as AgentReviewerEntry[] } : {}),
    ...(orchestration
      ? {
          evidenceRequirements: orchestration.bundle.requirements,
          evidenceFacts: orchestration.bundle.evidenceFacts,
          evidenceGate: orchestration.bundle.gate,
          decisionContract: orchestration.decisionContract,
          auditReceipt: orchestration.auditReceipt,
          ...(orchestration.validationViolations.length
            ? { decisionViolations: orchestration.validationViolations }
            : {}),
        }
      : {}),
  };
}

function agentReviewChecksFromEvidence(evidence: Record<string, unknown> | undefined): AgentReviewCheck[] | undefined {
  if (!isJsonObject(evidence)) return undefined;
  const raw = Array.isArray(evidence.checks)
    ? evidence.checks
    : Array.isArray(evidence.findings)
      ? evidence.findings
      : Array.isArray(evidence.evidenceRows)
        ? evidence.evidenceRows
        : undefined;
  if (!raw) return undefined;
  return parseAgentReviewChecks(raw);
}

function normalizeAgentReviewResultForFacts(
  result: AgentPlanReviewResult,
  plan: AgentPlan,
  facts: AgentReviewFactSet,
  request?: { instruction?: string },
): AgentPlanReviewResult {
  if (result.decision !== 'needs_input' || !result.questions?.length || !planBehavesLikeSwap(plan)) {
    return result;
  }
  const unnecessaryQuestions = result.questions.filter((question) => isSwapQuestionAnsweredByFacts(question, facts));
  if (unnecessaryQuestions.length !== result.questions.length) {
    return result;
  }
  const hasFailedFact = Object.values(facts).some((fact) => fact?.state === 'fail');
  const instruction = request?.instruction ?? '';
  const questionFindings = questionAwareFindingsFromFacts(facts, plan, instruction);
  const unknowns = unsupportedFactsFromInstruction(instruction, facts);
  const reasonPieces: string[] = [];
  for (const finding of questionFindings) {
    if (finding.tone === 'good' || finding.tone === 'neutral') {
      reasonPieces.push(`${finding.label}: ${finding.value}`);
    }
  }
  for (const unknown of unknowns) {
    reasonPieces.push(`${unknown.label}: not in deterministic facts`);
  }
  const reason = hasFailedFact
    ? `A required deterministic fact failed. ${reasonPieces.join('. ')}`.trim()
    : reasonPieces.length
      ? reasonPieces.join('. ') + '.'
      : 'Agent review passed from deterministic action facts (route, protocol, token, limits, simulation).';
  const summary = hasFailedFact
    ? 'Agent review found a blocking issue.'
    : unknowns.length
      ? `Approved from deterministic facts; ${unknowns.length} part${unknowns.length === 1 ? '' : 's'} of the question had no on-device source.`
      : 'Approved from deterministic action facts.';
  const factSources = deterministicSourcesFromFacts(facts, plan);
  const cleanedEvidence = cleanEvidenceAfterConversion(
    result.evidence,
    unnecessaryQuestions.map((q) => q.id),
    questionFindings,
    unknowns,
    factSources,
  );
  const converted: AgentPlanReviewResult = {
    ...result,
    decision: hasFailedFact ? 'deny' : 'approve',
    reason: compactSentence(reason, 360),
    summary: compactSentence(summary, 200),
    questions: undefined,
    evidence: cleanedEvidence,
  };
  if (instruction) {
    return reconcileThresholdReviewDecision(converted, { instruction });
  }
  return converted;
}

interface QuestionAwareFinding {
  label: string;
  value: string;
  tone: 'good' | 'warn' | 'neutral' | 'fail';
}

interface UnsupportedFact {
  label: string;
  value: string;
}

function cleanEvidenceAfterConversion(
  evidence: Record<string, unknown> | undefined,
  convertedQuestionIds: string[],
  questionFindings: QuestionAwareFinding[],
  unknowns: UnsupportedFact[],
  factSources: ReviewSource[] = [],
): Record<string, unknown> {
  const source = evidence && typeof evidence === 'object' && !Array.isArray(evidence) ? evidence : {};
  const { research: _research, findings: rawFindings, facts: rawFacts, sources: rawSources, ...rest } = source;
  const dropLabels = new Set(['research needed', 'research']);
  const filteredFindings = Array.isArray(rawFindings)
    ? rawFindings.filter((entry) => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return false;
        const label = String((entry as Record<string, unknown>).label ?? '').toLowerCase().trim();
        return !dropLabels.has(label);
      })
    : [];
  const factsRecord = rawFacts && typeof rawFacts === 'object' && !Array.isArray(rawFacts)
    ? (rawFacts as Record<string, unknown>)
    : undefined;
  const cleanedFacts = factsRecord
    ? Object.fromEntries(Object.entries(factsRecord).filter(([key]) => key !== 'research'))
    : undefined;
  // Build a set of labels already covered by server-side findings (which include the
  // orchestrator's policyBundle rows merged in by aiPlanner). Browser-demo's inline
  // question-aware findings only add rows for labels the server hasn't already covered,
  // so the inbox card never shows two rows for the same gate.
  const serverLabelsCovered = new Set<string>();
  for (const finding of filteredFindings) {
    if (!finding || typeof finding !== 'object') continue;
    const label = String((finding as Record<string, unknown>).label ?? '').trim().toLowerCase();
    if (label) serverLabelsCovered.add(label);
  }
  const newFindings = [
    ...questionFindings.filter((entry) => !serverLabelsCovered.has(entry.label.trim().toLowerCase())),
    ...unknowns
      .filter((entry) => !serverLabelsCovered.has(entry.label.trim().toLowerCase()))
      .map((entry) => ({ label: entry.label, value: entry.value, tone: 'warn' as const })),
  ];
  const autoResolvedFinding = newFindings.length || filteredFindings.length
    ? undefined
    : {
        label: 'Auto-resolved',
        value: convertedQuestionIds.length
          ? `Deterministic action facts answered: ${convertedQuestionIds.join(', ')}.`
          : 'Deterministic action facts answered the agent’s open questions.',
        tone: 'good' as const,
      };
  const findings = [
    ...newFindings,
    ...filteredFindings,
    ...(autoResolvedFinding ? [autoResolvedFinding] : []),
  ];
  const existingSources = Array.isArray(rawSources)
    ? rawSources.filter((entry): entry is Record<string, unknown> => Boolean(entry && typeof entry === 'object' && !Array.isArray(entry)))
    : [];
  const dedupedSources = mergeReviewSources(existingSources, factSources);
  return {
    ...rest,
    findings,
    ...(cleanedFacts && Object.keys(cleanedFacts).length ? { facts: cleanedFacts } : {}),
    ...(dedupedSources.length ? { sources: dedupedSources } : {}),
  };
}

interface ReviewSource {
  url: string;
  title?: string;
}

function deterministicSourcesFromFacts(facts: AgentReviewFactSet, plan: AgentPlan): ReviewSource[] {
  const sources: ReviewSource[] = [];
  const tokenSource = typeof facts.tokenMint?.detail?.marketSource === 'string'
    ? (facts.tokenMint.detail.marketSource as string)
    : undefined;
  const tokenRows = Array.isArray(facts.tokenMint?.detail?.tokens)
    ? facts.tokenMint.detail.tokens
    : [];
  const hasCoinGeckoTokenSource = tokenRows.some((entry) => {
    const record = asRecord(entry);
    const market = asRecord(record?.market);
    return market?.source === 'coingecko' || Boolean(asRecord(market?.coingecko));
  });
  if (tokenSource === 'birdeye') {
    sources.push({ url: 'https://birdeye.so/', title: 'BirdEye - Solana token prices' });
  } else if (tokenSource === 'dexscreener') {
    sources.push({ url: 'https://dexscreener.com/solana', title: 'DEX Screener - Solana markets' });
  }
  if (hasCoinGeckoTokenSource) {
    sources.push({ url: 'https://www.coingecko.com/', title: 'CoinGecko - Token prices and market data' });
  }
  if (planBehavesLikeSwap(plan)) {
    sources.push({ url: 'https://jup.ag/', title: 'Jupiter - Solana swap aggregator' });
  }
  if (facts.marketSentiment?.state === 'ok') {
    sources.push({
      url: 'https://alternative.me/crypto/fear-and-greed-index/',
      title: 'alternative.me - Crypto Fear & Greed Index',
    });
  }
  if (facts.marketConditions?.state === 'ok') {
    sources.push({
      url: 'https://www.coingecko.com/en/global-charts',
      title: 'CoinGecko - Global market dominance & volume',
    });
  }
  if (facts.walletActivity?.state === 'ok' || facts.walletActivity?.state === 'warn') {
    sources.push({
      url: 'https://www.helius.dev/docs/rpc/gettransfersbyaddress',
      title: 'Helius getTransfersByAddress',
    });
  }
  if (facts.walletHoldings?.state === 'ok' || facts.walletHoldings?.state === 'warn') {
    sources.push({ url: 'https://birdeye.so/', title: 'BirdEye wallet token list' });
  }
  if (facts.connectorRead?.state === 'ok' || facts.connectorRead?.state === 'warn') {
    const website = typeof facts.connectorRead.detail?.connectorWebsite === 'string'
      ? facts.connectorRead.detail.connectorWebsite
      : undefined;
    sources.push({
      url: website || 'https://agentic-signer.com/app',
      title: typeof facts.connectorRead.detail?.connectorName === 'string'
        ? `${facts.connectorRead.detail.connectorName} connector facts`
        : 'Protocol connector facts',
    });
  }
  return sources;
}

function mergeReviewSources(
  existing: Array<Record<string, unknown>>,
  added: ReviewSource[],
): Array<Record<string, unknown>> {
  const out: Array<Record<string, unknown>> = [];
  const seen = new Set<string>();
  for (const entry of [...existing, ...added.map((source) => ({ url: source.url, ...(source.title ? { title: source.title } : {}) }))]) {
    const url = typeof entry.url === 'string' ? entry.url.trim() : '';
    if (!url || seen.has(url)) continue;
    seen.add(url);
    out.push(entry);
  }
  return out;
}

function questionAwareFindingsFromFacts(
  facts: AgentReviewFactSet,
  plan: AgentPlan,
  instruction: string,
): QuestionAwareFinding[] {
  const findings: QuestionAwareFinding[] = [];
  const seenLabels = new Set<string>();
  const lowerInstruction = instruction.toLowerCase();
  const tokens = tokensFromTokenMintFact(facts.tokenMint);

  for (const token of tokens) {
    const price = token.priceUsd;
    if (price === undefined || !Number.isFinite(price)) continue;
    const symbol = (token.symbol ?? token.label ?? '').toUpperCase();
    if (!symbol) continue;
    const label = `${symbol} price`;
    if (seenLabels.has(label.toLowerCase())) continue;
    seenLabels.add(label.toLowerCase());
    findings.push({
      label,
      value: `${formatUsdEstimate(price)} (${token.source ?? 'BirdEye'})`,
      tone: instructionMentionsToken(lowerInstruction, symbol, token.name) ? 'good' : 'neutral',
    });
  }

  if (/\b(market\s+cap|mcap)\b/i.test(instruction)) {
    for (const token of tokens) {
      if (token.marketCapUsd === undefined || !Number.isFinite(token.marketCapUsd)) continue;
      const symbol = (token.symbol ?? token.label ?? '').toUpperCase();
      if (!symbol) continue;
      const label = `${symbol} market cap`;
      if (seenLabels.has(label.toLowerCase())) continue;
      seenLabels.add(label.toLowerCase());
      findings.push({
        label,
        value: `${formatUsdCompact(token.marketCapUsd)} (${token.marketSource ?? token.source ?? 'CoinGecko'})`,
        tone: instructionMentionsToken(lowerInstruction, symbol, token.name) ? 'good' : 'neutral',
      });
    }
  }

  if (/\b(volume\s+24h?|24h?\s+volume)\b/i.test(instruction)) {
    for (const token of tokens) {
      if (token.volume24hUsd === undefined || !Number.isFinite(token.volume24hUsd)) continue;
      const symbol = (token.symbol ?? token.label ?? '').toUpperCase();
      if (!symbol) continue;
      const label = `${symbol} 24h volume`;
      if (seenLabels.has(label.toLowerCase())) continue;
      seenLabels.add(label.toLowerCase());
      findings.push({
        label,
        value: `${formatUsdCompact(token.volume24hUsd)} (${token.marketSource ?? token.source ?? 'CoinGecko'})`,
        tone: instructionMentionsToken(lowerInstruction, symbol, token.name) ? 'good' : 'neutral',
      });
    }
  }

  if (/\b(24h\s+(?:change|price\s+change)|price\s+change\s+24h)\b/i.test(instruction)) {
    for (const token of tokens) {
      if (token.change24hPct === undefined || !Number.isFinite(token.change24hPct)) continue;
      const symbol = (token.symbol ?? token.label ?? '').toUpperCase();
      if (!symbol) continue;
      const label = `${symbol} 24h change`;
      if (seenLabels.has(label.toLowerCase())) continue;
      seenLabels.add(label.toLowerCase());
      findings.push({
        label,
        value: `${token.change24hPct >= 0 ? '+' : ''}${token.change24hPct.toFixed(2)}% (${token.marketSource ?? token.source ?? 'CoinGecko'})`,
        tone: instructionMentionsToken(lowerInstruction, symbol, token.name) ? 'good' : 'neutral',
      });
    }
  }

  const slippageBps = typeof facts.limits?.detail?.slippageBps === 'number'
    ? (facts.limits.detail.slippageBps as number)
    : undefined;
  if (slippageBps && Number.isFinite(slippageBps)) {
    findings.push({
      label: 'Slippage protection',
      value: `${(slippageBps / 100).toFixed(2)}% (${slippageBps} bps)`,
      tone: slippageBps > 200 ? 'warn' : 'good',
    });
  }

  if (planBehavesLikeSwap(plan)) {
    const amount = planParameter(plan, ['amount', 'inputAmount', 'plannedAmount']).trim();
    const inputSymbol = (planParameter(plan, ['inputToken']).trim() || '').toUpperCase();
    if (amount && inputSymbol) {
      const numericAmount = Number(amount);
      const inputToken = tokens.find((t) => (t.symbol ?? t.label ?? '').toUpperCase() === inputSymbol);
      const inputPrice = inputToken?.priceUsd;
      const usdEstimate = Number.isFinite(numericAmount) && inputPrice && Number.isFinite(inputPrice)
        ? ` (~${formatUsdEstimate(numericAmount * inputPrice)})`
        : '';
      findings.push({
        label: 'Swap amount',
        value: `${amount} ${inputSymbol}${usdEstimate}`,
        tone: 'neutral',
      });
    }
  }

  const fearGreed = fearGreedValueFromFacts(facts);
  if (fearGreed) {
    const mentioned = /fear\s*(?:&|and)\s*greed|crypto\s+fear|fng/i.test(instruction);
    const threshold = parseFearGreedThreshold(instruction);
    let tone: QuestionAwareFinding['tone'] = 'neutral';
    if (threshold !== undefined) {
      tone = fearGreed.value > threshold ? 'good' : 'fail';
    } else if (mentioned) {
      tone = 'good';
    }
    findings.push({
      label: 'BTC Fear & Greed Index',
      value: `${fearGreed.value} (${fearGreed.classification}) - alternative.me`,
      tone,
    });
  }

  const conditions = marketConditionsFromFacts(facts);
  if (conditions) {
    const btcDominanceMentioned = /\bbtc\s*dominance\b|\bbitcoin\s+dominance\b/i.test(instruction);
    const btcThreshold = parseDominanceThreshold(instruction);
    if (conditions.btcDominancePct !== undefined) {
      let tone: QuestionAwareFinding['tone'] = btcDominanceMentioned ? 'good' : 'neutral';
      if (btcThreshold !== undefined) {
        tone = conditions.btcDominancePct > btcThreshold ? 'good' : 'fail';
      }
      findings.push({
        label: 'BTC dominance',
        value: `${conditions.btcDominancePct.toFixed(2)}% - CoinGecko`,
        tone,
      });
    }
    if (conditions.totalMarketCapUsd !== undefined && /total\s+market\s+cap|crypto\s+market\s+cap/i.test(instruction)) {
      findings.push({
        label: 'Total crypto market cap',
        value: `${formatUsdCompact(conditions.totalMarketCapUsd)} - CoinGecko`,
        tone: 'neutral',
      });
    }
    if (conditions.marketCapChangePct24hUsd !== undefined && /24h\s+(?:market|change)|market\s+cap\s+change/i.test(instruction)) {
      findings.push({
        label: '24h market cap change',
        value: `${conditions.marketCapChangePct24hUsd >= 0 ? '+' : ''}${conditions.marketCapChangePct24hUsd.toFixed(2)}% - CoinGecko`,
        tone: 'neutral',
      });
    }
  }

  for (const token of tokenSecurityRows(facts, instruction)) {
    findings.push(token);
  }

  return findings;
}

// Delegates to the shared workflow helper so threshold parsing stays byte-identical
// across browser-demo, mcp-server, and any future surface.
function parseDominanceThreshold(instruction: string): number | undefined {
  return workflowParseDominanceThreshold(instruction);
}

interface TokenSecurityRow extends QuestionAwareFinding {}

const KNOWN_STABLECOIN_SYMBOLS = new Set(['USDC', 'USDT', 'PYUSD', 'USDS', 'USDE', 'DAI', 'FDUSD']);

function tokenSecurityRows(facts: AgentReviewFactSet, instruction: string): TokenSecurityRow[] {
  const tokenList = facts.tokenMint?.detail?.tokens;
  if (!Array.isArray(tokenList)) return [];
  const wantMintAuth = /\bmint(?:ing)?\s+authority\b/i.test(instruction);
  const wantFreezeAuth = /\bfreeze\s+authority\b/i.test(instruction);
  const ageMatch = instruction.match(/token\s+age[^.\n]*?(\d+)\s*(h(?:ours?)?|d(?:ays?)?|w(?:eeks?)?)/i);
  const minAgeSeconds = ageMatch ? parseAgeThresholdSeconds(ageMatch[1]!, ageMatch[2]!) : undefined;
  const wantAge = minAgeSeconds !== undefined || /\btoken\s+age\b|\bage\s+above\b|\bcreated\s+(?:at|on|after)\b/i.test(instruction);
  const rows: TokenSecurityRow[] = [];
  for (const raw of tokenList) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) continue;
    const entry = raw as Record<string, unknown>;
    const security = entry.security as Record<string, unknown> | undefined;
    if (!security || typeof security !== 'object') continue;
    const role = typeof entry.role === 'string' ? entry.role.toUpperCase() : 'TOKEN';
    const symbol = typeof entry.symbol === 'string' ? entry.symbol : (typeof entry.label === 'string' ? entry.label : '');
    const prefix = symbol ? `${role} ${symbol}` : role;
    // Established stablecoins (USDC, USDT, etc.) intentionally keep their freeze authority
    // for compliance. Skip mint/freeze authority rows for them so the findings grid
    // doesn't surface expected, non-actionable behavior.
    const isStable = KNOWN_STABLECOIN_SYMBOLS.has(symbol.toUpperCase());
    if (wantMintAuth && !isStable) {
      const mintAuth = security.mintAuthority;
      const disabled = mintAuth === null;
      rows.push({
        label: `${prefix} mint authority`,
        value: disabled
          ? 'disabled (null) - BirdEye'
          : typeof mintAuth === 'string' && mintAuth
            ? `enabled: ${short(mintAuth)} - BirdEye`
            : 'unknown',
        tone: disabled ? 'good' : typeof mintAuth === 'string' ? 'fail' : 'warn',
      });
    }
    if (wantFreezeAuth && !isStable) {
      const freezeAuth = security.freezeAuthority;
      const disabled = freezeAuth === null;
      rows.push({
        label: `${prefix} freeze authority`,
        value: disabled
          ? 'disabled (null) - BirdEye'
          : typeof freezeAuth === 'string' && freezeAuth
            ? `enabled: ${short(freezeAuth)} - BirdEye`
            : 'unknown',
        tone: disabled ? 'good' : typeof freezeAuth === 'string' ? 'fail' : 'warn',
      });
    }
    if (wantAge) {
      const ageSeconds = typeof security.ageSeconds === 'number' ? security.ageSeconds : undefined;
      if (ageSeconds === undefined) {
        rows.push({ label: `${prefix} token age`, value: 'unknown', tone: 'warn' });
      } else {
        const passes = minAgeSeconds === undefined ? undefined : ageSeconds >= minAgeSeconds;
        rows.push({
          label: `${prefix} token age`,
          value: `${formatTokenAge(ageSeconds)} - BirdEye`,
          tone: passes === undefined ? 'neutral' : passes ? 'good' : 'fail',
        });
      }
    }
  }
  return rows;
}

function parseAgeThresholdSeconds(value: string, unit: string): number {
  return workflowParseAgeThresholdSeconds(value, unit);
}

function formatTokenAge(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  if (seconds < 86_400) return `${(seconds / 3600).toFixed(1)}h`;
  if (seconds < 30 * 86_400) return `${(seconds / 86_400).toFixed(1)}d`;
  return `${(seconds / (30 * 86_400)).toFixed(1)} months`;
}

function parseFearGreedThreshold(instruction: string): number | undefined {
  return workflowParseFearGreedThreshold(instruction);
}

interface TokenPriceFact {
  role?: string;
  symbol?: string;
  label?: string;
  name?: string;
  priceUsd?: number;
  marketCapUsd?: number;
  volume24hUsd?: number;
  change24hPct?: number;
  source?: string;
  marketSource?: string;
}

function tokensFromTokenMintFact(fact: AgentReviewFact | undefined): TokenPriceFact[] {
  const tokens = fact?.detail?.tokens;
  if (!Array.isArray(tokens)) return [];
  return tokens.flatMap((entry): TokenPriceFact[] => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return [];
    const record = entry as Record<string, unknown>;
    const market = record.market && typeof record.market === 'object' && !Array.isArray(record.market)
      ? (record.market as Record<string, unknown>)
      : undefined;
    const coingecko = asRecord(market?.coingecko);
    const price = numberField(market?.priceUsd)
      ?? numberField(coingecko?.priceUsd)
      ?? numberField(coingecko?.onchainPriceUsd);
    const marketCap = numberField(market?.marketCap)
      ?? numberField(market?.marketCapUsd)
      ?? numberField(coingecko?.marketCapUsd);
    const volume24h = numberField(market?.volumeH24)
      ?? numberField(market?.volume24hUsd)
      ?? numberField(coingecko?.volume24hUsd);
    const change24h = numberField(market?.change24hPct)
      ?? numberField(coingecko?.change24hPct);
    const sourceTag = market && typeof market.source === 'string'
      ? market.source
      : typeof record.source === 'string' ? record.source : coingecko ? 'coingecko' : undefined;
    const metricSource = coingecko ? 'CoinGecko' : sourceTag ? prettifyMarketSource(sourceTag) : undefined;
    return [{
      role: typeof record.role === 'string' ? record.role : undefined,
      symbol: typeof record.symbol === 'string' ? record.symbol : undefined,
      label: typeof record.label === 'string' ? record.label : undefined,
      name: typeof record.name === 'string' ? record.name : undefined,
      priceUsd: price,
      marketCapUsd: marketCap,
      volume24hUsd: volume24h,
      change24hPct: change24h,
      source: sourceTag ? prettifyMarketSource(sourceTag) : undefined,
      marketSource: metricSource,
    }];
  });
}

function prettifyMarketSource(value: string): string {
  if (value === 'birdeye') return 'BirdEye';
  if (value === 'dexscreener') return 'DEX Screener';
  if (value === 'coingecko') return 'CoinGecko';
  return value;
}

function instructionMentionsToken(lowerInstruction: string, symbol: string, name?: string): boolean {
  if (!lowerInstruction) return false;
  if (symbol && lowerInstruction.includes(symbol.toLowerCase())) return true;
  if (name && lowerInstruction.includes(name.toLowerCase())) return true;
  if (symbol === 'SOL' && /\bsolana\b/.test(lowerInstruction)) return true;
  if (symbol === 'USDC' && /\busd\s*coin\b/.test(lowerInstruction)) return true;
  return false;
}

function unsupportedFactsFromInstruction(
  instruction: string,
  facts?: AgentReviewFactSet,
): UnsupportedFact[] {
  const found: UnsupportedFact[] = [];
  const lower = instruction.toLowerCase();
  const sentimentOk = facts ? facts.marketSentiment?.state === 'ok' : false;
  const conditionsOk = facts ? facts.marketConditions?.state === 'ok' : false;
  const conditionsDetail = (facts?.marketConditions?.detail ?? {}) as Record<string, unknown>;
  const tokenMintOk = facts ? facts.tokenMint?.state === 'ok' : false;
  const tokenMarketFacts = tokensFromTokenMintFact(facts?.tokenMint);
  const hasTokenMarketCap = tokenMarketFacts.some((token) => token.marketCapUsd !== undefined);
  const hasToken24hVolume = tokenMarketFacts.some((token) => token.volume24hUsd !== undefined);
  const hasTokenSecurity = tokenMintOk && Array.isArray((facts?.tokenMint?.detail as { tokens?: unknown[] } | undefined)?.tokens)
    && ((facts!.tokenMint!.detail as { tokens?: Array<Record<string, unknown>> }).tokens ?? []).some((token) => Boolean(token.security));
  const checks: Array<{ test: RegExp; label: string; hint: string; satisfied?: boolean }> = [
    {
      test: /fear\s*(?:&|and)\s*greed|crypto\s+fear|fng/i,
      label: 'Fear & Greed Index',
      hint: 'No on-device source for this metric.',
      satisfied: sentimentOk,
    },
    {
      test: /\b(btc|bitcoin)\s*dominance\b/i,
      label: 'BTC dominance',
      hint: 'No on-device source for this metric.',
      satisfied: conditionsOk && typeof conditionsDetail.btcDominancePct === 'number',
    },
    {
      test: /\bmint(?:ing)?\s+authority\b/i,
      label: 'Mint authority',
      hint: 'No on-device source for this metric.',
      satisfied: hasTokenSecurity,
    },
    {
      test: /\bfreeze\s+authority\b/i,
      label: 'Freeze authority',
      hint: 'No on-device source for this metric.',
      satisfied: hasTokenSecurity,
    },
    {
      test: /\btoken\s+age\b|\bage\s+above\b/i,
      label: 'Token age',
      hint: 'No on-device source for this metric.',
      satisfied: hasTokenSecurity,
    },
    { test: /\b(rsi|relative\s+strength)\b/i, label: 'RSI', hint: 'No on-device source for this metric.' },
    { test: /\bfunding\s+rate\b/i, label: 'Funding rate', hint: 'No on-device source for this metric.' },
    { test: /\b(open\s+interest|oi)\b/i, label: 'Open interest', hint: 'No on-device source for this metric.' },
    { test: /\b(tvl|total\s+value\s+locked)\b/i, label: 'TVL', hint: 'No on-device source for this metric.' },
    {
      test: /\b(volume\s+24h?|24h?\s+volume)\b/i,
      label: '24h volume',
      hint: 'No on-device source for this metric.',
      satisfied: hasToken24hVolume || (conditionsOk && typeof conditionsDetail.totalVolume24hUsd === 'number'),
    },
    {
      test: /\b(market\s+cap|mcap)\b/i,
      label: 'Market cap',
      hint: 'No on-device source for this metric.',
      satisfied: hasTokenMarketCap || (conditionsOk && typeof conditionsDetail.totalMarketCapUsd === 'number'),
    },
    { test: /\b(yesterday|last\s+(?:hour|day|week|month)|historical)\b/i, label: 'Historical data', hint: 'No on-device source for historical lookups.' },
  ];
  for (const check of checks) {
    if (check.satisfied) continue;
    if (check.test.test(lower)) {
      found.push({
        label: check.label,
        value: `${check.hint} Supply the value in the draft or pick an AI provider that can fetch it.`,
      });
    }
  }
  return found;
}

function planBehavesLikeSwap(plan: AgentPlan): boolean {
  return plan.actionType === 'swap' ||
    plan.parameters.actionKind === 'swap';
}

function isSwapQuestionAnsweredByFacts(question: AgentReviewQuestion, facts: AgentReviewFactSet): boolean {
  const prompt = question.prompt.toLowerCase();
  const asksProtocol = /\b(protocol|dex|jupiter|raydium|orca|aggregator|venue)\b/.test(prompt);
  if (asksProtocol && facts.protocol && facts.protocol.state !== 'missing') return true;
  const asksTokenIdentity = /\b(token|mint|symbol|name|address|verified|source|solscan|birdeye|dexscreener|coingecko)\b/.test(prompt);
  if (asksTokenIdentity && facts.tokenMint && facts.tokenMint.state !== 'missing') return true;
  const asksRoute = /\b(route|quote|slippage|output|minimum received|min received)\b/.test(prompt);
  if (asksRoute && (facts.route || facts.quote || facts.limits)) return true;
  return false;
}

function enabledUserAgentPolicies(): UserAgentPolicy[] {
  return state.agentPolicies.filter((policy) => policy.enabled);
}

function planFingerprint(plan: AgentPlan): string {
  return stableJson({
    intent: plan.intent,
    route: plan.route,
    risk: plan.risk,
    approval: plan.approval,
    actionType: plan.actionType,
    templateId: (plan as { templateId?: string }).templateId ?? '',
    parameters: plan.parameters,
    userNotes: plan.userNotes ?? '',
  });
}

function isAgentReviewStale(record: GeneratedPlanRecord | undefined): boolean {
  const review = record?.agentReview;
  if (!review?.reviewedPlanFingerprint) return false;
  if (review.status !== 'approved' && review.status !== 'needs_input' && review.status !== 'denied') return false;
  return planFingerprint(planWithRuntimeTokenLabels(record!.plan)) !== review.reviewedPlanFingerprint;
}

function appendReviewAttempt(prev: AgentReviewAttempt[] | undefined, attempt: AgentReviewAttempt): AgentReviewAttempt[] {
  const next = [...(prev ?? []), attempt];
  return next.slice(-5);
}

async function recordAgentOverrideReceipt(record: GeneratedPlanRecord, userReason: string | undefined): Promise<void> {
  const review = record.agentReview;
  if (!review) return;
  const blockReason = agentReviewQueueOverrideMessage(record) || 'Agent did not approve this draft.';
  const overriddenAt = new Date().toISOString();
  const actionId = `browser-override-${record.id}-${Date.now().toString(36)}`;
  const walletAddress = state.address || record.walletAddress;
  const cluster = record.cluster;
  const planSummary = compactSentence(record.plan.intent || record.plan.templateTitle || 'Agent draft', 132);
  const summary = overrideReceiptSummary(review, userReason, planSummary);
  const note = overrideReceiptNote(review, userReason);
  const overrideEntry: AgentReviewOverride = {
    overriddenAt,
    agentStatus: review.status,
    agentReason: review.reason || blockReason,
    ...(review.decision ? { agentDecision: review.decision } : {}),
    ...(review.summary ? { agentSummary: review.summary } : {}),
    ...(userReason && userReason.trim() ? { userReason: userReason.trim() } : {}),
    ...(review.provider ? { provider: review.provider } : {}),
    ...(review.model ? { model: review.model } : {}),
    ...(review.source ? { source: review.source } : {}),
  };
  await updateGeneratedPlan(record.id, { agentOverride: overrideEntry }).catch(() => undefined);
  const receipt: ActionReceipt = {
    actionId,
    status: 'approved',
    summary,
    note,
    walletAddress,
    cluster,
    createdAt: overriddenAt,
    completedAt: overriddenAt,
    evidenceKind: 'agent_override_receipt',
    agentOverride: {
      reviewSnapshot: review,
      ...(userReason ? { userReason } : {}),
      overriddenAt,
      blockReason,
      planSummary,
      planId: record.id,
    },
  };
  state.receipts = mergeActionReceipts([receipt], state.receipts);
  saveBrowserWorkflowState();
}

function overrideReceiptSummary(
  review: AgentPlanReviewState,
  userReason: string | undefined,
  planSummary: string,
): string {
  const status = review.status;
  const verdict = status === 'denied'
    ? 'agent denied'
    : status === 'checking'
      ? 'agent still checking'
      : status === 'needs_input'
        ? 'agent needed input'
        : status === 'error'
          ? 'agent review failed'
          : 'agent not approved';
  const reasonPart = userReason ? ` User reason: ${userReason}.` : '';
  return compactSentence(`Overrode ${verdict}. Sent ${planSummary} for approval anyway.${reasonPart}`, 240);
}

function overrideReceiptNote(review: AgentPlanReviewState, userReason: string | undefined): string {
  const agentSaid = review.reason?.trim() || 'No reason recorded.';
  const userPart = userReason?.trim()
    ? `User reason: ${userReason.trim()}`
    : 'User did not give a reason.';
  return compactSentence(`Agent said: ${agentSaid}. ${userPart}`, 360);
}

function agentReviewProviderLabel(): string {
  if (state.aiSettings.mode === 'bridge') {
    return state.aiStatus?.provider ?? state.aiStatus?.apiFormat ?? 'Local bridge AI';
  }
  if (state.aiSettings.mode === 'device-agent') {
    return state.deviceAgentStatus?.provider ?? aiProviderPresetById(state.aiSettings.provider).label;
  }
  return aiProviderPresetById(state.aiSettings.provider).label;
}

function agentReviewModelLabel(): string {
  if (state.aiSettings.mode === 'bridge') {
    return state.aiStatus?.model ?? 'model configured';
  }
  if (state.aiSettings.mode === 'device-agent') {
    return state.deviceAgentStatus?.model ?? state.aiSettings.model ?? 'model configured';
  }
  return state.aiSettings.model || aiProviderPresetById(state.aiSettings.provider).model;
}

function factSetForContext(facts: AgentReviewFactSet): Record<string, unknown> | undefined {
  const entries = Object.entries(facts).filter(([, fact]) => Boolean(fact));
  if (!entries.length) return undefined;
  return Object.fromEntries(entries.map(([key, fact]) => [key, {
    state: fact!.state,
    source: fact!.source,
    ...(fact!.message ? { message: fact!.message } : {}),
    ...(fact!.detail ? { detail: fact!.detail } : {}),
  }]));
}

function mergeReviewFacts(
  deterministic: AgentReviewFactSet,
  aiEvidence: Record<string, unknown> | undefined,
): AgentReviewFactSet {
  const merged: AgentReviewFactSet = { ...deterministic };
  const aiFacts = aiEvidence?.facts;
  if (!aiFacts || typeof aiFacts !== 'object' || Array.isArray(aiFacts)) return merged;
  const checkedAt = new Date().toISOString();
  const slots: Array<keyof AgentReviewFactSet> = [
    'evidenceRoutes',
    'research',
    'quote',
    'route',
    'policy',
    'simulation',
    'protocol',
    'protocolConnector',
    'connectorRead',
    'blinkAction',
    'blinkClassification',
    'tokenMint',
    'recipient',
    'limits',
    'schedule',
    'walletActivity',
    'walletHoldings',
    'marketSentiment',
    'marketConditions',
  ];
  for (const slot of slots) {
    const existing = merged[slot];
    if (existing && existing.source === 'deterministic' && existing.state !== 'missing') {
      continue;
    }
    const aiSlot = (aiFacts as Record<string, unknown>)[slot];
    if (!aiSlot || typeof aiSlot !== 'object' || Array.isArray(aiSlot)) continue;
    const slotRecord = aiSlot as Record<string, unknown>;
    const stateValue = slotRecord.state;
    const validState = stateValue === 'checked' || stateValue === 'missing' || stateValue === 'warn' || stateValue === 'ok' || stateValue === 'fail'
      ? stateValue
      : 'checked';
    merged[slot] = {
      state: validState,
      source: 'ai',
      checkedAt,
      ...(typeof slotRecord.message === 'string' ? { message: slotRecord.message } : {}),
      ...(slotRecord.detail && typeof slotRecord.detail === 'object' && !Array.isArray(slotRecord.detail)
        ? { detail: slotRecord.detail as Record<string, unknown> }
        : {}),
    };
  }
  return merged;
}

const TOKEN_FACT_ROUTE_NEEDS: AgentFactNeed[] = ['token_metadata', 'token_security', 'token_market'];

async function gatherAgentReviewFacts(
  record: GeneratedPlanRecord,
  options: { question?: string; instruction?: string } = {},
): Promise<AgentReviewFactSet> {
  const facts = gatherDeterministicFacts(record);
  const plan = planWithRuntimeTokenLabels(record.plan);
  const routePlan = planFactRoutesForAgentReview(record, plan, options);
  facts.evidenceRoutes = agentFactRoutePlanFact(routePlan);
  if (routePlanHasAnyNeed(routePlan, TOKEN_FACT_ROUTE_NEEDS)) {
    const enriched = routePlanHasAnyId(routePlan, ['birdeye.token_metadata', 'birdeye.token_security', 'birdeye.price_multi'])
      ? await enrichTokenFactsFromBirdEye(plan, facts).catch(() => false)
      : false;
    if (routePlanHasAnyId(routePlan, ['coingecko.token_evidence'])) {
      await enrichTokenFactsFromCoinGecko(plan, facts).catch(() => undefined);
    }
    if (!enriched && routePlanHasAnyId(routePlan, ['dexscreener.token_pairs'])) {
      await enrichTokenFactsFromDexScreener(plan, facts).catch(() => undefined);
    }
  }
  await Promise.all([
    enrichWalletFactsForAgent(record, facts, routePlan).catch(() => undefined),
    enrichConnectorFactsForAgent(record, plan, facts, routePlan).catch(() => undefined),
    routePlanHasAnyId(routePlan, ['rpc.simulate_transaction'])
      ? enrichSimulationFactsForAgent(record, plan, facts, routePlan).catch(() => undefined)
      : Promise.resolve(),
    routePlanHasAnyId(routePlan, ['alternative_me.fear_greed'])
      ? enrichMarketSentimentFromAlternativeMe(facts).catch(() => undefined)
      : Promise.resolve(),
    routePlanHasAnyId(routePlan, ['coingecko.global'])
      ? enrichMarketConditionsFromCoinGecko(facts).catch(() => undefined)
      : Promise.resolve(),
  ]);
  return facts;
}

function planFactRoutesForAgentReview(
  record: GeneratedPlanRecord,
  plan: AgentPlan,
  options: { question?: string; instruction?: string },
): AgentFactRoutePlan {
  const walletContext = walletContextForAgent(record);
  const connector = selectedConnectorForDraftParameters(plan.parameters) ??
    findProtocolConnectorByInput(plan.parameters.protocol || plan.parameters.dapp || plan.route);
  const connectorForm = selectedConnectorActionForm(plan.parameters) ?? connectorActionFormByActionType(plan.actionType);
  const connectorSubAction = connectorForm ? selectedSubAction(connectorForm, plan.parameters) : undefined;
  const connectorActionKind = connectorSubAction?.actionType ?? connectorForm?.actionType ?? plan.actionType;
  const connectorEnabled = Boolean(connector && isDappEnabled(connector.id, state.connectedDapps, state.cluster));
  const connectorReadReady = Boolean(
    connector &&
      connectorEnabled &&
      connector.readSource &&
      (!connector.requiresClientKey || state.protocolConnectorPrefs.dialectClientKey.trim()),
  );
  const riskProfile = connector
    ? connectorProfileKind(connector.id, connectorActionKind ?? '')
    : undefined;
  return planAgentReviewFactRoutes({
    actionType: plan.actionType,
    intent: plan.intent,
    route: plan.route,
    risk: plan.risk,
    approval: plan.approval,
    userNotes: plan.userNotes,
    instruction: options.instruction,
    question: options.question,
    prompt: record.prompt,
    parameters: plan.parameters,
    hasWallet: Boolean(walletContext.address),
    hasTokenMints: planTokenCandidates(plan).some((token) => Boolean(token.mint)),
    hasProtocolConnector: connectorReadReady,
    hasPreparedTx: Boolean(extractPreparedTxBase64(record)),
    ...(riskProfile ? { riskProfile } : {}),
    ...(connector
      ? {
          connector: {
            id: connector.id,
            name: connector.name,
            enabled: connectorEnabled,
            readReady: connectorReadReady,
            readSource: connector.readSource ?? '',
            actionSource: connector.actionSource ?? '',
            capabilities: connector.capabilities,
            actionKind: connectorActionKind,
            operation: connectorSubAction?.label ?? connectorForm?.operationLabel ?? plan.parameters.operation,
          },
        }
      : {}),
  });
}

function agentFactRoutePlanFact(routePlan: AgentFactRoutePlan): AgentReviewFact {
  const checkedAt = new Date().toISOString();
  return {
    state: routePlan.routes.length ? 'checked' : 'missing',
    source: 'deterministic',
    checkedAt,
    message: routePlan.routeText,
    detail: {
      routes: routePlan.routes.map((route) => ({
        id: route.id,
        need: route.need,
        provider: route.provider,
        endpoint: route.endpoint,
        status: route.status,
        reason: route.reason,
        ...(route.params ? { params: route.params } : {}),
      })),
      skipped: routePlan.skipped,
    },
  };
}

interface FactSetEvidenceSlotMapping {
  slot: keyof AgentReviewFactSet;
  routeId: string;
  source: AgentEvidenceFact['source'];
  label: string;
}

const FACT_SET_TO_EVIDENCE_ROUTES: FactSetEvidenceSlotMapping[] = [
  { slot: 'quote', routeId: 'jupiter.swap_order_preview', source: 'jupiter', label: 'Swap quote' },
  { slot: 'route', routeId: 'jupiter.swap_route', source: 'jupiter', label: 'Swap route' },
  { slot: 'walletActivity', routeId: 'helius.getTransfersByAddress', source: 'helius', label: 'Recent wallet activity' },
  { slot: 'walletHoldings', routeId: 'birdeye.wallet_token_list', source: 'birdeye', label: 'Wallet holdings' },
  { slot: 'tokenMint', routeId: 'birdeye.token_metadata', source: 'birdeye', label: 'Token identity' },
  { slot: 'marketSentiment', routeId: 'alternative_me.fear_greed', source: 'alternative_me', label: 'Market sentiment' },
  { slot: 'marketConditions', routeId: 'coingecko.global', source: 'coingecko', label: 'Market conditions' },
  { slot: 'connectorRead', routeId: 'protocol_connector.read_facts', source: 'protocol_connector', label: 'Connector read facts' },
  { slot: 'simulation', routeId: 'rpc.simulate_transaction', source: 'rpc', label: 'Transaction simulation' },
  { slot: 'research', routeId: 'external_research.current_web', source: 'external_research', label: 'Current research' },
];

function toneFromFactState(state: AgentReviewFact['state']): AgentEvidenceFact['tone'] {
  switch (state) {
    case 'ok':
      return 'good';
    case 'warn':
    case 'missing':
      return 'warn';
    case 'fail':
      return 'fail';
    case 'checked':
    default:
      return 'neutral';
  }
}

function severityForFactState(state: AgentReviewFact['state']): AgentEvidenceFact['severity'] {
  if (state === 'fail') return 'block';
  if (state === 'warn' || state === 'missing') return 'warn';
  return 'info';
}

function compactValueFromFact(fact: AgentReviewFact): string {
  if (fact.message) return fact.message.length > 240 ? `${fact.message.slice(0, 237)}...` : fact.message;
  return fact.state;
}

function normalizeFactSetToEvidenceFacts(
  factSet: AgentReviewFactSet,
  requirements: AgentEvidenceRequirement[],
  walletAddress: string | undefined,
): AgentEvidenceFact[] {
  const requirementByRoute = new Map(requirements.map((req) => [req.routeId, req]));
  const evidenceFacts: AgentEvidenceFact[] = [];

  if (walletAddress) {
    const walletReq = requirementByRoute.get('wallet.connected_public_key');
    evidenceFacts.push(normalizeAgentEvidenceFact({
      id: 'fact.wallet.connected_public_key',
      routeId: 'wallet.connected_public_key',
      ...(walletReq ? { requirementId: walletReq.id } : {}),
      label: 'Connected wallet',
      value: walletAddress,
      tone: 'good',
      severity: 'info',
      source: 'wallet',
      checkedAt: new Date().toISOString(),
      ttlMs: walletReq?.ttlMs ?? Number.POSITIVE_INFINITY,
    }));
  }

  for (const mapping of FACT_SET_TO_EVIDENCE_ROUTES) {
    const fact = factSet[mapping.slot];
    if (!fact) continue;
    const req = requirementByRoute.get(mapping.routeId);
    evidenceFacts.push(normalizeAgentEvidenceFact({
      id: `fact.${mapping.slot}`,
      routeId: mapping.routeId,
      ...(req ? { requirementId: req.id } : {}),
      label: mapping.label,
      value: compactValueFromFact(fact),
      tone: toneFromFactState(fact.state),
      severity: severityForFactState(fact.state),
      source: mapping.source,
      checkedAt: fact.checkedAt,
      ttlMs: req?.ttlMs ?? Number.POSITIVE_INFINITY,
      ...(fact.detail ? { detail: fact.detail } : {}),
    }));
  }
  // The enrichers collapse per-mint Birdeye security/price and CoinGecko market data
  // into facts.tokenMint.detail.tokens[…]. The router declares birdeye.token_security,
  // birdeye.price_multi, and coingecko.token_evidence as separate required routes, so
  // the gate needs separate AgentEvidenceFacts under those routeIds — otherwise it
  // marks them missingRequired even when the data is present in the tokenMint bundle.
  emitTokenDerivedEvidenceFacts(factSet, requirementByRoute, evidenceFacts);
  return evidenceFacts;
}

function emitTokenDerivedEvidenceFacts(
  factSet: AgentReviewFactSet,
  requirementByRoute: Map<string, AgentEvidenceRequirement>,
  evidenceFacts: AgentEvidenceFact[],
): void {
  const tokenMintFact = factSet.tokenMint;
  const tokenMintDetail = asRecord(tokenMintFact?.detail);
  const tokensValue = tokenMintDetail?.tokens;
  if (!Array.isArray(tokensValue)) return;
  const tokens = tokensValue.filter(
    (entry): entry is Record<string, unknown> => Boolean(entry && typeof entry === 'object' && !Array.isArray(entry)),
  );
  if (!tokens.length) return;

  const checkedAt = tokenMintFact?.checkedAt ?? new Date().toISOString();
  const factState = tokenMintFact?.state;
  const tone: AgentEvidenceFact['tone'] =
    factState === 'fail' ? 'fail'
      : factState === 'warn' || factState === 'missing' ? 'warn'
        : 'good';
  const severity: AgentEvidenceFact['severity'] =
    factState === 'fail' ? 'block'
      : factState === 'warn' || factState === 'missing' ? 'warn'
        : 'info';

  emitTokenSecurityEvidence(tokens, requirementByRoute, evidenceFacts, checkedAt, tone, severity);
  emitTokenBirdeyePriceEvidence(tokens, requirementByRoute, evidenceFacts, checkedAt, tone, severity);
  emitTokenCoinGeckoEvidence(tokens, requirementByRoute, evidenceFacts, checkedAt, tone, severity);
}

function tokenIdentityLabel(token: Record<string, unknown>): string {
  const role = String(token.role ?? 'token').toUpperCase();
  const mint = stringField(token.mint);
  const label = stringField(token.symbol)
    ?? stringField(token.label)
    ?? (mint ? shortHexMint(mint) : 'token');
  return `${role} ${label}`;
}

function formatAuthorityState(value: unknown): string {
  if (value === null) return 'disabled';
  if (typeof value === 'string' && value.trim()) {
    const short = value.length > 8 ? `${value.slice(0, 8)}…` : value;
    return `set (${short})`;
  }
  return 'unknown';
}

function formatTokenAgeDays(ageSeconds: unknown): string {
  if (typeof ageSeconds !== 'number' || !Number.isFinite(ageSeconds) || ageSeconds < 0) {
    return 'age unknown';
  }
  if (ageSeconds < 86400) {
    const hours = Math.max(1, Math.floor(ageSeconds / 3600));
    return `age ${hours}h`;
  }
  const days = Math.floor(ageSeconds / 86400);
  return `age ${days}d`;
}

function emitTokenSecurityEvidence(
  tokens: Record<string, unknown>[],
  requirementByRoute: Map<string, AgentEvidenceRequirement>,
  evidenceFacts: AgentEvidenceFact[],
  checkedAt: string,
  tone: AgentEvidenceFact['tone'],
  severity: AgentEvidenceFact['severity'],
): void {
  const routeId = 'birdeye.token_security';
  const tokensWithSecurity = tokens.filter((token) => asRecord(token.security) !== undefined);
  if (!tokensWithSecurity.length) return;
  const req = requirementByRoute.get(routeId);
  const value = tokensWithSecurity.map((token) => {
    const security = asRecord(token.security) ?? {};
    return [
      tokenIdentityLabel(token),
      `mint ${formatAuthorityState(security.mintAuthority)}`,
      `freeze ${formatAuthorityState(security.freezeAuthority)}`,
      formatTokenAgeDays(security.ageSeconds),
    ].join(', ');
  }).join('; ');
  evidenceFacts.push(normalizeAgentEvidenceFact({
    id: 'fact.birdeye.token_security',
    routeId,
    ...(req ? { requirementId: req.id } : {}),
    label: 'Token security',
    value,
    tone,
    severity,
    source: 'birdeye',
    checkedAt,
    ttlMs: req?.ttlMs ?? Number.POSITIVE_INFINITY,
    detail: {
      tokens: tokensWithSecurity.map((token) => ({
        mint: stringField(token.mint),
        symbol: stringField(token.symbol),
        security: asRecord(token.security),
      })),
    },
  }));
}

function emitTokenBirdeyePriceEvidence(
  tokens: Record<string, unknown>[],
  requirementByRoute: Map<string, AgentEvidenceRequirement>,
  evidenceFacts: AgentEvidenceFact[],
  checkedAt: string,
  tone: AgentEvidenceFact['tone'],
  severity: AgentEvidenceFact['severity'],
): void {
  const routeId = 'birdeye.price_multi';
  const tokensWithBirdeyePrice = tokens.filter((token) => {
    const market = asRecord(token.market);
    if (!market) return false;
    return market.source === 'birdeye' && numberField(market.priceUsd) !== undefined;
  });
  if (!tokensWithBirdeyePrice.length) return;
  const req = requirementByRoute.get(routeId);
  const value = tokensWithBirdeyePrice.map((token) => {
    const market = asRecord(token.market) ?? {};
    const priceUsd = numberField(market.priceUsd)!;
    const liquidity = numberField(market.liquidityUsd);
    const pieces = [
      tokenIdentityLabel(token),
      `price ${formatUsdEstimate(priceUsd)}`,
      liquidity !== undefined ? `liquidity ${formatUsdCompact(liquidity)}` : '',
    ].filter(Boolean);
    return pieces.join(' ');
  }).join('; ');
  evidenceFacts.push(normalizeAgentEvidenceFact({
    id: 'fact.birdeye.price_multi',
    routeId,
    ...(req ? { requirementId: req.id } : {}),
    label: 'Token price (BirdEye)',
    value,
    tone,
    severity,
    source: 'birdeye',
    checkedAt,
    ttlMs: req?.ttlMs ?? Number.POSITIVE_INFINITY,
    detail: {
      tokens: tokensWithBirdeyePrice.map((token) => ({
        mint: stringField(token.mint),
        symbol: stringField(token.symbol),
        market: asRecord(token.market),
      })),
    },
  }));
}

function emitTokenCoinGeckoEvidence(
  tokens: Record<string, unknown>[],
  requirementByRoute: Map<string, AgentEvidenceRequirement>,
  evidenceFacts: AgentEvidenceFact[],
  checkedAt: string,
  tone: AgentEvidenceFact['tone'],
  severity: AgentEvidenceFact['severity'],
): void {
  const routeId = 'coingecko.token_evidence';
  const tokensWithCoinGecko = tokens.filter((token) => {
    const market = asRecord(token.market);
    if (!market) return false;
    if (market.source === 'coingecko') return true;
    return asRecord(market.coingecko) !== undefined;
  });
  if (!tokensWithCoinGecko.length) return;
  const req = requirementByRoute.get(routeId);
  const value = tokensWithCoinGecko.map((token) => {
    const market = asRecord(token.market) ?? {};
    const coingecko = asRecord(market.coingecko) ?? market;
    const priceUsd = numberField(coingecko.priceUsd) ?? numberField(market.priceUsd);
    const marketCap = numberField(coingecko.marketCapUsd) ?? numberField(market.marketCapUsd);
    const volume24h = numberField(coingecko.volume24hUsd) ?? numberField(market.volume24hUsd);
    const pieces = [
      tokenIdentityLabel(token),
      priceUsd !== undefined ? `price ${formatUsdEstimate(priceUsd)}` : '',
      marketCap !== undefined ? `mcap ${formatUsdCompact(marketCap)}` : '',
      volume24h !== undefined ? `vol24h ${formatUsdCompact(volume24h)}` : '',
    ].filter(Boolean);
    return pieces.join(' ');
  }).join('; ');
  evidenceFacts.push(normalizeAgentEvidenceFact({
    id: 'fact.coingecko.token_evidence',
    routeId,
    ...(req ? { requirementId: req.id } : {}),
    label: 'Token market evidence (CoinGecko)',
    value,
    tone,
    severity,
    source: 'coingecko',
    checkedAt,
    ttlMs: req?.ttlMs ?? Number.POSITIVE_INFINITY,
    detail: {
      tokens: tokensWithCoinGecko.map((token) => ({
        mint: stringField(token.mint),
        symbol: stringField(token.symbol),
        market: asRecord(token.market),
      })),
    },
  }));
}

interface AgentReviewEvidenceBundle {
  routePlan: AgentFactRoutePlan;
  requirements: AgentEvidenceRequirement[];
  evidenceFacts: AgentEvidenceFact[];
  gate: AgentEvidenceGateResult;
  evidenceContext: AgentEvidenceContext;
}

// Returns true when the active AI provider has a native web-research tool the device-agent
// runtime will attach in a two-pass flow:
//   - Anthropic (any model)              → AnthropicProvider.runResearchPass + web_search
//   - OpenAI gpt-5 / o-series (Native)   → OpenAiNativeProvider + web_search_preview
//   - Gemini Native                      → GeminiNativeProvider + google_search
//   - OpenRouter / Custom OpenAI-compat  → NO (chat completions has no web-search tool)
// Mirrors packages/mcp-server/src/aiPlanner.ts:supportsNativeWebResearch on the server side.
// Used by evidenceContextForReview to set `externalResearchAvailable` so the gate doesn't
// block external_research routes when the AI will resolve them via web search.
function aiProviderSupportsWebResearch(): boolean {
  const provider = (state.aiSettings.provider ?? '').trim().toLowerCase();
  const apiFormat = (state.aiSettings.apiFormat ?? '').trim().toLowerCase();
  if (apiFormat === 'anthropic') return true;
  if (apiFormat === 'openai-compatible' || apiFormat === 'openai') {
    if (provider === 'openai') return true;
    if (provider === 'gemini') return true;
    return false;
  }
  return false;
}

function evidenceContextForReview(record: GeneratedPlanRecord, plan: AgentPlan, routePlan: AgentFactRoutePlan): AgentEvidenceContext {
  const walletContext = walletContextForAgent(record);
  // Honor user-selected connector ONLY (form-supplied parameters.protocol / .connectorId /
  // .dapp / .provider / .route). Phase 5+ fix — the prior fallback to
  // findProtocolConnectorByInput(plan.route) fuzzy-matched the AI's free-text route prose
  // ("Jupiter aggregator route", "via Jupiter") and attached Jupiter as the gate's
  // selected connector even when the user picked nothing. If the user had Jupiter
  // disabled in their connector list, the gate then fired "Selected connector jupiter
  // is disabled" — blocking the entire review. Mirrors the fix already applied to
  // generatedPlanConnectorChip (main.ts:11075-11079).
  const connector = selectedConnectorForDraftParameters(plan.parameters);
  const connectorEnabled = Boolean(connector && isDappEnabled(connector.id, state.connectedDapps, state.cluster));
  const connectorReadReady = Boolean(
    connector &&
      connectorEnabled &&
      connector.readSource &&
      (!connector.requiresClientKey || state.protocolConnectorPrefs.dialectClientKey.trim()),
  );
  const connectorRoute = routePlan.routes.find((entry) => entry.id === 'protocol_connector.read_facts');
  const connectorProfile = (connectorRoute?.params?.profile as AgentConnectorProfileKind | undefined) ?? undefined;
  const draftWallet = stringField(plan.parameters.walletAddress) ?? stringField(plan.parameters.draftWallet);
  return {
    walletAddress: walletContext.address || undefined,
    ...(draftWallet ? { draftWalletAddress: draftWallet } : {}),
    cluster: record.cluster,
    ...(connector ? { connectorId: connector.id } : {}),
    ...(connectorProfile ? { connectorProfile } : {}),
    connectorEnabled: connector ? connectorEnabled : undefined,
    connectorReadReady: connector ? connectorReadReady : undefined,
    planFingerprint: planFingerprint(plan),
    isWalletScoped: true,
    enabledUserPolicyIds: enabledUserAgentPolicies().map((policy) => policy.id),
    externalResearchAvailable: aiProviderSupportsWebResearch(),
  };
}

function userControlledFieldsForReview(record: GeneratedPlanRecord, plan: AgentPlan): Array<{ name: string; value: string | undefined }> {
  const fields: Array<{ name: string; value: string | undefined }> = [
    { name: 'plan.userNotes', value: plan.userNotes },
    { name: 'record.prompt', value: record.prompt },
  ];
  if (plan.parameters) {
    for (const [key, value] of Object.entries(plan.parameters)) {
      if (typeof value === 'string') fields.push({ name: `plan.parameters.${key}`, value });
    }
  }
  const priorAnswers = record.agentReview?.answers;
  if (priorAnswers) {
    for (const [key, value] of Object.entries(priorAnswers)) {
      if (typeof value === 'string') fields.push({ name: `agentReview.answers.${key}`, value });
    }
  }
  return fields;
}

function lookupBehavioralBaseline(walletAddress: string | undefined, cluster: string): BehavioralBaseline | undefined {
  if (!walletAddress) return undefined;
  const key = baselineStorageKey(walletAddress, cluster);
  return state.behavioralBaselines[key];
}

/**
 * Collect the mints involved in a plan so the price cache can be primed. SOL is normalized
 * to the SOL_MINT_KEY sentinel; SPL mints are passed through.
 */
function planMints(plan: AgentPlan): string[] {
  const params = plan.parameters ?? {};
  const out = new Set<string>();
  // SOL: anything that looks like a SOL-denominated action.
  if (typeof params.solAmount === 'string' || typeof params.amountSol === 'string' || plan.actionType === 'transfer_sol') {
    out.add(SOL_MINT_KEY);
  }
  // SPL: scan common mint param names.
  for (const key of ['mint', 'token', 'outputMint', 'inputMint', 'reserveMint', 'assetMint', 'lstMint']) {
    const value = params[key];
    if (typeof value === 'string' && value.trim().length >= 32) out.add(value.trim());
  }
  return Array.from(out);
}

/**
 * Resolve spot prices for the plan's mints using only the in-memory cache (zero network
 * cost during this synchronous call). Stablecoins always resolve. SOL resolves if the
 * Pyth fetch in `kickPriceFetchesForPlan` populated the cache before this point. Other
 * mints rely on whatever the router already fetched.
 */
function spotPricesForPlan(plan: AgentPlan): Record<string, PriceUsdSnapshot> {
  const out: Record<string, PriceUsdSnapshot> = {};
  for (const mint of planMints(plan)) {
    const snap = getCachedUsdPrice(mint);
    if (snap) out[mint] = snap;
  }
  return out;
}

/**
 * Fire-and-forget: kick the Pyth fetch for SOL (when relevant) so the next review has
 * it cached. Stablecoins are resolved synchronously by the cache itself.
 */
function kickPriceFetchesForPlan(plan: AgentPlan): void {
  for (const mint of planMints(plan)) {
    if (isStablecoinMint(mint) || getCachedUsdPrice(mint)) continue;
    if (mint !== SOL_MINT_KEY) continue;
    void getUsdPriceForMint(mint).catch(() => undefined);
  }
}

/**
 * Best-effort SOL-lamport USD lookup for an evidence fact. Returns undefined when no
 * price is cached (either Pyth hasn't fetched yet, or this is the first review).
 */
function lamportsUsd(rawAmount: string | number | bigint | undefined, mintKey: string): number | undefined {
  if (rawAmount === undefined) return undefined;
  const snap = getCachedUsdPrice(mintKey);
  if (!snap) return undefined;
  const decimals = mintKey === SOL_MINT_KEY ? 9 : isStablecoinMint(mintKey) ? 6 : 6;
  return tokenAmountToUsd(rawAmount, decimals, snap.usdPerToken);
}

/**
 * Compute the USD-at-risk for a plan, when computable from cached prices. SOL amounts
 * use Pyth (when cached); stablecoin amounts use the $1.00 shortcut. Returns undefined
 * when the plan has no priceable amount.
 */
function planTotalUsdAtRisk(plan: AgentPlan): number | undefined {
  const params = plan.parameters ?? {};
  // SOL-denominated amount
  const solRaw = params.solAmount ?? params.amountSol;
  if (typeof solRaw === 'string' && solRaw.trim()) {
    const solNum = Number(solRaw.trim());
    if (Number.isFinite(solNum) && solNum > 0) {
      const lamports = Math.round(solNum * 1e9);
      const usd = lamportsUsd(lamports, SOL_MINT_KEY);
      if (typeof usd === 'number') return usd;
    }
  }
  // SPL amount with known mint
  const splAmount = params.amount;
  const mintCandidates = ['mint', 'token', 'reserveMint', 'assetMint', 'outputMint', 'inputMint'];
  for (const key of mintCandidates) {
    const mint = params[key];
    if (typeof mint !== 'string' || mint.length < 32) continue;
    const snap = getCachedUsdPrice(mint);
    if (!snap) continue;
    if (typeof splAmount !== 'string' || !splAmount.trim()) continue;
    const num = Number(splAmount.trim());
    if (!Number.isFinite(num) || num <= 0) continue;
    // Assume 6 decimals for stablecoins (the common case); SPL decimals are not on the
    // plan record so we default to 6 for unknown tokens. This is best-effort display only.
    const decimals = isStablecoinMint(mint) ? 6 : 6;
    return tokenAmountToUsd(Math.round(num * Math.pow(10, decimals)), decimals, snap.usdPerToken);
  }
  return undefined;
}

/**
 * Append USD annotations to amount-bearing evidence facts. Pure additive — the existing
 * native token value stays in `value`, USD is appended as "(≈$X.XX)" and stored on `usd`.
 */
function augmentEvidenceFactsWithUsd(facts: AgentEvidenceFact[], plan: AgentPlan): void {
  const totalUsd = planTotalUsdAtRisk(plan);
  for (const fact of facts) {
    if (typeof fact.usd === 'number') continue;
    // Only augment facts that look like they describe a transferable amount.
    if (fact.routeId === 'wallet.connected_public_key') continue;
    // Use the plan's total USD-at-risk for facts that summarize the wallet action.
    if (fact.id === 'fact.simulation' || fact.id === 'fact.connectorRead') continue;
    if (typeof totalUsd !== 'number') continue;
    // Heuristic: tag the route-plan summary fact + any wallet holdings fact.
    if (fact.routeId === 'birdeye.wallet_token_list' || fact.id.startsWith('fact.walletHoldings')) {
      fact.usd = totalUsd;
      fact.value = augmentValueWithUsd(fact.value, totalUsd);
    }
  }
}

const baselineUpdatedActionIds = new Set<string>();

function recordBaselineCompletion(action: PreparedAction, approvedAt: string): void {
  if (baselineUpdatedActionIds.has(action.id)) return;
  baselineUpdatedActionIds.add(action.id);
  if (!action.walletAddress) return;
  const key = baselineStorageKey(action.walletAddress, action.cluster);
  const existing = state.behavioralBaselines[key] ?? createEmptyBaseline(action.walletAddress, action.cluster, approvedAt);
  const params = action.params as Record<string, unknown> | undefined;
  const paramRecord: Record<string, string> = {};
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      if (typeof v === 'string') paramRecord[k] = v;
    }
  }
  const recipient = extractRecipientFromParameters(paramRecord);
  const amount = extractAmountFromParameters(paramRecord, action.kind);
  const next = updateBaselineFromCompletion(existing, {
    decision: 'approve',
    approvedAt,
    actionType: action.kind,
    connectorId: typeof paramRecord.connectorId === 'string' ? paramRecord.connectorId : undefined,
    ...(recipient ? { recipient } : {}),
    ...(amount ? { amountLamports: amount.amountLamports, amountTokenKey: amount.tokenKey } : {}),
  });
  state.behavioralBaselines = { ...state.behavioralBaselines, [key]: next };
  saveBehavioralBaselines();
}

function baselineFactsFor(signals: BaselineSignal[]): AgentEvidenceFact[] {
  if (!signals.length) return [];
  const checkedAt = new Date().toISOString();
  return signals.map((signal, index) => normalizeAgentEvidenceFact({
    id: `fact.baseline.${signal.kind}.${index}`,
    label: `Behavioural baseline: ${signal.label}`,
    value: signal.value,
    tone: signal.severity === 'block' ? 'fail' : signal.severity === 'warn' ? 'warn' : 'neutral',
    severity: signal.severity,
    source: 'deterministic',
    checkedAt,
    ttlMs: Number.POSITIVE_INFINITY,
    detail: { signalKind: signal.kind, ...(signal.detail ?? {}) },
  }));
}

function promptInjectionFactsFor(hits: PromptInjectionFieldHit[]): AgentEvidenceFact[] {
  if (!hits.length) return [];
  const checkedAt = new Date().toISOString();
  return hits.map((hit, index) => {
    const top = hit.detection.matches[0];
    const value = top
      ? `${top.label} (in ${hit.field}): "${top.snippet}"`
      : `Suspicious content detected in ${hit.field}.`;
    return normalizeAgentEvidenceFact({
      id: `fact.security.prompt_injection.${index}`,
      label: 'Prompt-injection attempt blocked',
      value,
      tone: 'fail',
      severity: hit.detection.highestSeverity === 'block' ? 'block' : 'warn',
      source: 'deterministic',
      checkedAt,
      ttlMs: Number.POSITIVE_INFINITY,
      detail: {
        field: hit.field,
        matches: hit.detection.matches,
      },
    });
  });
}

function buildAgentReviewEvidenceBundle(
  record: GeneratedPlanRecord,
  plan: AgentPlan,
  factSet: AgentReviewFactSet,
): AgentReviewEvidenceBundle {
  // Best-effort: warm the price cache (Pyth SOL) in the background so subsequent reviews
  // and the USD-suffix augmentation below have data. Stablecoins resolve synchronously
  // via the cache so no fetch fires for them.
  kickPriceFetchesForPlan(plan);
  const routePlanFact = factSet.evidenceRoutes;
  const routePlan: AgentFactRoutePlan = routePlanFactToRoutePlan(routePlanFact) ?? planFactRoutesForAgentReview(record, plan, {});
  const evidenceContext = evidenceContextForReview(record, plan, routePlan);
  const requirements = buildEvidenceRequirements(routePlan, evidenceContext);
  const evidenceFacts = normalizeFactSetToEvidenceFacts(factSet, requirements, evidenceContext.walletAddress);
  augmentEvidenceFactsWithUsd(evidenceFacts, plan);
  // Layer 1: scan user-controlled text for prompt-injection attempts. Each match becomes a
  // blocking evidence fact so the existing gate denies the approval (no AI consultation
  // can override a block-severity fact).
  const injectionHits = detectPromptInjectionInFields(userControlledFieldsForReview(record, plan));
  evidenceFacts.push(...promptInjectionFactsFor(injectionHits));

  // Behavioural baseline signals: compare the plan against the wallet's historical norms.
  // These default to severity 'warn' / 'info' — they SURFACE patterns to the AI reviewer
  // (and the audit receipt) rather than auto-deny. Users wanting hard blocks can add a
  // dedicated policy.
  const baseline = lookupBehavioralBaseline(evidenceContext.walletAddress, evidenceContext.cluster ?? record.cluster);
  if (baseline) {
    const baselineSignals = evaluateBaselineSignals(baseline, {
      actionType: plan.actionType,
      connectorId: evidenceContext.connectorId,
      recipient: extractRecipientFromParameters(plan.parameters),
      ...(extractAmountFromParameters(plan.parameters, plan.actionType) ?? {}),
    });
    evidenceFacts.push(...baselineFactsFor(baselineSignals));
  }

  const gate = evaluateAgentEvidenceGate(requirements, evidenceFacts, evidenceContext);
  return { routePlan, requirements, evidenceFacts, gate, evidenceContext };
}

function routePlanFactToRoutePlan(fact: AgentReviewFact | undefined): AgentFactRoutePlan | undefined {
  if (!fact?.detail) return undefined;
  const detail = fact.detail as { routes?: unknown; skipped?: unknown };
  if (!Array.isArray(detail.routes)) return undefined;
  const routes = detail.routes
    .filter((row): row is Record<string, unknown> => Boolean(row) && typeof row === 'object')
    .map((row) => ({
      id: String(row.id ?? ''),
      need: row.need as AgentFactRoute['need'],
      provider: row.provider as AgentFactRoute['provider'],
      endpoint: String(row.endpoint ?? ''),
      status: (row.status === 'optional' ? 'optional' : 'required') as AgentFactRoute['status'],
      reason: String(row.reason ?? ''),
      ...(row.params && typeof row.params === 'object' && !Array.isArray(row.params)
        ? { params: row.params as Record<string, string | number | boolean> }
        : {}),
    }))
    .filter((row) => row.id);
  const skipped = Array.isArray(detail.skipped)
    ? (detail.skipped as Array<{ need: AgentFactNeed; reason: string }>)
    : [];
  return { routes, skipped, routeText: typeof fact.message === 'string' ? fact.message : '' };
}

function routePlanHasAnyNeed(routePlan: AgentFactRoutePlan, needs: AgentFactNeed[]): boolean {
  return routePlan.routes.some((route) => needs.includes(route.need));
}

function routePlanHasAnyId(routePlan: AgentFactRoutePlan, ids: string[]): boolean {
  return routePlan.routes.some((route) => ids.includes(route.id));
}

function routePlanRoute(routePlan: AgentFactRoutePlan, id: string): AgentFactRoute | undefined {
  return routePlan.routes.find((route) => route.id === id);
}

async function enrichWalletFactsForAgent(
  record: GeneratedPlanRecord,
  facts: AgentReviewFactSet,
  routePlan: AgentFactRoutePlan,
): Promise<void> {
  const wallet = walletContextForAgent(record).address;
  if (!wallet) return;
  await Promise.all([
    routePlanHasAnyNeed(routePlan, ['wallet_transfers'])
      ? enrichWalletTransferFacts(wallet, facts)
      : Promise.resolve(),
    routePlanHasAnyNeed(routePlan, ['wallet_holdings'])
      ? enrichWalletHoldingsFacts(wallet, facts)
      : Promise.resolve(),
  ]);
}

function extractPreparedTxBase64(record: GeneratedPlanRecord): string | undefined {
  if (!record.preparedActionId) return undefined;
  const action = state.preparedActions.find((entry) => entry.id === record.preparedActionId);
  if (!action) return undefined;
  const raw = (action.params as Record<string, unknown> | undefined)?.transactionBase64;
  return typeof raw === 'string' && raw.trim() ? raw : undefined;
}

async function enrichSimulationFactsForAgent(
  record: GeneratedPlanRecord,
  plan: AgentPlan,
  facts: AgentReviewFactSet,
  routePlan: AgentFactRoutePlan,
): Promise<void> {
  const route = routePlanRoute(routePlan, 'rpc.simulate_transaction');
  if (!route) return;
  const checkedAt = new Date().toISOString();
  const txBase64 = extractPreparedTxBase64(record);
  if (!txBase64) {
    facts.simulation = {
      state: route.status === 'required' ? 'warn' : 'missing',
      source: 'deterministic',
      checkedAt,
      message: 'Simulation requested but no serialized transaction is on the record yet.',
      detail: { routeStatus: route.status, routeReason: route.reason },
    };
    return;
  }

  const walletAddress = walletContextForAgent(record).address ?? '';
  try {
    const bytes = base64ToUint8Array(txBase64);
    const versioned = tryDeserializeVersionedTx(bytes);
    const legacy = versioned ? undefined : tryDeserializeLegacyTx(bytes);
    if (!versioned && !legacy) {
      throw new Error('Could not deserialize transaction bytes.');
    }
    const writableProgramIds = collectWritableProgramIds(versioned ?? legacy!);
    const connection = browserActionConnection(record.cluster);
    const simResult = versioned
      ? await connection.simulateTransaction(versioned, { sigVerify: false, replaceRecentBlockhash: true })
      : await connection.simulateTransaction(legacy!, undefined, false);
    const evaluation = evaluateSimulationOutcome({
      result: {
        err: simResult.value.err,
        logs: simResult.value.logs ?? null,
        accounts: simResult.value.accounts ?? null,
        unitsConsumed: simResult.value.unitsConsumed ?? null,
      },
      preWalletLamports: null,
      postWalletLamports: null,
      walletAddress,
      planSolLamports: planAmountSolLamports(plan),
      writableProgramIds,
    });
    facts.simulation = {
      state: evaluation.state,
      source: 'deterministic',
      checkedAt,
      message: evaluation.summary,
      detail: {
        ...evaluation.detail,
        routeStatus: route.status,
        routeReason: route.reason,
      },
    };
  } catch (err) {
    facts.simulation = {
      state: route.status === 'required' ? 'warn' : 'missing',
      source: 'deterministic',
      checkedAt,
      message: `Simulation could not run: ${redactSecrets(err instanceof Error ? err.message : String(err))}`,
      detail: { routeStatus: route.status, routeReason: route.reason },
    };
  }
}

function tryDeserializeVersionedTx(bytes: Uint8Array): VersionedTransaction | undefined {
  try {
    return VersionedTransaction.deserialize(bytes);
  } catch {
    return undefined;
  }
}

function tryDeserializeLegacyTx(bytes: Uint8Array): Transaction | undefined {
  try {
    return Transaction.from(bytes);
  } catch {
    return undefined;
  }
}

function collectWritableProgramIds(tx: VersionedTransaction | Transaction): string[] {
  const ids = new Set<string>();
  if (tx instanceof VersionedTransaction) {
    const message = tx.message;
    const staticKeys = message.staticAccountKeys.map((k) => k.toBase58());
    for (const ix of message.compiledInstructions) {
      const programKey = staticKeys[ix.programIdIndex];
      if (programKey) ids.add(programKey);
    }
  } else {
    for (const ix of tx.instructions) {
      ids.add(ix.programId.toBase58());
    }
  }
  return Array.from(ids);
}

function planAmountSolLamports(plan: AgentPlan): number | null {
  const candidates = [plan.parameters?.solAmount, plan.parameters?.amountSol, plan.parameters?.amount];
  for (const value of candidates) {
    if (typeof value === 'string' && value.trim()) {
      const num = Number(value.trim());
      if (Number.isFinite(num) && num >= 0) return Math.round(num * 1e9);
    }
  }
  return null;
}

function base64ToUint8Array(value: string): Uint8Array {
  if (typeof atob === 'function') {
    const binary = atob(value);
    const out = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
    return out;
  }
  return Uint8Array.from(Buffer.from(value, 'base64'));
}

async function enrichConnectorFactsForAgent(
  record: GeneratedPlanRecord,
  plan: AgentPlan,
  facts: AgentReviewFactSet,
  routePlan: AgentFactRoutePlan,
): Promise<void> {
  const route = routePlanRoute(routePlan, 'protocol_connector.read_facts');
  if (!route) return;
  const checkedAt = new Date().toISOString();
  const connector = selectedConnectorForDraftParameters(plan.parameters) ??
    findProtocolConnectorByInput(plan.parameters.protocol || plan.parameters.dapp || plan.route);
  if (!connector) {
    facts.connectorRead = {
      state: route.status === 'required' ? 'warn' : 'missing',
      source: 'deterministic',
      checkedAt,
      message: 'Connector read facts were selected, but no matching connector was found.',
      detail: { routeStatus: route.status },
    };
    return;
  }
  const request = connectorReadFactsRequestForAgent(record, plan, connector, route);
  try {
    const response = await fetchConnectorFactsForAgent(record, request);
    const rows = compactConnectorReadFactRows(response);
    const capability = stringField(request.capability) ?? stringField(route.params?.capability) ?? 'facts';
    facts.connectorRead = {
      state: rows.length ? 'ok' : 'checked',
      source: 'deterministic',
      checkedAt,
      message: connectorReadFactMessage(connector.name, capability, rows),
      detail: {
        provider: 'protocol_connector',
        connectorId: connector.id,
        connectorName: connector.name,
        connectorWebsite: connector.website,
        capability,
        routeStatus: route.status,
        routeReason: route.reason,
        request: compactConnectorReadRequest(request),
        factCount: rows.length,
        facts: rows.slice(0, 12),
        response: compactConnectorReadResponse(response),
      },
    };
  } catch (err) {
    facts.connectorRead = {
      state: route.status === 'required' ? 'warn' : 'missing',
      source: 'deterministic',
      checkedAt,
      message: `${connector.name} connector facts unavailable: ${redactSecrets(err instanceof Error ? err.message : String(err))}`,
      detail: {
        provider: 'protocol_connector',
        connectorId: connector.id,
        connectorName: connector.name,
        connectorWebsite: connector.website,
        routeStatus: route.status,
        routeReason: route.reason,
        request: compactConnectorReadRequest(request),
      },
    };
  }
}

